function BuybackActionForm({
  kind,
  rows,
  onDone,
}: {
  kind: ActionKind
  rows: BuybackChainState[]
  onDone: () => void
}) {
  const action = ACTIONS[kind]
  const batch = useSafeBatch()
  const available = useMemo(
    () => rows.filter(row => isKindAvailable(kind, row)),
    [kind, rows],
  )
  const [selected, setSelected] = useState<Set<number>>(
    () => new Set(available.map(row => row.chainId)),
  )
  const [addresses, setAddresses] = useState<Record<number, string>>(() =>
    Object.fromEntries(
      available.map(row => [
        row.chainId,
        kind === 'hook'
          ? row.defaultHook ?? ''
          : kind === 'terminal'
            ? row.defaultTerminal ?? ''
            : // Pre-select the pool the chain already has, so a TWAP edit targets
              // an initialized pair instead of a native pool a USDC revnet never
              // had. Native pools read back as address(0); show the sentinel.
              kind === 'twap' && row.pools[0] && row.pools[0].token !== zeroAddress
              ? row.pools[0].token
              : NATIVE_TOKEN,
      ]),
    ),
  )
  const [fee, setFee] = useState('3000')
  const [tickSpacing, setTickSpacing] = useState('60')
  const [twapWindow, setTwapWindow] = useState(() =>
    kind === 'twap' ? String(available[0]?.pools[0]?.twap ?? 1800) : '1800',
  )
  const [sqrtPriceX96, setSqrtPriceX96] = useState('')
  const [ack, setAck] = useState(false)
  const [review, setReview] = useState<Review | null>(null)
  const [busy, setBusy] = useState(false)
  const [status, setStatus] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [done, setDone] = useState(false)

  useEffect(() => {
    setReview(null)
    setAck(false)
  }, [selected, addresses, fee, tickSpacing, twapWindow, sqrtPriceX96])

  const closeReview = () => {
    if (busy) return
    setReview(null)
    setError(null)
    if (done) onDone()
  }

  /** The exact calls the submit would send, or null after reporting why not. */
  const buildPlan = (): Review | null => {
    setError(null)
    const chosen = available.filter(row => selected.has(row.chainId))
    if (!chosen.length) {
      setError('Choose at least one available chain.')
      return null
    }
    try {
      let poolValues: {
        fee: number
        tickSpacing: number
        twapWindow: number
        sqrtPriceX96: bigint
      } | null = null
      if (kind === 'pool') {
        if (![fee, tickSpacing, twapWindow, sqrtPriceX96].every(v => /^\d+$/.test(v))) {
          throw new Error('Fee, tick spacing, TWAP window, and price must be whole numbers.')
        }
        const parsed = {
          fee: Number(fee),
          tickSpacing: Number(tickSpacing),
          twapWindow: Number(twapWindow),
          sqrtPriceX96: BigInt(sqrtPriceX96),
        }
        if (parsed.fee < 0 || parsed.fee > 0xffffff) {
          throw new Error('Fee must fit uint24.')
        }
        if (parsed.tickSpacing < 1 || parsed.tickSpacing > 0x7fffff) {
          throw new Error('Tick spacing must be a positive int24 value.')
        }
        // Pool registration runs the SAME `_requireValidTwapWindow` bound the
        // standalone TWAP edit does; the uint32 range let an out-of-bounds
        // value through review and the danger acknowledgement, only to die in
        // the pre-flight eth_call with a raw JBBuybackHook_InvalidTwapWindow.
        if (
          parsed.twapWindow < MIN_TWAP_WINDOW ||
          parsed.twapWindow > MAX_TWAP_WINDOW
        ) {
          throw new Error(
            `The hook only accepts a TWAP window between ${MIN_TWAP_WINDOW} and ${MAX_TWAP_WINDOW} seconds.`,
          )
        }
        if (parsed.sqrtPriceX96 <= 0n || parsed.sqrtPriceX96 >= 2n ** 160n) {
          throw new Error('Initial price must be a positive uint160 value.')
        }
        poolValues = parsed
      }
      let newTwapWindow = 0
      if (kind === 'twap') {
        if (!/^\d+$/.test(twapWindow)) {
          throw new Error('Enter the TWAP window in whole seconds.')
        }
        newTwapWindow = Number(twapWindow)
        if (newTwapWindow < MIN_TWAP_WINDOW || newTwapWindow > MAX_TWAP_WINDOW) {
          throw new Error(
            `The hook only accepts a TWAP window between ${MIN_TWAP_WINDOW} and ${MAX_TWAP_WINDOW} seconds.`,
          )
        }
      }

      const calls: AuthorityCall[] = []
      const reviewRows: TxConfirmRow[] = []
      const steps: BatchStep[] = []
      for (const row of chosen) {
        if (!row.authority) throw new Error(`${row.name}: owner/operator is unknown.`)
        const input = addresses[row.chainId] ?? ''
        const address = resolvedAddress(input)
        if (!address) {
          throw new Error(
            `${row.name}: enter a valid ${action.fieldLabel.toLowerCase()} address.`,
          )
        }

        if (kind === 'hook') {
          if (!row.buybackRegistry) throw new Error(`${row.name}: no buyback registry.`)
          calls.push(
            buildBuybackHookAuthorityCall({
              chainId: row.chainId,
              authority: row.authority,
              registry: row.buybackRegistry,
              projectId: BigInt(row.projectId),
              hook: address,
              gas: action.gas,
              label: action.title,
            }),
          )
          steps.push(
            buildStep({
              kind: 'setHookFor',
              chainId: row.chainId,
              projectId: row.projectId,
              values: { hook: address },
            }),
          )
        } else if (kind === 'terminal') {
          if (!row.routerRegistry) throw new Error(`${row.name}: no router registry.`)
          calls.push(
            buildRouterTerminalAuthorityCall({
              chainId: row.chainId,
              authority: row.authority,
              registry: row.routerRegistry,
              projectId: BigInt(row.projectId),
              terminal: address,
              gas: action.gas,
              label: action.title,
            }),
          )
          steps.push(
            buildStep({
              kind: 'setTerminalFor',
              chainId: row.chainId,
              projectId: row.projectId,
              values: { terminal: address },
            }),
          )
        } else if (kind === 'twap') {
          // The registry has no setTwapWindowOf forwarder — the write goes to
          // the project's resolved hook.
          if (!row.hook) throw new Error(`${row.name}: no buyback hook set.`)
          calls.push(
            buildSetBuybackTwapAuthorityCall({
              chainId: row.chainId,
              authority: row.authority,
              hook: row.hook,
              projectId: BigInt(row.projectId),
              terminalToken: address,
              twapWindow: BigInt(newTwapWindow),
              gas: action.gas,
              label: action.title,
            }),
          )
          steps.push(
            buildStep({
              kind: 'setTwapWindowOf',
              chainId: row.chainId,
              projectId: row.projectId,
              values: {
                hook: row.hook,
                terminalToken: address,
                twapWindow: BigInt(newTwapWindow),
              },
            }),
          )
        } else {
          if (!row.buybackRegistry || !poolValues) {
            throw new Error(`${row.name}: no buyback registry.`)
          }
          calls.push(
            buildInitializeBuybackPoolAuthorityCall({
              chainId: row.chainId,
              authority: row.authority,
              registry: row.buybackRegistry,
              projectId: BigInt(row.projectId),
              fee: poolValues.fee,
              tickSpacing: poolValues.tickSpacing,
              twapWindow: BigInt(poolValues.twapWindow),
              pairToken: address,
              sqrtPriceX96: poolValues.sqrtPriceX96,
              gas: action.gas,
              label: action.title,
            }),
          )
          steps.push(
            buildStep({
              kind: 'initializePoolFor',
              chainId: row.chainId,
              projectId: row.projectId,
              values: {
                fee: poolValues.fee,
                tickSpacing: poolValues.tickSpacing,
                twapWindow: BigInt(poolValues.twapWindow),
                pairToken: address,
                sqrtPriceX96: poolValues.sqrtPriceX96,
              },
            }),
          )
        }
        reviewRows.push({
          label: row.name,
          mono: true,
          value: `${truncateAddress(address)}${
            kind === 'pool'
              ? ` | fee ${fee} | spacing ${tickSpacing} | TWAP ${twapWindow}s | price ${sqrtPriceX96}`
              : kind === 'twap'
                ? ` | TWAP ${
                    row.pools.find(
                      pool => sameToken(pool.token, address),
                    )?.twap ?? '—'
                  }s → ${twapWindow}s`
                : ''
          }`,
        })
      }
      reviewRows.push({ label: 'On', value: chosen.map(row => row.name).join(', ') })
      return { calls, rows: reviewRows, steps }
    } catch (reviewError) {
      setError(
        reviewError instanceof Error
          ? reviewError.message
          : 'Could not review this action.',
      )
      return null
    }
  }

  const buildReview = () => {
    const plan = buildPlan()
    if (!plan) return
    setStatus(null)
    setDone(false)
    setReview(plan)
  }

  const addToBatch = () => {
    const plan = buildPlan()
    if (!plan || !batch) return
    batch.queue(plan.steps)
    onDone()
  }

  const submit = async () => {
    if (!review || !ack || busy) return
    setBusy(true)
    setError(null)
    try {
      const result = await runAuthorityCalls({
        calls: review.calls,
        onProgress: progress => setStatus(progress.message),
      })
      setStatus(
        safeOutcomeMessage(
          result,
          `${action.title} completed on ${review.calls.length} chain${
            review.calls.length === 1 ? '' : 's'
          }.`,
        ),
      )
      setDone(true)
    } catch (submitError) {
      setError(
        submitError instanceof Error
          ? submitError.message
          : 'Could not complete this action.',
      )
    } finally {
      setBusy(false)
    }
  }

  return (
    <div>
      <ChainPicker
        label="Run on"
        rows={rows.map(row => ({
          chainId: row.chainId,
          name: row.name,
          disabled: !isKindAvailable(kind, row),
        }))}
        selected={selected}
        onChange={setSelected}
        disabled={busy}
      />

      <PerChainAddressField
        className="mt-4"
        fieldLabel={action.fieldLabel}
        rows={available}
        selected={selected}
        values={addresses}
        onChange={setAddresses}
        disabled={busy}
      >
        {kind === 'pool' || kind === 'twap' ? (
          <p className="mt-2 text-xs leading-relaxed text-smoke-500">
            Use the native-token sentinel for native ETH pools. USDC and other
            pair-token addresses may differ by chain.
          </p>
        ) : null}
      </PerChainAddressField>

      {kind === 'twap' ? (
        <div className="mt-4 sm:max-w-xs">
          <NumberField
            label="TWAP window (seconds)"
            note={PROTOCOL_CONCEPTS.twapWindow}
            value={twapWindow}
            onChange={setTwapWindow}
            disabled={busy}
            placeholder="1800 = 30 min"
          />
        </div>
      ) : null}

      {kind === 'pool' ? (
        <div className="mt-4 grid gap-3 sm:grid-cols-2">
          <NumberField
            label="Fee (hundredths of a bip)"
            value={fee}
            onChange={setFee}
            disabled={busy}
            placeholder="3000 = 0.3%"
          />
          <NumberField
            label="Tick spacing"
            value={tickSpacing}
            onChange={setTickSpacing}
            disabled={busy}
            placeholder="60 for a 0.3% pool"
          />
          <NumberField
            label="TWAP window (seconds)"
            note={PROTOCOL_CONCEPTS.twapWindow}
            value={twapWindow}
            onChange={setTwapWindow}
            disabled={busy}
            placeholder="1800"
          />
          <NumberField
            label="Initial price (sqrtPriceX96)"
            value={sqrtPriceX96}
            onChange={setSqrtPriceX96}
            disabled={busy}
            placeholder="positive uint160"
          />
        </div>
      ) : null}

      <label className="mt-4 flex items-start gap-2 rounded-lg border border-red-300 bg-red-50 p-3">
        <input
          type="checkbox"
          checked={ack}
          onChange={event => setAck(event.target.checked)}
          disabled={busy}
          className="mt-0.5 accent-red-600"
        />
        <span className="text-xs leading-relaxed text-red-700">
          I verified every selected chain and value. {action.danger}
        </span>
      </label>

      <div className="mt-3 flex flex-wrap items-center gap-2">
        <button
          type="button"
          onClick={buildReview}
          disabled={busy || !selected.size || !ack}
          className="btn-primary min-h-[44px] flex-1 text-sm"
        >
          {action.title}
        </button>
        {batch ? (
          <button
            type="button"
            onClick={addToBatch}
            disabled={busy || !selected.size || !ack}
            className="btn-secondary min-h-[44px] px-4 text-sm"
          >
            Add to batch
          </button>
        ) : null}
      </div>
      {error && !review ? <ErrorNote message={error} /> : null}
      {review ? (
        <TxConfirmDialog
          open
          title={done ? `${action.title} complete` : `Confirm ${action.title.toLowerCase()}`}
          rows={review.rows}
          steps={review.calls.map(call => ({
            key: String(call.chainId),
            title: `${action.title} on ${chainName(call.chainId)}`,
          }))}
          activeIndex={busy ? 0 : -1}
          status={status}
          error={error}
          busy={busy}
          complete={done}
          action={error ? 'Retry' : action.title}
          onConfirm={() => void submit()}
          onClose={closeReview}
        />
      ) : null}
    </div>
  )
}

function NumberField({
  label,
  value,
  onChange,
  disabled,
  placeholder,
  note,
}: {
  label: string
  value: string
  onChange: (value: string) => void
  disabled: boolean
  placeholder: string
  /** What the field MEANS, for a term the operator may not know. */
  note?: string
}) {
  return (
    <label className="block">
      <span className="field-label">
        {note ? <ConceptTerm note={note}>{label}</ConceptTerm> : label}
      </span>
      <input
        type="text"
        inputMode="numeric"
        value={value}
        onChange={event => onChange(event.target.value.replace(/[^0-9]/g, ''))}
        disabled={disabled}
        placeholder={placeholder}
        className="input-well mt-1.5 min-h-[42px] w-full px-3 text-sm tabular-nums disabled:opacity-60"
      />
    </label>
  )
}

import { NATIVE_TOKEN, type JBChainId } from '@bananapus/nana-sdk-core'
import {
  buildCashOutTx,
  cashOutPoolBufferBps as sdkCashOutPoolBufferBps,
  cashOutProtocolFee,
  classifyCashOutExecutionError,
  getAccountingContexts,
  getCashOutQuote,
  type CashOutQuote,
  type CashOutRoute,
  type JBAccountingContext,
  type V6CashOutTxRequest,
} from '@bananapus/nana-sdk-core/v6'
import { formatUnits, type Address, type PublicClient } from 'viem'
import { formatTokenAmount } from '@/lib/format'

/**
 * Pure cash-out plumbing shared by the TreasuryCard client island and the
 * verification scripts: accounting-context resolution, quoting in the
 * project's own accounting terms, and tx-request assembly from an SDK
 * slippage-protected route (getHookAwareCashOutQuote/resolveCashOutRoute).
 */

export function isNativeToken(token: string): boolean {
  return token.toLowerCase() === NATIVE_TOKEN.toLowerCase()
}

/** Pool fee/impact buffer already reflected in the hook's executable quote. */
export function cashOutPoolBufferBps(
  route: CashOutRoute | undefined,
): number | null {
  const buffer = sdkCashOutPoolBufferBps(route)
  return buffer === null ? null : Number(buffer)
}

/**
 * Plain-language disclosure for the mandatory review when the minimum being
 * signed is worse than the one on screen.
 *
 * Every cash-out flow re-quotes at submit and floors the SENT minimum from the
 * fresh number, while the panel keeps showing the render-time one. The exact
 * payload review does render the fresh argument, but as raw fixed point — no
 * tolerance band applies here, so any drop at all gets named in words, with
 * both figures, before a signature is requested.
 *
 * Returns undefined when the minimum held or improved.
 */
export function minimumDropNotice({
  displayedMinimum,
  freshMinimum,
  decimals,
  symbol,
}: {
  displayedMinimum: bigint | null | undefined
  freshMinimum: bigint
  decimals: number
  symbol: string
}): string | undefined {
  if (displayedMinimum === null || displayedMinimum === undefined) return
  if (freshMinimum >= displayedMinimum) return
  const [was, now] = distinctAmounts(displayedMinimum, freshMinimum, decimals)
  return (
    `The amount you'd receive dropped since you reviewed: was at least ` +
    `${was} ${symbol}, now at least ${now} ${symbol}. ` +
    `Approve only if the new amount still works for you — otherwise close this ` +
    `and start over with a fresh quote.`
  )
}

/**
 * Two amounts rendered so the drop is actually visible: display rounding (and,
 * past ~15 significant digits, JS number precision) can print two different
 * amounts identically, which would turn the warning into nonsense. Widen the
 * precision until they differ, falling back to the exact fixed-point strings.
 */
function distinctAmounts(
  left: bigint,
  right: bigint,
  decimals: number,
): [string, string] {
  for (const digits of [4, 6, 9, 12]) {
    const a = formatTokenAmount(left, decimals, digits)
    const b = formatTokenAmount(right, decimals, digits)
    if (a !== b) return [a, b]
  }
  return [formatUnits(left, decimals), formatUnits(right, decimals)]
}

export function cashOutExecutionErrorMessage(error: unknown): string {
  const classified = classifyCashOutExecutionError(error)
  if (classified?.code === 'BUYBACK_SLIPPAGE_EXCEEDED') {
    return 'The buyback pool moved below your protected minimum. Refresh the quote or choose a larger max slippage, then try again.'
  }
  if (classified?.code === 'TERMINAL_UNDER_MIN') {
    return 'The project cash-out fell below your protected minimum. Refresh the quote and try again.'
  }
  return error instanceof Error ? error.message : 'Something went wrong.'
}

/**
 * Net an ambient (display-only) reclaim quote of the exact protocol fee the
 * terminal deducts: with a non-zero cash-out tax the 2.5% fee (floor of
 * `gross / 40`) applies to the full reclaim; with a zero tax it applies only
 * up to the project's `feeFreeSurplusOf` counter. Callers that could not
 * read that counter should pass `gross` (conservative: full fee).
 */
export function netOfCashOutFee({
  gross,
  cashOutTaxRate,
  feeFreeSurplus,
}: {
  gross: bigint
  cashOutTaxRate: bigint
  feeFreeSurplus: bigint
}): bigint {
  const fee = cashOutProtocolFee({
    reclaimAmount: gross,
    cashOutTaxRate,
    feeFreeSurplus,
  })
  return gross > fee ? gross - fee : 0n
}

/**
 * Resolve the project's accounting context — the token its treasury is
 * accounted in. The first registered context is the accounting token; do NOT
 * assume native (USDC-accounting projects exist, e.g. Artizen on Base).
 */
export async function getCashOutContext(
  client: PublicClient,
  { chainId, projectId }: { chainId: JBChainId; projectId: bigint },
): Promise<JBAccountingContext | null> {
  const contexts = await getAccountingContexts(client, { chainId, projectId })
  return contexts[0] ?? null
}

/**
 * Quote a cash-out in the accounting context's own terms (its decimals and
 * token-keyed currency), so no price-feed conversion is involved.
 *
 * Hook-blind (`currentReclaimableSurplusOf` skips data hooks) — display-only.
 * Transactions must quote through the SDK's `getHookAwareCashOutQuote`.
 *
 * `reclaimAmountAfterFee` is only populated when the fee-gating inputs are
 * supplied: the ruleset's `cashOutTaxRate`, plus the terminal's
 * `feeFreeSurplusOf` when that rate is zero. Omit them and the SDK returns
 * `undefined` for the net rather than fabricating one — callers must render
 * that as unknown, never as zero and never as the gross.
 */
export function getContextCashOutQuote(
  client: PublicClient,
  {
    chainId,
    projectId,
    cashOutCount,
    context,
    cashOutTaxRate,
    feeFreeSurplus,
  }: {
    chainId: JBChainId
    projectId: bigint
    /** Project tokens to cash out, fixed-point 18 decimals. */
    cashOutCount: bigint
    context: JBAccountingContext
    cashOutTaxRate?: bigint
    feeFreeSurplus?: bigint
  },
): Promise<CashOutQuote> {
  return getCashOutQuote(client, {
    chainId,
    projectId,
    cashOutCount,
    decimals: BigInt(context.decimals),
    currency: BigInt(context.currency),
    cashOutTaxRate,
    feeFreeSurplus,
  })
}

/**
 * The current per-token cash-out price from an omnichain revnet's aggregate
 * surplus and token supply. This mirrors JBCashOuts.cashOutFrom's staged
 * integer arithmetic for one 18-decimal project token:
 *
 * balance × share × ((1 - tax) + tax × share)
 *
 * Keeping every division in the contract's order matters: collapsing the
 * expression into one fraction can round up a value the contract rounds down.
 */
export function cashOutPriceFromTotals({
  balance,
  tokenSupply,
  cashOutTaxRate,
  balanceDecimals,
}: {
  balance: bigint
  tokenSupply: bigint
  /** Basis points, out of 10,000. */
  cashOutTaxRate: number
  balanceDecimals: number
}): number | null {
  if (balance <= 0n || tokenSupply <= 0n) return null

  const oneToken = 10n ** 18n
  const tax = BigInt(Math.max(0, Math.min(10_000, cashOutTaxRate)))
  if (tax === 10_000n) return null
  if (oneToken >= tokenSupply) {
    const value = Number(formatUnits(balance, balanceDecimals))
    return Number.isFinite(value) && value > 0 ? value : null
  }

  const base = (balance * oneToken) / tokenSupply
  const rawPrice =
    tax === 0n
      ? base
      : (base * (10_000n - tax + (tax * oneToken) / tokenSupply)) / 10_000n
  if (rawPrice <= 0n) return null

  // GROSS by design: this mirrors JBCashOuts.cashOutFrom exactly (see the test pinning the
  // staged arithmetic). The protocol fee is applied by the DISPLAY layer via
  // `netOfCashOutFee`, so this stays a faithful contract mirror.
  const value = Number(formatUnits(rawPrice, balanceDecimals))
  return Number.isFinite(value) && value > 0 ? value : null
}

/**
 * The current cash-out curve's backing asymptote:
 * (1 - tax) × balance ÷ supply.
 *
 * The one-token quote is slightly above this value because it includes that
 * token's quadratic share term. As supply grows, the quote approaches this
 * value. This is distinct from the payment asymptote shown on the chart.
 */
export function minimumCashOutPriceFromTotals({
  balance,
  tokenSupply,
  cashOutTaxRate,
  balanceDecimals,
}: {
  balance: bigint
  tokenSupply: bigint
  /** Basis points, out of 10,000. */
  cashOutTaxRate: number
  balanceDecimals: number
}): number | null {
  if (balance <= 0n || tokenSupply <= 0n) return null

  const oneToken = 10n ** 18n
  const tax = BigInt(Math.max(0, Math.min(10_000, cashOutTaxRate)))
  const rawPrice =
    (balance * oneToken * (10_000n - tax)) /
    (tokenSupply * 10_000n)
  if (rawPrice <= 0n) return null

  const value = Number(formatUnits(rawPrice, balanceDecimals))
  return Number.isFinite(value) && value > 0 ? value : null
}

/**
 * Long-run cash-out price after payments at the current issuance price. GROSS of the
 * protocol fee — net it at the display layer with {@link netCashOutDisplayValue}.
 */
export function minimumCashOutPriceAtIssuancePrice(
  issuancePrice: number,
  cashOutTaxRate: number,
): number | null {
  if (!Number.isFinite(issuancePrice) || issuancePrice <= 0) return null
  const tax = Math.max(0, Math.min(10_000, cashOutTaxRate))
  return issuancePrice * (1 - tax / 10_000)
}

/**
 * Net an ambient DISPLAY value of the protocol cash-out fee.
 *
 * The pure quote helpers above mirror the contract and are deliberately gross; every surface
 * a holder reads to decide when to sell must show what they would actually RECEIVE, matching
 * the confirm modal. `feeFreeSurplusOf` is unavailable to these display paths, so the fee is
 * assumed fully applicable — understating proceeds is the safe direction.
 */
export function netCashOutDisplayValue(
  value: number | null | undefined,
  cashOutTaxRate: number | undefined,
): number | null {
  if (value === null || value === undefined || !Number.isFinite(value)) return null
  // A zero-tax project is fee-free up to feeFreeSurplusOf; without that counter the fee
  // still cannot be ruled out, so it is applied either way.
  void cashOutTaxRate
  return value - value / 40
}

/** Show the payment asymptote only when paid issuance can pull the live quote down toward it. */
export function shouldShowCashOutAsymptote(
  cashOutPrice: number | undefined,
  asymptote: number | undefined,
): boolean {
  return (
    cashOutPrice !== undefined &&
    asymptote !== undefined &&
    Number.isFinite(cashOutPrice) &&
    Number.isFinite(asymptote) &&
    cashOutPrice > 0 &&
    asymptote > 0 &&
    cashOutPrice > asymptote
  )
}

/**
 * Assemble the `cashOutTokensOf` request from an SDK slippage-protected
 * route: the route's terminal minimum and metadata carry the floor (in
 * `minTokensReclaimed` on the treasury route, in the buyback hook metadata
 * on the pool route). Throws when the route's floor is zero — an
 * unprotected cash-out must never be sent.
 */
export function buildCashOutRequest({
  chainId,
  terminal,
  holder,
  projectId,
  cashOutCount,
  tokenToReclaim,
  route,
  beneficiary,
}: {
  chainId: JBChainId
  terminal: Address
  holder: Address
  projectId: bigint
  /** Project tokens to cash out, fixed-point 18 decimals. */
  cashOutCount: bigint
  tokenToReclaim: Address
  route: CashOutRoute
  beneficiary: Address
}): V6CashOutTxRequest {
  if (route.minimumReturn <= 0n) {
    throw new Error('Nothing to reclaim for this cash-out.')
  }
  return buildCashOutTx({
    chainId,
    terminal,
    holder,
    projectId,
    cashOutCount,
    tokenToReclaim,
    minTokensReclaimed: route.terminalMinimum,
    beneficiary,
    metadata: route.metadata,
  })
}

