async function waitForPaymentReceipt(client: PublicClient, hash: Hex) {
  try {
    return await client.waitForTransactionReceipt({ hash, timeout: 120_000 });
  } catch (firstError) {
    for (let attempt = 0; attempt < 90; attempt += 1) {
      try {
        return await client.getTransactionReceipt({ hash });
      } catch {
        await new Promise(resolve => window.setTimeout(resolve, 2_000));
      }
    }
    throw firstError;
  }
}

function nextUiPaint(): Promise<void> {
  return new Promise(resolve => {
    window.requestAnimationFrame(() => window.requestAnimationFrame(() => resolve()));
  });
}

/** A subtle underlined-text dropdown (website/ parity: sizeSelectToText) —
 *  a native select styled as bold underlined text with a caret. The class
 *  overrides let the pay-token selector restyle the same structure (plain
 *  label, not-allowed disabled cursor) without duplicating the overlay. */
function TextSelect({
  value,
  onChange,
  options,
  disabled,
  ariaLabel,
  className = "relative inline-flex min-h-11 items-center gap-1",
  labelClassName = "font-medium text-ink underline decoration-smoke-300 decoration-1 underline-offset-4",
  selectClassName = "absolute inset-0 h-full w-full cursor-pointer opacity-0 disabled:cursor-default",
}: {
  value: string;
  onChange: (value: string) => void;
  options: {
    value: string;
    label: string;
    selectedLabel?: string;
    disabled?: boolean;
  }[];
  disabled?: boolean;
  ariaLabel: string;
  className?: string;
  labelClassName?: string;
  selectClassName?: string;
}) {
  // A native <select> sizes to its WIDEST option, which would leave a gap
  // between a short label and the caret. So show the current label + caret as
  // tight visible text and overlay a transparent, full-cover select for the
  // real (native) dropdown.
  const selected = options.find((o) => o.value === value);
  const current = selected?.selectedLabel ?? selected?.label ?? "";
  return (
    <span className={`${className} ${disabled ? "opacity-60" : ""}`}>
      <span className={labelClassName || undefined}>{current}</span>
      <svg
        viewBox="0 0 24 24"
        className="h-3.5 w-3.5 shrink-0 text-smoke-500"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden
      >
        <path d="m6 9 6 6 6-6" />
      </svg>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        aria-label={ariaLabel}
        className={selectClassName}
      >
        {options.map((o) => (
          <option key={o.value} value={o.value} disabled={o.disabled}>
            {o.label}
          </option>
        ))}
      </select>
    </span>
  );
}

function formatStartCountdown(secs: number): string {
  if (secs <= 0) return "moments";
  const d = Math.floor(secs / 86400);
  if (d >= 1) return `${d}d ${Math.floor((secs % 86400) / 3600)}h`;
  const h = Math.floor(secs / 3600);
  if (h >= 1) return `${h}h ${Math.floor((secs % 3600) / 60)}m`;
  return `${Math.max(1, Math.floor(secs / 60))}m`;
}

import { jbRouterTerminalRegistryAbi } from '@bananapus/nana-sdk-core'
import { getAddress, isAddressEqual, type Address, type PublicClient } from 'viem'
import { contractReverted } from '@/lib/errors'
import { rolloutAddress, rolloutChain } from '@/lib/protocol-rollout'

/** Recorded payment entries, including direct routers retained by older projects. */
export function knownPaymentRouterEntries(chainId: number): Address[] {
  const record = rolloutChain(chainId)
  const addresses = [
    rolloutAddress('JBRouterTerminalRegistry', chainId),
    rolloutAddress('JBRouterTerminalGateway', chainId),
    rolloutAddress('JBRouterTerminal', chainId),
    ...Object.values(record?.history.JBRouterTerminal ?? {}),
  ].filter((address): address is string => !!address)
  return [...new Set(addresses.map(address => address.toLowerCase()))].map(address => getAddress(address))
}

/** Preserve the listed entry; a direct gateway/router does not imply an attached registry. */
export function attachedPaymentRouterEntries(chainId: number, terminals: readonly Address[]): Address[] {
  return knownPaymentRouterEntries(chainId)
    .map(known => terminals.find(terminal => isAddressEqual(known, terminal)))
    .filter((terminal): terminal is Address => !!terminal)
}

/** Find an attached entry with a live route for this token without bypassing its gateway. */
export async function readPaymentRouterEntry(
  client: Pick<PublicClient, 'readContract'>,
  {
    chainId,
    projectId,
    terminals,
    token,
    decimals,
  }: {
    chainId: number
    projectId: bigint
    terminals: readonly Address[]
    token: Address
    decimals: number
  },
): Promise<Address | null> {
  for (const terminal of attachedPaymentRouterEntries(chainId, terminals)) {
    try {
      const [ruleset] = await client.readContract({
        address: terminal,
        abi: jbRouterTerminalRegistryAbi,
        functionName: 'previewPayFor',
        args: [projectId, token, 10n ** BigInt(decimals), '0x0000000000000000000000000000000000000001', '0x'],
      })
      if (BigInt(ruleset.id) !== 0n) return terminal
    } catch (error) {
      // A contract revert means this entry cannot route the token. An RPC error
      // leaves its state unknown and must not select a different payment route.
      if (!contractReverted(error)) throw error
    }
  }
  return null
}

'use client'

import { getAccount } from '@wagmi/core'
import { useCallback } from 'react'
import { useConfig, useSignTypedData, useSwitchChain } from 'wagmi'
import {
  permit2TypedData,
  type Permit2SignatureAuthorization,
} from '@/lib/permit2-swap'
import { requireTransactionReview } from '@/lib/transaction-review'
import { getViewAs, VIEW_AS_WRITE_BLOCKED } from '@/lib/viewAs'
import type { Address } from 'viem'

export function useReviewedPermit2Signature(options?: {
  reviewedInParent?: boolean
}) {
  const config = useConfig()
  const { signTypedDataAsync } = useSignTypedData()
  const { switchChainAsync } = useSwitchChain()

  const signPermit2Async = useCallback(
    async ({
      authorization,
      expectedAccount,
    }: {
      authorization: Permit2SignatureAuthorization
      expectedAccount: Address
    }) => {
      if (getViewAs()) throw new Error(VIEW_AS_WRITE_BLOCKED)
      const typedData = permit2TypedData(authorization)
      if (!options?.reviewedInParent) {
        await requireTransactionReview({
          title: 'Sign the swap authorization',
          calls: [],
          kind: 'authorization',
          authorization: typedData,
        })
      }
      let current = getAccount(config)
      if (
        !current.address ||
        current.address.toLowerCase() !== expectedAccount.toLowerCase()
      ) {
        throw new Error('Connected account changed. Review the payment again.')
      }
      if (current.chainId !== authorization.chainId) {
        await switchChainAsync({ chainId: authorization.chainId })
      }
      current = getAccount(config)
      if (
        !current.address ||
        current.address.toLowerCase() !== expectedAccount.toLowerCase() ||
        current.chainId !== authorization.chainId
      ) {
        throw new Error('Wallet account or network changed. Review the payment again.')
      }
      const signature = await signTypedDataAsync({
        account: expectedAccount,
        ...typedData,
      })
      const after = getAccount(config)
      if (
        !after.address ||
        after.address.toLowerCase() !== expectedAccount.toLowerCase() ||
        after.chainId !== authorization.chainId
      ) {
        throw new Error('Wallet account or network changed after signing. Nothing was sent.')
      }
      return signature
    },
    [config, options?.reviewedInParent, signTypedDataAsync, switchChainAsync],
  )

  return { signPermit2Async }
}

