export async function getPermissionHoldersAcrossDeployments(
  deployments: { chainId: number; projectId: number; authority?: string | null }[],
): Promise<BsPermissionHolder[]> {
  const unique = new Map(
    deployments.map(deployment => [
      `${deployment.chainId}:${deployment.projectId}`,
      deployment,
    ]),
  )
  const rows = await Promise.all(
    [...unique.values()].flatMap(deployment => [
      getPermissionHolders(deployment.chainId, deployment.projectId),
      // Wildcard grants from this project's own authority. Without a resolved
      // authority there is no grantor to scope to, so skip rather than pull
      // every account's wildcards on the chain.
      deployment.authority
        ? getWildcardPermissionHolders(deployment.chainId, deployment.authority)
        : Promise.resolve([]),
    ]),
  )
  return rows.flat()
}

/**
 * Grants an account made on JBPermissions.WILDCARD_PROJECT_ID (0). They apply
 * to every project that account owns, so an operator holding ROOT this way
 * controls the project while appearing in no project-scoped query.
 */
async function getWildcardPermissionHolders(
  chainId: number,
  account: string,
): Promise<BsPermissionHolder[]> {
  const page = await getPagedItems<BsPermissionHolder>(
    `query($chainId: Int!, $account: String!, $limit: Int!, $offset: Int!) {
        permissionHolders(
          where: { chainId: $chainId, projectId: 0, account: $account, version: 6 }
          limit: $limit
          offset: $offset
        ) {
          items { chainId account operator permissions isRevnetOperator }
          totalCount
        }
      }`,
    'permissionHolders',
    { chainId, account },
    { pageSize: 200, max: Number.POSITIVE_INFINITY },
  ).catch(() => ({ items: [] as BsPermissionHolder[], totalCount: 0 }))
  return page.items
    .filter(row => (row.permissions?.length ?? 0) > 0)
    .map(row => ({ ...row, wildcard: true }))
}

import {
  Kind,
  parse,
  type FragmentDefinitionNode,
  type SelectionSetNode,
  type TypeNode,
  type ValueNode,
} from 'graphql'

export type BendystrawOperationContract = {
  operationName?: string
  validateData: (value: unknown) => value is Record<string, unknown>
  validateVariables: (value: unknown) => value is Record<string, unknown>
}

const contracts = new Map<string, BendystrawOperationContract>()

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
}

function isSafeInput(value: unknown, depth = 0): boolean {
  if (depth > 12) return false
  if (
    value === undefined ||
    value === null ||
    typeof value === 'boolean' ||
    (typeof value === 'number' && Number.isFinite(value))
  ) {
    return true
  }
  if (typeof value === 'string') return value.length <= 16_384
  if (Array.isArray(value)) {
    return value.length <= 1_000 && value.every(item => isSafeInput(item, depth + 1))
  }
  return (
    isRecord(value) &&
    Object.keys(value).length <= 250 &&
    Object.values(value).every(item => isSafeInput(item, depth + 1))
  )
}

function validateNamedInput(name: string, value: unknown): boolean {
  if (!isSafeInput(value)) return false
  switch (name) {
    case 'Boolean':
      return typeof value === 'boolean'
    case 'Float':
      return typeof value === 'number' && Number.isFinite(value)
    case 'Int':
      return typeof value === 'number' && Number.isSafeInteger(value)
    case 'ID':
      return typeof value === 'string' || Number.isSafeInteger(value)
    case 'String':
      return typeof value === 'string'
    default:
      return true
  }
}

function validateInput(type: TypeNode, value: unknown): boolean {
  if (type.kind === Kind.NON_NULL_TYPE) {
    return value !== null && value !== undefined && validateInput(type.type, value)
  }
  if (value === null || value === undefined) return true
  if (type.kind === Kind.LIST_TYPE) {
    const values = Array.isArray(value) ? value : [value]
    return values.every(item => validateInput(type.type, item))
  }
  return validateNamedInput(type.name.value, value)
}

function defaultValueOf(value: ValueNode | undefined): unknown {
  if (!value) return undefined
  switch (value.kind) {
    case Kind.BOOLEAN:
      return value.value
    case Kind.ENUM:
    case Kind.STRING:
      return value.value
    case Kind.FLOAT:
    case Kind.INT:
      return Number(value.value)
    case Kind.LIST:
      return value.values.map(defaultValueOf)
    case Kind.NULL:
      return null
    case Kind.OBJECT:
      return Object.fromEntries(
        value.fields.map(field => [field.name.value, defaultValueOf(field.value)]),
      )
    case Kind.VARIABLE:
      return undefined
  }
}

function validateSelectedValue(
  value: unknown,
  selectionSet: SelectionSetNode,
  fragments: ReadonlyMap<string, FragmentDefinitionNode>,
): boolean {
  if (value === null) return true
  if (Array.isArray(value)) {
    return value.every(item => validateSelectedValue(item, selectionSet, fragments))
  }
  if (!isRecord(value)) return false
  return validateSelectionSet(value, selectionSet, fragments, true)
}

function validateSelectionSet(
  value: Record<string, unknown>,
  selectionSet: SelectionSetNode,
  fragments: ReadonlyMap<string, FragmentDefinitionNode>,
  requireFields: boolean,
): boolean {
  for (const selection of selectionSet.selections) {
    if (selection.kind === Kind.FIELD) {
      const responseKey = selection.alias?.value ?? selection.name.value
      if (!Object.prototype.hasOwnProperty.call(value, responseKey)) {
        if (requireFields) return false
        continue
      }
      if (
        selection.selectionSet &&
        !validateSelectedValue(value[responseKey], selection.selectionSet, fragments)
      ) {
        return false
      }
    } else if (selection.kind === Kind.INLINE_FRAGMENT) {
      if (
        !validateSelectionSet(
          value,
          selection.selectionSet,
          fragments,
          requireFields && !selection.typeCondition,
        )
      ) {
        return false
      }
    } else {
      const fragment = fragments.get(selection.name.value)
      if (!fragment) return false
      if (!validateSelectionSet(value, fragment.selectionSet, fragments, false)) {
        return false
      }
    }
  }
  return true
}

/**
 * Compile one static GraphQL document into the same runtime operation contract
 * used by every Bendystraw transport: operation name, bounded variables, and
 * recursive response-shape validation.
 */
export function compileBendystrawOperation(
  query: string,
): BendystrawOperationContract {
  const cached = contracts.get(query)
  if (cached) return cached

  const document = parse(query)
  const operations = document.definitions.filter(
    definition => definition.kind === Kind.OPERATION_DEFINITION,
  )
  if (operations.length !== 1) {
    throw new TypeError('A Bendystraw document must contain exactly one operation')
  }
  const operation = operations[0]
  const fragments = new Map(
    document.definitions
      .filter(
        (definition): definition is FragmentDefinitionNode =>
          definition.kind === Kind.FRAGMENT_DEFINITION,
      )
      .map(fragment => [fragment.name.value, fragment]),
  )
  const variableNames = new Set(
    operation.variableDefinitions?.map(definition => definition.variable.name.value) ?? [],
  )

  const contract: BendystrawOperationContract = {
    operationName: operation.name?.value,
    validateData: (value): value is Record<string, unknown> =>
      isRecord(value) &&
      validateSelectionSet(value, operation.selectionSet, fragments, true),
    validateVariables: (value): value is Record<string, unknown> => {
      if (!isRecord(value) || !isSafeInput(value)) return false
      if (Object.keys(value).some(name => !variableNames.has(name))) return false
      return (operation.variableDefinitions ?? []).every(definition => {
        const name = definition.variable.name.value
        const input =
          value[name] === undefined ? defaultValueOf(definition.defaultValue) : value[name]
        return validateInput(definition.type, input)
      })
    },
  }
  contracts.set(query, contract)
  return contract
}

export const APPROVAL_STATUS = {
  Empty: 0,
  Upcoming: 1,
  Active: 2,
  ApprovalExpected: 3,
  Approved: 4,
  Failed: 5,
} as const;

export type QueueAction = "current" | "replace" | "after";

export type QueueRulesetRef = {
  id: bigint | number;
  cycleNumber: bigint | number;
  start: bigint | number;
  duration: bigint | number;
};

export type QueueActionOption = {
  action: QueueAction;
  source: QueueRulesetRef;
  mustStartAtOrAfter: number | null;
  requiresStartDate: boolean;
};

export type RulesetQueuePlan = {
  defaultAction: QueueAction;
  options: QueueActionOption[];
  hasQueuedRuleset: boolean;
  hasMultipleQueuedRulesets: boolean;
};

function sameRuleset(a: QueueRulesetRef | null, b: QueueRulesetRef | null): boolean {
  return !!a && !!b && BigInt(a.id) === BigInt(b.id);
}

/**
 * Translate JBRulesets' approval lifecycle into the choices an owner can safely
 * make. `upcoming` is the next stored configuration (simulated auto-cycles must
 * be filtered by the caller); `latest` is the tail returned by
 * latestQueuedRulesetOf.
 */
export function planRulesetQueue({
  current,
  upcoming,
  latest,
  latestApprovalStatus,
}: {
  current: QueueRulesetRef;
  upcoming: QueueRulesetRef | null;
  latest: QueueRulesetRef | null;
  latestApprovalStatus: number | null;
}): RulesetQueuePlan {
  const distinctUpcoming = upcoming && !sameRuleset(upcoming, current) ? upcoming : null;
  const distinctLatest = latest && !sameRuleset(latest, current) ? latest : null;
  if (!distinctLatest) {
    return {
      defaultAction: "current",
      options: [
        {
          action: "current",
          source: current,
          mustStartAtOrAfter: 0,
          requiresStartDate: false,
        },
      ],
      hasQueuedRuleset: false,
      hasMultipleQueuedRulesets: false,
    };
  }

  const options: QueueActionOption[] = [];
  const latestIsReplaceable =
    latestApprovalStatus !== APPROVAL_STATUS.Approved &&
    latestApprovalStatus !== APPROVAL_STATUS.Active;
  const replaceTarget = latestIsReplaceable ? distinctLatest : null;

  // Approved means the queued cycle is final. Active is not a replaceable
  // future configuration either. Every other queued state falls back to the
  // queued ruleset's parent when another configuration targets its cycle.
  if (replaceTarget) {
    options.push({
      action: "replace",
      source: replaceTarget,
      mustStartAtOrAfter: Number(replaceTarget.start),
      requiresStartDate: false,
    });
  }

  // Only a configuration which is already final, expected to become final, or
  // has no approval hook can safely parent another queued configuration.
  if (
    latestApprovalStatus === APPROVAL_STATUS.Approved ||
    latestApprovalStatus === APPROVAL_STATUS.ApprovalExpected ||
    latestApprovalStatus === APPROVAL_STATUS.Empty
  ) {
    const duration = Number(distinctLatest.duration);
    options.push({
      action: "after",
      source: distinctLatest,
      mustStartAtOrAfter:
        duration > 0 ? Number(distinctLatest.start) + duration : null,
      requiresStartDate: duration === 0,
    });
  }

  return {
    // Preserve an existing queued configuration unless the owner explicitly
    // chooses to replace it.
    defaultAction: options.some((option) => option.action === "after")
      ? "after"
      : options[0]?.action ?? "current",
    options,
    hasQueuedRuleset: true,
    hasMultipleQueuedRulesets:
      !!distinctUpcoming && !sameRuleset(distinctUpcoming, distinctLatest),
  };
}

export function approvalStatusLabel(status: number | null): string {
  switch (status) {
    case APPROVAL_STATUS.Empty:
      return "No approval hook";
    case APPROVAL_STATUS.Upcoming:
      return "Approval not available yet";
    case APPROVAL_STATUS.Active:
      return "Active";
    case APPROVAL_STATUS.ApprovalExpected:
      return "Approval expected";
    case APPROVAL_STATUS.Approved:
      return "Approved";
    case APPROVAL_STATUS.Failed:
      return "Approval failed";
    default:
      return "Unknown approval status";
  }
}

