      salt: TEST_SALT,
      creationFee: CREATION_FEE,
    });
    const splitWeights = request.args[1].stageConfigurations[0].splits.map(
      (split) => split.percent,
    );

    expect(splitWeights.reduce((sum, percent) => sum + percent, 0)).toBe(SPLITS_TOTAL_PERCENT);
    expect(() => encodeFunctionData(request)).not.toThrow();
  });

  // `splitPercent` is a uint16 of basis points. Summing float percentages and scaling lands
  // off an integer for ordinary inputs — 10.5 + 19.505 gives 3000.5 — and viem then throws
  // `RangeError: ... cannot be converted to a BigInt because it is not an integer`, which
  // surfaced as a generic "deploy failed" toast with nothing to act on.
  it("encodes an integer split percent for fractional inputs", () => {
    const form = validRevnetForm();
    form.stages[0].splits = [
      { percentage: "10.5", defaultBeneficiary: TEST_ACCOUNT },
      { percentage: "19.505", defaultBeneficiary: TEST_BENEFICIARY },
    ];
    const request = parseDeployData(form, {
      metadataCid: "bafy-metadata",
      chainId: sepolia.id,
      suckerDeployerConfig: EMPTY_SUCKER_CONFIG,
      timestamp: TEST_TIMESTAMP,
      salt: TEST_SALT,
      creationFee: CREATION_FEE,
    });
    const stage = request.args[1].stageConfigurations[0];

    expect(Number.isInteger(stage.splitPercent)).toBe(true);
    expect(stage.splitPercent).toBe(3_001);
    expect(Number.isInteger(stage.issuanceCutPercent)).toBe(true);
    expect(Number.isInteger(stage.cashOutTaxRate)).toBe(true);
    // The real regression: the encoder threw before reaching the wallet.
    expect(() => encodeFunctionData(request)).not.toThrow();
  });
});

// Per-chain values collected inline in the create form (split beneficiary
// overrides and operator overrides keyed by chainId) must resolve to each
// chain's own address in that chain's deployFor args, falling back to the
// single default value on chains without an override.
describe("wallet-action:create-revnet — per-chain inline values", () => {
  const CHAIN_IDS = [sepolia.id, baseSepolia.id] as const;

  function perChainForm() {
    const form = validRevnetForm();
    form.chainIds = [...CHAIN_IDS];
    form.stages[0].splits = [
      {
        percentage: "25",
        defaultBeneficiary: TEST_BENEFICIARY,
        beneficiary: [
          { chainId: sepolia.id, address: TEST_BENEFICIARY },
          { chainId: baseSepolia.id, address: TEST_ACCOUNT },
        ],
      },
      // Single-value split: no per-chain overrides.
      { percentage: "25", defaultBeneficiary: TEST_BENEFICIARY },
    ];
    form.operator = [
      { chainId: String(sepolia.id), address: TEST_ACCOUNT },
      { chainId: String(baseSepolia.id), address: TEST_BENEFICIARY },
    ];
    return form;
  }

  function requestFor(form: ReturnType<typeof perChainForm>, chainId: (typeof CHAIN_IDS)[number]) {
    return parseDeployData(form, {
      metadataCid: "bafy-metadata",
      chainId,
      suckerDeployerConfig: EMPTY_SUCKER_CONFIG,
      timestamp: TEST_TIMESTAMP,
      salt: TEST_SALT,
      creationFee: CREATION_FEE,
    });
  }

  it("routes each chain's split beneficiary override and falls back to the default", () => {
    const form = perChainForm();
    const sepoliaSplits = requestFor(form, sepolia.id).args[1].stageConfigurations[0].splits;
    const baseSepoliaSplits = requestFor(form, baseSepolia.id).args[1].stageConfigurations[0]
      .splits;

    expect(sepoliaSplits.map((split) => split.beneficiary)).toEqual([
      TEST_BENEFICIARY,
      TEST_BENEFICIARY,
    ]);
    expect(baseSepoliaSplits.map((split) => split.beneficiary)).toEqual([
      TEST_ACCOUNT,
      TEST_BENEFICIARY,
    ]);
  });

  it("routes the per-chain operator override and falls back to the stage operator", () => {
    const form = perChainForm();
    expect(requestFor(form, sepolia.id).args[1].operator).toBe(TEST_ACCOUNT);
    expect(requestFor(form, baseSepolia.id).args[1].operator).toBe(TEST_BENEFICIARY);

    // Without an override the chain inherits the single stage operator.
    form.operator = form.operator.filter((entry) => Number(entry.chainId) !== baseSepolia.id);
    expect(requestFor(form, baseSepolia.id).args[1].operator).toBe(TEST_ACCOUNT);
  });

  it("still validates the per-chain fixture against the create schema", async () => {
    const { createSchema } = await import("@/app/create/helpers/createSchema");
    expect(createSchema.safeParse(perChainForm()).success).toBe(true);
  });
});

// REVDeployer folds ALL auto-issuance rows into `encodedConfiguration`, which
// must be byte-identical on every chain for the sucker deploy to link, and it
// mints only the rows whose chainId matches block.chainid. The client must
// therefore send the FULL row list — user-chosen chainIds intact — to every
// chain, never filtering rows or rewriting a row's chainId to the config chain.
describe("wallet-action:create-revnet — multi-chain auto issuance", () => {
  const CHAIN_IDS = [sepolia.id, baseSepolia.id] as const;

  function multiChainRequest(chainId: (typeof CHAIN_IDS)[number]) {
    const form = validRevnetForm();
    form.chainIds = [...CHAIN_IDS];
    form.stages[0].autoIssuance = [
      { chainId: sepolia.id, amount: "25", beneficiary: TEST_BENEFICIARY },
      { chainId: baseSepolia.id, amount: "40", beneficiary: TEST_ACCOUNT },
    ];
    return parseDeployData(form, {
      metadataCid: "bafy-metadata",
      chainId,
      suckerDeployerConfig: EMPTY_SUCKER_CONFIG,
      timestamp: TEST_TIMESTAMP,
      salt: TEST_SALT,
      creationFee: CREATION_FEE,
    });
  }

  function encodeRevnetConfig(request: ReturnType<typeof multiChainRequest>) {
    const deployFor = (
      request.abi as readonly { type: string; name?: string; inputs?: readonly AbiParameter[] }[]
    ).find((item) => item.type === "function" && item.name === "deployFor");
    if (!deployFor?.inputs) throw new Error("deployFor ABI entry missing");
    return encodeAbiParameters([deployFor.inputs[1]], [request.args[1]]);
  }

  it("carries every row with its user-chosen chainId in every chain's stage config", () => {
    for (const chainId of CHAIN_IDS) {
      const request = multiChainRequest(chainId);

      expect(request.args[1].stageConfigurations[0].autoIssuances).toEqual([
        {
          chainId: String(sepolia.id),
          count: parseUnits("25", 18),
          beneficiary: TEST_BENEFICIARY,
        },
        {
          chainId: String(baseSepolia.id),
          count: parseUnits("40", 18),
          beneficiary: TEST_ACCOUNT,
        },
      ]);
    }
  });

  it("encodes a byte-identical REVConfig for every chain", () => {
    const [sepoliaConfig, baseSepoliaConfig] = CHAIN_IDS.map((chainId) =>
      encodeRevnetConfig(multiChainRequest(chainId)),
    );

    expect(sepoliaConfig).toBe(baseSepoliaConfig);
    // Both rows' chainIds survive in the encoded bytes (uint32, hex-padded).
    const sepoliaWord = sepolia.id.toString(16).padStart(64, "0");
    const baseSepoliaWord = baseSepolia.id.toString(16).padStart(64, "0");
    expect(sepoliaConfig).toContain(sepoliaWord);
    expect(sepoliaConfig).toContain(baseSepoliaWord);
  });
});

// https://github.com/rev-net/revnet-core/blob/main/script/Deploy.s.sol
import { USDC_DECIMALS } from "@/app/constants";
import { buildTierConfigs } from "@/components/shop/itemDraft";
import {
  CashOutTaxRate,
  ETH_CURRENCY_ID,
  JBChainId,
  NATIVE_TOKEN,
  NATIVE_TOKEN_DECIMALS,
  SPLITS_TOTAL_PERCENT,
  USD_CURRENCY_ID,
  USDC_ADDRESSES,
  WeightCutPercent,
} from "@bananapus/nana-sdk-core";
import {
  build721RulesetMetadata,
  buildAccountingContext,
  buildDeployRevnetTx,
  buildRevnetStageConfig,
  fillSplitPercents,
  REV_METADATA_ALLOW_SUCKER_DEPLOYMENT,
  RULESET_WEIGHT_INHERIT,
  tokenCurrencyId,
} from "@bananapus/nana-sdk-core/v6";
import { Address, ContractFunctionArgs, parseUnits, zeroAddress } from "viem";
import { RevnetFormData } from "../types";

// Standard reserves use the 4-arg `deployFor` overload. Custom reserves use the
// 6-arg overload so the empty 721 store can inherit the ERC-20's own decimals.
// Keep both argument shapes typed against the deployer ABI.
type RevDeployerAbi = ReturnType<typeof buildDeployRevnetTx>["abi"];
type DeployForArgs = ContractFunctionArgs<RevDeployerAbi, "payable", "deployFor">;
export type DeployRevnetRequest = Omit<ReturnType<typeof buildDeployRevnetTx>, "args"> & {
  args: DeployForArgs;
};

export function parseDeployData(
  _formData: RevnetFormData,
  extra: {
    metadataCid: string;
    chainId: JBChainId;
    suckerDeployerConfig: {
      deployerConfigurations: {
        deployer: Address;
        peer: `0x${string}`;
        mappings: {
          localToken: Address;
          minGas: number;
          remoteToken: `0x${string}`;
        }[];
      }[];
    };
    timestamp: number;
    salt: `0x${string}`;
    creationFee: bigint;
  },
): DeployRevnetRequest {
  // hack: stringfy numbers
  const formData: RevnetFormData = JSON.parse(JSON.stringify(_formData), (_, value) =>
    typeof value === "number" ? String(value) : value,
  );
  let prevStart = 0;
  const operator =
    formData?.operator.find((c) => Number(c.chainId) === Number(extra.chainId))?.address ||
    formData.stages[0].initialOperator;

  // Accounting-context currencies are ALWAYS token-keyed:
  // `uint32(uint160(token))`, native = 61166. The well-known ETH/USD ids
  // (1/2) are base-currency denominations only — encoding them as context
  // currencies is the convention violation this file used to carry.
  // `buildAccountingContext` defaults to `tokenCurrencyId(token)`.
  let baseCurrency: number;
  let tokenAddress: Address;
  let tokenDecimals: number;

  if (formData.reserveAsset === "CUSTOM") {
    tokenAddress = formData.customReserveAsset.address as Address;
    tokenDecimals = Number(formData.customReserveAsset.decimals);
    baseCurrency = tokenCurrencyId(tokenAddress);
  } else {
    const acceptsUsdc = formData.reserveAsset === "USDC" || formData.reserveAsset === "ETH_USDC";
    tokenAddress = acceptsUsdc ? USDC_ADDRESSES[extra.chainId] : NATIVE_TOKEN;
    tokenDecimals = acceptsUsdc ? USDC_DECIMALS : NATIVE_TOKEN_DECIMALS;
    baseCurrency = formData.issuanceBaseCurrency === "USD" ? USD_CURRENCY_ID(6) : ETH_CURRENCY_ID;
  }

  const nativeAccountingContext = buildAccountingContext(NATIVE_TOKEN, NATIVE_TOKEN_DECIMALS);
  const usdcAccountingContext = buildAccountingContext(
    USDC_ADDRESSES[extra.chainId],
    USDC_DECIMALS,
  );
  const accountingContextsToAccept =
    formData.reserveAsset === "CUSTOM"
      ? [buildAccountingContext(tokenAddress, tokenDecimals)]
      : formData.reserveAsset === "ETH_USDC"
        ? [nativeAccountingContext, usdcAccountingContext]
        : formData.reserveAsset === "USDC"
          ? [usdcAccountingContext]
          : [nativeAccountingContext];

  const stageConfigurations = formData.stages.map((stage, idx) => {
    const lengthSeconds = Math.floor(Number(stage.stageStart) * 86400);
    const bufferSeconds = 600;
    // Stage 0: use futureStartTimestamp if set, otherwise start in ~10 minutes
    const futureStart = Number(formData.stages[0].futureStartTimestamp);
    const startsAtOrAfter =
      idx === 0
        ? futureStart > 0
          ? futureStart
          : extra.timestamp + bufferSeconds
        : prevStart + lengthSeconds;
    prevStart = startsAtOrAfter;
    // Every chain receives the FULL auto-issuance row list with the user-chosen
    // chainIds intact: REVDeployer folds all rows into `encodedConfiguration`
    // (which must be byte-identical across chains) and mints only the rows
    // whose chainId matches the chain it is deployed on.
    const autoIssuances = stage.autoIssuance.map((autoIssuance) => ({
      chainId: autoIssuance.chainId,
      count: autoIssuance.amount ? parseUnits(autoIssuance.amount, 18) : 0n,
      beneficiary: autoIssuance.beneficiary as Address,
    }));

    // The bucket's size in basis points out of 10_000. Two values, deliberately:
    //  - `splitBucketBps` keeps the EXACT entered total, because each row's share below is
    //    relative to what the user actually typed. Rounding first makes the shares sum to a
    //    different total and `fillSplitPercents` rejects the drift.
    //  - `splitPercent` is what gets encoded, and the field is a uint16. Summing float
    //    percentages lands off an integer for ordinary inputs — 10.5 + 19.505 gives 3000.5 —
    //    and viem then throws `RangeError: ... cannot be converted to a BigInt because it is
    //    not an integer`, blocking the deploy behind a generic toast. A basis point is the
    //    finest unit the field can express, so rounding loses nothing it could have carried.
    const splitBucketBps =
      stage.splits.reduce((sum, split) => sum + (Number(split.percentage) || 0), 0) * 100;
    const splitPercent = Math.round(splitBucketBps);
    // Scale each split to its share of the split bucket, then correct per-row rounding
    // drift so the group sums to exactly SPLITS_TOTAL_PERCENT (JBSplits reverts otherwise).
    const splitBucketPercents = fillSplitPercents(
      stage.splits.map((split) =>
        Math.round((Number(split.percentage) * 100 * SPLITS_TOTAL_PERCENT) / splitBucketBps),
      ),
    );
    const splits = stage.splits.map((split, splitIdx) => {
      let beneficiary = split.beneficiary?.find(
        (b) => Number(b?.chainId) === Number(extra.chainId),
      )?.address;
      if (!beneficiary) {
        beneficiary = split.defaultBeneficiary;
      }
      if (!beneficiary) throw new Error("Beneficiary not found");
      return {
        preferAddToBalance: false,
        lockedUntil: 0,
        percent: splitBucketPercents[splitIdx],
        projectId: 0n,
        beneficiary: beneficiary as Address,
        hook: zeroAddress,
      };
    });

    return buildRevnetStageConfig({
      startsAtOrAfter,
      autoIssuances,
      splitPercent,
      splits,
      initialIssuance:
        stage.pickUpFromPrevious && idx > 0
          ? RULESET_WEIGHT_INHERIT
          : stage.initialIssuance && stage.initialIssuance !== ""
            ? parseUnits(`${stage.initialIssuance}`, 18)
            : 0n,
      issuanceCutFrequency: Math.floor(Number(stage.priceCeilingIncreaseFrequency) * 86400), // seconds
      // Same integer requirement as splitPercent above: these divisions can leave a fraction
      // that the ABI encoder rejects outright.
      issuanceCutPercent: Math.round(
        Number(WeightCutPercent.parse(stage.priceCeilingIncreasePercentage, 9).value) / 100,
      ),
      cashOutTaxRate: Math.round(
        Number(CashOutTaxRate.parse(stage.priceFloorTaxIntensity, 4).value) / 100,
      ),
      // `REVDeployer.deploySuckersFor` reads bit 2 of the CURRENT stage's app
      // metadata and reverts without it (REVDeployer.sol:646-650). Stages are
      // immutable, so a stage that ships without the bit can never be extended
      // to another chain. `buildRevnetStageConfig` sets it by default, but the
      // 721 metadata is composed here, so it is re-applied explicitly.
      extraMetadata:
        build721RulesetMetadata({
          metadata: Number(stage.extraMetadata ?? 0),
          // Keep the collection-level gate permanently closed. Each tier's
          // immutable `transfersPausable` flag is then a fixed policy:
          // false = transferable, true = non-transferable. No later stage can
          // switch an item from one behavior to the other.
          pauseTransfers: true,
        }) | REV_METADATA_ALLOW_SUCKER_DEPLOYMENT,
    });
  });

  // The v6 REVDeployer bakes in the terminals, buyback hook, and loans contract.
  // `buildDeployRevnetTx` sends the creation fee as the transaction's value
  // (revnetId defaults to 0n: a new revnet).
  // Every revnet gets a store: REVDeployer's four-argument `deployFor` deploys an empty 721
  // hook itself when none is given (REVDeployer.sol:594-605). It hardcodes 18 price decimals
  // there, which mis-prices a USD- or USDC-denominated store by twelve orders of magnitude, and
  // grants the operator every 721 permission. So the config is always ours to send.
  //
  // Item prices are denominated in the revnet's own base currency by default — the same unit
  // its issuance is quoted in — or in USD when the store is priced that way. The decimals must
  // follow the CURRENCY, not the reserve token: a USD-denominated revnet holding ETH prices its
  // items with 6 decimals, not 18.
  const storePricing =
    formData.store.pricing === "USD"
      ? { currency: USD_CURRENCY_ID(6), decimals: 6 }
      : {
          currency: baseCurrency,
          decimals:
            formData.reserveAsset === "CUSTOM"
              ? tokenDecimals
              : formData.issuanceBaseCurrency === "USD"
                ? 6
                : NATIVE_TOKEN_DECIMALS,
        };

  const tiers = buildTierConfigs(formData.store.items, storePricing.decimals, extra.chainId);
  if (typeof tiers === "string") throw new Error(tiers);

  const tiered721Config = {
    baseline721HookConfiguration: {
      name: formData.store.collectionName.trim() || `${formData.name} Store`,
      symbol: formData.store.collectionSymbol.trim() || `${formData.tokenSymbol}STORE`,
      baseUri: "ipfs://",
      tokenUriResolver: zeroAddress,
      contractUri: extra.metadataCid,
      tiersConfig: {
        tiers,
        currency: storePricing.currency,
        decimals: storePricing.decimals,
      },
      flags: {
        noNewTiersWithReserves: formData.store.noNewTiersWithReserves,
        noNewTiersWithVotes: formData.store.noNewTiersWithVotes,
        noNewTiersWithOwnerMinting: formData.store.noNewTiersWithOwnerMinting,
        preventOverspending: formData.store.preventOverspending,
      },
    },
    salt: extra.salt,
    // The form asks what the operator MAY do; the deployer takes what it may NOT.
    preventOperatorAdjustingTiers: !formData.store.operatorCanAdjustTiers,
    preventOperatorUpdatingMetadata: !formData.store.operatorCanUpdateMetadata,
    preventOperatorMinting: !formData.store.operatorCanMint,
    preventOperatorIncreasingDiscountPercent: !formData.store.operatorCanIncreaseDiscount,
  };

  const request = buildDeployRevnetTx({
    chainId: extra.chainId,
    config: {
      description: {
        name: formData.name,
        ticker: formData.tokenSymbol,
        uri: extra.metadataCid,
        salt: extra.salt,
      },
      baseCurrency: baseCurrency,
      operator: operator as Address,
      scopeCashOutsToLocalBalances: false,
      stageConfigurations,
    },
    accountingContexts: accountingContextsToAccept,
    suckerConfig: {
      deployerConfigurations: extra.suckerDeployerConfig.deployerConfigurations,
      salt: extra.salt,
    },
    creationFee: extra.creationFee,
    tiered721Config,
    allowedPosts: [],
  });

  // Viem cannot reliably disambiguate overloaded tuple-heavy functions when
  // one overload contains empty arrays. Keep only the selected deployFor
  // overload so encoding, simulation, review, and wallet submission all use
  // the same selector.
  const argCount = request.args.length;
  return {
    ...request,
    abi: request.abi.filter(
      (item) =>
        item.type !== "function" || item.name !== "deployFor" || item.inputs.length === argCount,
    ) as unknown as RevDeployerAbi,
  } as DeployRevnetRequest;
}

import { chainDisplayName } from "@/app/constants";
import EtherscanLink from "@/components/EtherscanLink";
import { RelayrPaymentSelect } from "@/components/RelayrPaymentSelect";
import { Button } from "@/components/ui/button";
import {
  CheckCircle,
  CircleDashedIcon,
  CircleDotDashedIcon,
  CircleDotIcon,
  CircleXIcon,
  FastForward,
  SquareArrowOutUpRightIcon,
} from "@/components/ui/icons";
import { SummaryRow, TxConfirmDialog } from "@/components/ui/TxConfirmDialog";
import { useToast } from "@/components/ui/use-toast";
import { useGetRelayrTxBundle, useSendRelayrTx } from "@/hooks/useReviewedRelayr";
import { submittedViaSafe } from "@/hooks/useReviewedWriteContract";
import type {
  ChainPayment,
  RelayrGetBundleResponse,
  RelayrPostBundleResponse,
} from "@/lib/nana/types";
import { formatHexEther, formatWalletError } from "@/lib/utils";
import { JB_CHAINS, JBChainId } from "@bananapus/nana-sdk-core";
import { useState } from "react";
import { twMerge } from "tailwind-merge";
import { Hash } from "viem";
import { useCreateForm } from "../form/useCreateForm";
import { ensureFreshQuote, type QuotedStageStart } from "../helpers/staleQuote";
import { GoToProjectButton } from "./GoToProjectButton";

interface PaymentAndDeploySectionProps {
  relayrResponse: RelayrPostBundleResponse;
  revnetTokenSymbol: string;
  quotedStageStart?: QuotedStageStart;
  rebuildStaleQuote?: () => Promise<RelayrPostBundleResponse>;
}

const statusToIcon = (status: string) => {
  if (status === "Pending")
    return <CircleDashedIcon className="w-5 h-5 text-amber-400 animate-spin" />;
  if (status === "Mempool")
    return <CircleDotDashedIcon className="w-5 h-5 text-blue-400 animate-spin" />;
  if (status === "Included")
    return <CircleDotIcon className="w-5 h-5 text-cyan-400 animate-spin" />;
  if (status === "Success" || status === "Completed")
    return <CheckCircle className="w-5 h-5 text-emerald-500 fade-in-50" />;
  return <CircleXIcon className="w-5 h-5 text-red-500 fade-in-50" />;
};

function destinationHash(transaction: RelayrGetBundleResponse["transactions"][number]) {
  const data = transaction.status?.data as
    { hash?: Hash; transaction?: { hash?: Hash } } | undefined;
  return data?.hash ?? data?.transaction?.hash;
}

export function PayAndDeploy({
  relayrResponse,
  revnetTokenSymbol,
  quotedStageStart,
  rebuildStaleQuote,
}: PaymentAndDeploySectionProps) {
  const [selectedPayment, selectPayment] = useState<ChainPayment | null>(null);
  const [payIsProcessing, setPayIsProcessing] = useState(false);
  const [paymentSubmitted, setPaymentSubmitted] = useState(false);
  const [safeProposalSubmitted, setSafeProposalSubmitted] = useState(false);
  const [review, setReview] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { values } = useCreateForm();
  const { sendRelayrTx, data: paymentHash } = useSendRelayrTx();
  const {
    startPolling,
    response: bundleResponse,
    isComplete,
    hasFailed,
    isPolling,
    error: bundleError,
  } = useGetRelayrTxBundle();
  const { toast } = useToast();
  // A receipt or bundle verification error cannot make an existing payment safe to repeat.
  const paymentSent = paymentSubmitted || !!paymentHash;
  const paymentLocked = paymentSent || isComplete || hasFailed;
  const busy = payIsProcessing || isPolling;

  return (
    <div>
      <RelayrPaymentSelect
        payments={relayrResponse.payment_info}
        tokenSymbol="ETH"
        selectedPayment={selectedPayment}
        onSelectPayment={selectPayment}
        disabled={payIsProcessing || paymentLocked}
      />
      <div className="flex justify-end md:col-span-3 mt-4">
        <Button
          type="submit"
          size="lg"
          disabled={payIsProcessing || paymentLocked || !selectedPayment}
          className="disabled:text-black disabled:bg-transparent disabled:border disabled:border-black disabled:bg-gray-100 bg-teal-500 text-melon-950 hover:bg-teal-600"
          onClick={() => {
            setError(null);
            setReview(true);
          }}
        >
          Pay and launch
          {isComplete ? (
            <CheckCircle className={"h-4 w-4 ml-2 fill-none text-emerald-500"} />
          ) : (
            <FastForward
              className={twMerge(
                "h-4 w-4 fill-melon-950 ml-2",
                busy ? "animate-spin" : paymentLocked ? "" : "animate-pulse",
              )}
            />
          )}
        </Button>
      </div>
      {review && selectedPayment ? (
        <TxConfirmDialog
          open
          onOpenChange={(open) => {
            if (!open) setReview(false);
          }}
          title="Confirm payment"
          chainId={selectedPayment.chain}
          steps={[
            {
              title: `Pay ${formatHexEther(selectedPayment.amount)} ETH to relay`,
              detail:
                "Relayr sends the launch transactions to each selected chain. No further wallet prompts are needed.",
            },
          ]}
          activeIndex={payIsProcessing ? 0 : -1}
          action="Pay and launch"
          busy={payIsProcessing}
          disabled={paymentLocked}
          error={error}
          onConfirm={async () => {
            if (payIsProcessing || paymentLocked) return;
            setPayIsProcessing(true);
            setError(null);
            try {
              if (!selectedPayment || !sendRelayrTx) throw new Error("No payment selected");
              const { bundle, payment } = await ensureFreshQuote({
                bundle: relayrResponse,
                payment: selectedPayment,
                quotedStageStart,
                rebuildStaleQuote,
                onRebuild: () =>
                  toast({
                    title: "Refreshing quote",
                    description:
                      "The quoted start time has passed. Sign the new launch requests to avoid a 7-day lock on cash-outs and loans.",
                  }),
              });
              if (payment !== selectedPayment) selectPayment(payment);
              const hash = await sendRelayrTx(payment);
              setPaymentSubmitted(true);
              if (submittedViaSafe(hash)) {
                setSafeProposalSubmitted(true);
                setReview(false);
                toast({
                  title: "Safe payment proposal submitted",
                  description:
                    "The launch is not paid yet. Approve and carry out this payment in Safe, then check transaction activity. Do not propose another payment. If it runs after the quoted start time, cash-outs and loans will be locked for 7 days from launch.",
                });
                return;
              }
              setReview(false);
              startPolling(bundle.bundle_uuid);
            } catch (e: any) {
              setError(formatWalletError(e));
              toast({
                title: "Error",
                description: formatWalletError(e),
                variant: "destructive",
              });
            } finally {
              setPayIsProcessing(false);
            }
          }}
        >
          <SummaryRow label="Pays">{formatHexEther(selectedPayment.amount)} ETH</SummaryRow>
          <SummaryRow label="On">{chainDisplayName(selectedPayment.chain)}</SummaryRow>
          <SummaryRow label="Deploys on">
            {values.chainIds.map((chainId) => chainDisplayName(chainId)).join(", ")}
          </SummaryRow>
          <SummaryRow label="Revnet">
            {values.name || "Unnamed"} (${revnetTokenSymbol})
          </SummaryRow>
        </TxConfirmDialog>
      ) : null}
      {safeProposalSubmitted ? (
        <p className="mt-4 text-sm text-melon-700">
          Complete the existing payment proposal in Safe, then check transaction activity. Do not
          submit another payment.
        </p>
      ) : null}
      {bundleError ? (
        <p
          role="alert"
          className="mt-4 border border-peel-400 bg-peel-25 p-3 text-sm text-peel-800"
        >
          {formatWalletError(bundleError)} Check the launch in transaction activity. Do not make
          another Relayr payment.
        </p>
      ) : null}
      {!!bundleResponse && (
        <div className="mt-10 flex flex-col space-y-2">
          <div className="text-left text-zinc-500 mb-2">
            Track the launch on each chain below. It usually takes 1–2 minutes; your revnet is ready
            on a chain once its transaction confirms.
          </div>
          <div className="grid grid-cols-3 gap-4 font-semibold border-b mb-2">
            <div>Network</div>
            <div>Status</div>
            <div>Transaction</div>
          </div>
          {bundleResponse.transactions.map(
            (txn) =>
              txn?.status && (
                <div key={txn?.tx_uuid} className="grid grid-cols-3 gap-4">
                  <div>{chainDisplayName(txn.request.chain as JBChainId)}</div>
                  <div className="flex flex-row space-x-2 items-center justify-start">
                    <div>{statusToIcon(txn.status.state)}</div>
                    <div>{txn.status.state}</div>
                  </div>
                  {destinationHash(txn) ? (
                    <div className="flex flex-row space-x-1 items-center">
                      <EtherscanLink
                        value={destinationHash(txn)}
                        type="tx"
                        chain={JB_CHAINS[txn.request.chain as JBChainId].chain}
                        truncateTo={6}
                      />
                      <SquareArrowOutUpRightIcon className="w-3 h-3" />
                    </div>
                  ) : (
                    <div className="animate-pulse italic">generating...</div>
                  )}
                </div>
              ),
          )}
          {isComplete && bundleResponse.transactions[0] ? (
            <GoToProjectButton
              txHash={destinationHash(bundleResponse.transactions[0])}
              chainId={bundleResponse.transactions[0].request.chain}
            />
          ) : bundleError ? null : hasFailed ? (
            <p className="border border-peel-400 bg-peel-25 p-3 text-sm text-peel-800">
              At least one launch transaction failed. Review each chain’s status above; do not make
              another Relayr payment.
            </p>
          ) : (
            <p className="text-sm text-melon-700">
              Relayr payment confirmed. The launch transactions are still pending.
            </p>
          )}
        </div>
      )}
    </div>
  );
}

import { RESERVED_TOKEN_SPLIT_GROUP_ID } from "@/app/constants";
import { DEFAULT_FORM_DATA, defaultStoreData } from "@/app/create/constants";
import type { RevnetFormData, StageData } from "@/app/create/types";
import { newDraftItem } from "@/components/shop/itemDraft";
import { readAllProjectRulesets } from "@/lib/nana/rulesets";
import type { JBChainId } from "@/lib/nana/types";
import {
  JBCoreContracts,
  NATIVE_TOKEN,
  USDC_ADDRESSES,
  getJBContractAddress,
  jbControllerAbi,
  jbSplitsAbi,
} from "@bananapus/nana-sdk-core";
import { RULESET_WEIGHT_INHERIT, getAccountingContexts } from "@bananapus/nana-sdk-core/v6";
import { formatUnits, zeroAddress, type Address, type PublicClient } from "viem";

const MAX_DRAFT_BYTES = 2_000_000;
const SPLITS_TOTAL = 1_000_000_000;

type RawSplit = {
  percent: number;
  projectId: bigint;
  beneficiary: Address;
  preferAddToBalance: boolean;
  lockedUntil: number;
  hook: Address;
};

type RulesetMetadata = {
  reservedPercent: number;
  cashOutTaxRate: number;
  baseCurrency: number;
  metadata: number;
};

type RevnetDraftFile = {
  v: 1;
  app: "revnet.money";
  data: RevnetFormData;
};

export type RevnetDraftResult = {
  file: RevnetDraftFile;
  warnings: string[];
};

const text = (value: unknown, max: number) =>
  typeof value === "string" ? value.slice(0, max) : "";
const numericText = (value: unknown, max = 24) => {
  const raw = typeof value === "number" ? String(value) : text(value, max);
  return /^-?\d*(?:\.\d*)?$/u.test(raw) ? raw : "";
};

function sanitizeStage(value: unknown): StageData {
  const stage = (value ?? {}) as Record<string, unknown>;
  const autoIssuance = Array.isArray(stage.autoIssuance) ? stage.autoIssuance : [];
  const splits = Array.isArray(stage.splits) ? stage.splits : [];
  return {
    initialIssuance: numericText(stage.initialIssuance),
    pickUpFromPrevious: stage.pickUpFromPrevious === true,
    priceCeilingIncreasePercentage: numericText(stage.priceCeilingIncreasePercentage),
    priceCeilingIncreaseFrequency: numericText(stage.priceCeilingIncreaseFrequency),
    priceFloorTaxIntensity: numericText(stage.priceFloorTaxIntensity),
    extraMetadata:
      Number.isInteger(Number(stage.extraMetadata)) &&
      Number(stage.extraMetadata) >= 0 &&
      Number(stage.extraMetadata) <= 0x3fff
        ? Number(stage.extraMetadata)
        : 0,
    autoIssuance: autoIssuance.slice(0, 100).flatMap((raw) => {
      const row = (raw ?? {}) as Record<string, unknown>;
      const chainId = Number(row.chainId);
      return Number.isSafeInteger(chainId) && chainId > 0
        ? [
            {
              amount: numericText(row.amount),
              beneficiary: text(row.beneficiary, 64),
              chainId: chainId as JBChainId,
            },
          ]
        : [];
    }),
    splits: splits.slice(0, 100).map((raw) => {
      const row = (raw ?? {}) as Record<string, unknown>;
      const beneficiaries = Array.isArray(row.beneficiary) ? row.beneficiary : [];
      return {
        percentage: numericText(row.percentage),
        defaultBeneficiary: text(row.defaultBeneficiary, 64),
        beneficiary: beneficiaries.slice(0, 16).flatMap((beneficiary) => {
          const item = (beneficiary ?? {}) as Record<string, unknown>;
          const chainId = Number(item.chainId);
          const address = text(item.address, 64);
          return Number.isSafeInteger(chainId) && chainId > 0 && address
            ? [{ chainId: chainId as JBChainId, address }]
            : [];
        }),
      };
    }),
    stageStart: numericText(stage.stageStart) || "0",
    stageStartCuts: numericText(stage.stageStartCuts) || undefined,
    futureStartTimestamp:
      Number.isSafeInteger(Number(stage.futureStartTimestamp)) &&
      Number(stage.futureStartTimestamp) > 0
        ? Number(stage.futureStartTimestamp)
        : undefined,
  };
}

/**
 * Whitelist a store from an untrusted draft. Media files cannot travel in a JSON draft, so an
 * item arrives as its already-pinned URIs; everything else is clamped to the shapes the create
 * form and the tier encoder accept.
 */
function sanitizeStore(value: unknown): RevnetFormData["store"] {
  const raw = (value ?? {}) as Record<string, unknown>;
  const items = Array.isArray(raw.items) ? raw.items : [];
  const categories = Array.isArray(raw.categories) ? raw.categories : [];
  const bool = (key: string, fallback: boolean) =>
    typeof raw[key] === "boolean" ? (raw[key] as boolean) : fallback;
  return {
    ...defaultStoreData,
    collectionName: text(raw.collectionName, 100),
    collectionSymbol: text(raw.collectionSymbol, 32),
    pricing: raw.pricing === "USD" ? "USD" : "reserve",
    categories: categories.slice(0, 32).flatMap((entry) => {
      const category = (entry ?? {}) as Record<string, unknown>;
      const id = Number(category.id);
      const name = text(category.name, 64);
      return Number.isSafeInteger(id) && id > 0 && name ? [{ id, name }] : [];
    }),
    items: items.slice(0, 64).map((entry) => {
      const item = (entry ?? {}) as Record<string, unknown>;
      const splits = Array.isArray(item.splits) ? item.splits : [];
      const perChainSupply = (item.perChainSupply ?? {}) as Record<string, unknown>;
      return {
        ...newDraftItem(),
        name: text(item.name, 100),
        description: text(item.description, 2_000),
        mediaUri: text(item.mediaUri, 500),
        uri: text(item.uri, 500),
        price: numericText(item.price),
        supply: numericText(item.supply),
        category: numericText(item.category) || "0",
        reserveFrequency: numericText(item.reserveFrequency),
        reserveBeneficiary: text(item.reserveBeneficiary, 64),
        discountPct: numericText(item.discountPct),
        votingUnits: numericText(item.votingUnits),
        splits: splits.slice(0, 16).map((splitValue) => {
          const split = (splitValue ?? {}) as Record<string, unknown>;
          return {
            percent: numericText(split.percent),
            beneficiary: text(split.beneficiary, 64),
          };
        }),
        allowOwnerMint: item.allowOwnerMint === true,
        cantBeRemoved: item.cantBeRemoved === true,
        allowCredits: item.allowCredits !== false,
        operatorCanEditDiscount: item.operatorCanEditDiscount !== false,
        nonTransferable: item.nonTransferable === true,
        perChainSupply: Object.fromEntries(
          Object.entries(perChainSupply)
            .filter(([chainId]) => Number.isSafeInteger(Number(chainId)) && Number(chainId) > 0)
            .slice(0, 16)
            .map(([chainId, supply]) => [
              Number(chainId),
              String(supply).trim().toLowerCase() === "unlimited"
                ? "unlimited"
                : numericText(supply),
            ]),
        ),
      };
    }),
    preventOverspending: bool("preventOverspending", false),
    noNewTiersWithReserves: bool("noNewTiersWithReserves", false),
    noNewTiersWithVotes: bool("noNewTiersWithVotes", false),
    noNewTiersWithOwnerMinting: bool("noNewTiersWithOwnerMinting", false),
    operatorCanAdjustTiers: bool("operatorCanAdjustTiers", true),
    operatorCanUpdateMetadata: bool("operatorCanUpdateMetadata", true),
    operatorCanMint: bool("operatorCanMint", true),
    operatorCanIncreaseDiscount: bool("operatorCanIncreaseDiscount", true),
  };
}

/** Parse an untrusted Revnet .jb file into whitelisted create-form values. */
export function parseRevnetDraft(source: string): RevnetFormData {
  if (source.length > MAX_DRAFT_BYTES) throw new Error("That file is too large.");
  let parsed: unknown;
  try {
    parsed = JSON.parse(source);
  } catch {
    throw new Error("That doesn't look like a .jb file.");
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("That doesn't look like a .jb file.");
  }
  const root = parsed as Record<string, unknown>;
  const raw =
    root.app === "revnet.money" && root.data && typeof root.data === "object"
      ? (root.data as Record<string, unknown>)
      : root;
  if (!Array.isArray(raw.stages) || typeof raw.name !== "string") {
    throw new Error("No Revnet create draft was found in that file.");
  }
  const reserveAsset = ["ETH", "USDC", "ETH_USDC", "CUSTOM"].includes(String(raw.reserveAsset))
    ? (raw.reserveAsset as RevnetFormData["reserveAsset"])
    : "ETH";
  const custom = (raw.customReserveAsset ?? {}) as Record<string, unknown>;
  const chainIds = (Array.isArray(raw.chainIds) ? raw.chainIds : [])
    .slice(0, 16)
    .map(Number)
    .filter((chainId) => Number.isSafeInteger(chainId) && chainId > 0) as JBChainId[];
  const operators = Array.isArray(raw.operator) ? raw.operator : [];
  return {
    ...DEFAULT_FORM_DATA,
    name: text(raw.name, 100),
    description: text(raw.description, 10_000),
    logoUri: text(raw.logoUri, 500),
    twitter: text(raw.twitter, 200),
    telegram: text(raw.telegram, 200),
    discord: text(raw.discord, 200),
    infoUri: text(raw.infoUri, 500),
    tokenSymbol: text(raw.tokenSymbol, 32),
    stages: raw.stages.slice(0, 32).map(sanitizeStage),
    chainIds,
    operator: operators.slice(0, 16).flatMap((value) => {
      const item = (value ?? {}) as Record<string, unknown>;
      const chainId = Number(item.chainId);
      const address = text(item.address, 64);
      return Number.isSafeInteger(chainId) && chainId > 0 && address
        ? [{ chainId: String(chainId), address }]
        : [];
    }),
    reserveAsset,
    issuanceBaseCurrency: raw.issuanceBaseCurrency === "USD" ? "USD" : "ETH",
    store: sanitizeStore(raw.store),
    customReserveAsset: {
      address: text(custom.address, 64),
      symbol: text(custom.symbol, 32),
      decimals:
        Number.isInteger(Number(custom.decimals)) && Number(custom.decimals) >= 0
          ? Number(custom.decimals)
          : null,
      verifiedChainIds: (Array.isArray(custom.verifiedChainIds) ? custom.verifiedChainIds : [])
        .slice(0, 16)
        .map(Number)
        .filter((chainId) => Number.isSafeInteger(chainId) && chainId > 0) as JBChainId[],
    },
  };
}

function slug(value: string): string {
  return (
    value
      .toLocaleLowerCase()
      .replace(/[^a-z0-9]+/gu, "-")
      .replace(/^-+|-+$/gu, "") || "revnet"
  );
}

export function revnetDraftFileName(name: string): string {
  return `${slug(name)}.jb`;
}

/**
 * Reconstruct the full configured stage history from the source chain.
 * Per-chain operator/split differences are surfaced as warnings.
 */
export async function buildRevnetDraft({
  client,
  chainId,
  projectId,
  projects,
  operator,
  metadata,
  tokenSymbol,
  autoIssuances,
}: {
  client: PublicClient;
  chainId: JBChainId;
  projectId: bigint;
  projects: { chainId: number; projectId: number }[];
  operator: Address;
  metadata: Record<string, unknown>;
  tokenSymbol: string;
  autoIssuances: Array<{
    stageIndex: number;
    count: string | number;
    beneficiary: string;
    chainId: number;
  }>;
}): Promise<RevnetDraftResult> {
  const rulesets = (
    await readAllProjectRulesets(
      client,
      getJBContractAddress(JBCoreContracts.JBRulesets, 6, chainId),
      projectId,
    )
  ).reverse();
  if (!rulesets.length) throw new Error("No deployed stages could be verified.");

  const controller = getJBContractAddress(JBCoreContracts.JBController, 6, chainId);
  const splitsAddress = getJBContractAddress(JBCoreContracts.JBSplits, 6, chainId);
  const stageReads = await Promise.all(
    rulesets.map(async (ruleset) => {
      const [decoded, splits] = await Promise.all([
        client.readContract({
          address: controller,
          abi: jbControllerAbi,
          functionName: "getRulesetOf",
          args: [projectId, BigInt(ruleset.id)],
        }),
        client.readContract({
          address: splitsAddress,
          abi: jbSplitsAbi,
          functionName: "splitsOf",
          args: [projectId, BigInt(ruleset.id), RESERVED_TOKEN_SPLIT_GROUP_ID],
        }) as Promise<readonly RawSplit[]>,
      ]);
      const pair = decoded as unknown as [unknown, RulesetMetadata];
      return { ruleset, metadata: pair[1], splits };
    }),
  );

  const contexts = await getAccountingContexts(client, { chainId, projectId });
  if (!contexts.length) throw new Error("No reserve asset could be verified.");
  const hasEth = contexts.some(
    (context) => context.token.toLowerCase() === NATIVE_TOKEN.toLowerCase(),
  );
  const hasUsdc = contexts.some(
    (context) => context.token.toLowerCase() === USDC_ADDRESSES[chainId].toLowerCase(),
  );
  const custom = contexts.filter(
    (context) =>
      context.token.toLowerCase() !== NATIVE_TOKEN.toLowerCase() &&
      context.token.toLowerCase() !== USDC_ADDRESSES[chainId].toLowerCase(),
  );
  if (custom.length > 1 || (custom.length && contexts.length > 1)) {
    throw new Error("This reserve-asset combination cannot be reproduced by the create flow.");
  }
  const customSymbol = custom[0]
    ? await client
        .readContract({
          address: custom[0].token,
          abi: [
            {
              name: "symbol",
              type: "function",
              stateMutability: "view",
              inputs: [],
              outputs: [{ type: "string" }],
            },
          ],
          functionName: "symbol",
        })
        .catch(() => "")
    : "";

  const warnings: string[] = [];
  warnings.push(
    "Shop inventory added after deployment is not part of this file; the new revnet starts with an empty shop.",
  );
  if (projects.length > 1) {
    warnings.push(
      "Stages and split beneficiaries were reconstructed from this chain. Review the per-chain operator, beneficiaries, and reserve assets before redeploying.",
    );
  }
  const stages: StageData[] = stageReads.map((entry, index) => {
    const reservedPercent = Number(entry.metadata.reservedPercent) / 100;
    const startDeltaDays =
      index === 0
        ? 0
        : Math.max(
            0,
            (Number(entry.ruleset.start) - Number(stageReads[index - 1].ruleset.start)) / 86_400,
          );
    const splits = entry.splits.map((split) => {
      if (
        split.projectId > 0n ||
        split.hook.toLowerCase() !== zeroAddress ||
        split.preferAddToBalance ||
        Number(split.lockedUntil) > 0
      ) {
        throw new Error(
          "A deployed reserved-token split uses routing or locking the Revnet create flow cannot reproduce.",
        );
      }
      return {
        percentage: String(
          Number((reservedPercent * (Number(split.percent) / SPLITS_TOTAL)).toFixed(6)),
        ),
        defaultBeneficiary: split.beneficiary,
      };
    });
    const stored = autoIssuances
      .filter((row) => row.stageIndex === index)
      .map((row) => ({
        amount: formatUnits(BigInt(String(row.count).split(".")[0] || "0"), 18),
        beneficiary: row.beneficiary,
        chainId: row.chainId as JBChainId,
      }));
    const inherits = BigInt(entry.ruleset.weight) === RULESET_WEIGHT_INHERIT;
    return {
      initialIssuance: inherits ? "" : formatUnits(BigInt(entry.ruleset.weight), 18),
      pickUpFromPrevious: inherits,
      priceCeilingIncreasePercentage: String(
        Number((Number(entry.ruleset.weightCutPercent) / 10_000_000).toFixed(6)),
      ),
      priceCeilingIncreaseFrequency: String(
        Number((Number(entry.ruleset.duration) / 86_400).toFixed(6)),
      ),
      priceFloorTaxIntensity: String(
        Number((Number(entry.metadata.cashOutTaxRate) / 100).toFixed(2)),
      ),
      extraMetadata: Number(entry.metadata.metadata ?? 0),
      autoIssuance: stored,
      splits,
      stageStart: String(Number(startDeltaDays.toFixed(6))),
    };
  });

  const chainIds = projects.map((project) => project.chainId as JBChainId);
  const reserveAsset: RevnetFormData["reserveAsset"] = custom.length
    ? "CUSTOM"
    : hasEth && hasUsdc
      ? "ETH_USDC"
      : hasUsdc
        ? "USDC"
        : "ETH";
  const data: RevnetFormData = {
    ...DEFAULT_FORM_DATA,
    name: typeof metadata.name === "string" ? metadata.name : "",
    description: typeof metadata.description === "string" ? metadata.description : "",
    logoUri: typeof metadata.logoUri === "string" ? metadata.logoUri : "",
    twitter: typeof metadata.twitter === "string" ? metadata.twitter : "",
    telegram: typeof metadata.telegram === "string" ? metadata.telegram : "",
    discord: typeof metadata.discord === "string" ? metadata.discord : "",
    infoUri: typeof metadata.infoUri === "string" ? metadata.infoUri : "",
    tokenSymbol,
    stages,
    chainIds,
    operator: chainIds.map((id) => ({ chainId: String(id), address: operator })),
    reserveAsset,
    issuanceBaseCurrency: Number(stageReads[0].metadata.baseCurrency) === 2 ? "USD" : "ETH",
    customReserveAsset: {
      address: custom[0]?.token ?? "",
      symbol: String(customSymbol || ""),
      decimals: custom[0]?.decimals ?? null,
      verifiedChainIds: custom.length ? [chainId] : [],
    },
  };
  return { file: { v: 1, app: "revnet.money", data }, warnings };
}

import { jbCenterBaseUrl } from "@/lib/jbcenter-config";
import {
  JBCENTER_DEFAULT_URL,
  JBCenterRequestError,
  JBCenterTimeoutError,
  createJBCenterClient,
  type JBCenterClientOptions,
  type JBCenterJsonObject,
  type JBCenterPin,
} from "@bananapus/nana-sdk-core/jbcenter";

export const JBCENTER_IPFS_GATEWAY = `${JBCENTER_DEFAULT_URL}/ipfs/`;
export const JBCENTER_MAX_IMAGE_BYTES = 25 * 1024 * 1024;
export const JBCENTER_MAX_MEDIA_BYTES = 500 * 1024 * 1024;
/** CIDv0 of a zero-byte file — what a pin returns when the browser handed us an
 *  empty File (undownloaded cloud files, cross-site drags) or the body was lost. */
const EMPTY_FILE_CID = "QmbFMke1KXqnYyBBWxB74N4c5SBnJMVAiMNRcGu6x1AwQH";

type BrowserClientOptions = Pick<JBCenterClientOptions, "baseUrl" | "fetch">;

export type JBCenterIpfsClient = {
  pinJson(value: Record<string, unknown>): Promise<JBCenterPin>;
  pinImage(file: File): Promise<JBCenterPin>;
  pinMedia(file: File): Promise<JBCenterPin>;
};

/**
 * Browser-only Juicebox Center IPFS adapter.
 *
 * Approved web clients call Center directly and let the browser send its
 * `Origin`. Never add a Center API key here: a NEXT_PUBLIC key is public, and
 * server keys are for non-browser integrations only.
 */
export function createJBCenterIpfsClient(options: BrowserClientOptions = {}): JBCenterIpfsClient {
  const center = createJBCenterClient({
    baseUrl: jbCenterBaseUrl(),
    ...options,
  });

  const friendly = async <T>(label: string, request: Promise<T>): Promise<T> => {
    try {
      return await request;
    } catch (error) {
      if (error instanceof JBCenterRequestError || error instanceof JBCenterTimeoutError) {
        throw new Error(`${label}: ${error.message}`, { cause: error });
      }
      throw new Error(`${label} — try again.`, { cause: error });
    }
  };

  const nonEmpty = async (file: File, request: Promise<JBCenterPin>) => {
    if (file.size === 0) {
      throw new Error(
        `"${file.name || "file"}" is empty (0 bytes). If it lives in iCloud or another cloud drive, open it on this device first, then choose it again.`,
      );
    }
    const pin = await request;
    if (pin.cid === EMPTY_FILE_CID) {
      throw new Error(
        `"${file.name || "file"}" uploaded as empty. Choose the file again and retry.`,
      );
    }
    return pin;
  };

  return {
    pinJson(value) {
      let json: unknown;
      try {
        json = JSON.parse(JSON.stringify(value));
      } catch (error) {
        throw new Error("This metadata cannot be represented as JSON.", { cause: error });
      }
      if (typeof json !== "object" || json === null || Array.isArray(json)) {
        throw new Error("Metadata must be a JSON object.");
      }
      return friendly("Saving metadata failed", center.pinJson(json as JBCenterJsonObject));
    },
    pinImage(file) {
      return nonEmpty(
        file,
        friendly("Image upload failed", center.pinImage(file, { filename: file.name || "image" })),
      );
    },
    pinMedia(file) {
      return nonEmpty(
        file,
        friendly("Media upload failed", center.pinMedia(file, { filename: file.name || "media" })),
      );
    },
  };
}

export const jbCenterIpfs = createJBCenterIpfsClient();

import {
  createJBCenterIpfsClient,
  JBCENTER_MAX_IMAGE_BYTES,
  JBCENTER_MAX_MEDIA_BYTES,
} from "@/lib/jbcenter-ipfs";
import { afterEach, describe, expect, it, vi } from "vitest";

const CID = "QmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR";
const PIN = {
  cid: CID,
