import { jbRouterTerminalRegistryAbi, NATIVE_TOKEN } from "@bananapus/nana-sdk-core";
import {
  parseTierMetadataJson,
  tierDisplayMetadata as sdkTierDisplayMetadata,
  tierMediaAssetUrl as sdkTierMediaAssetUrl,
  tierMediaImageUrl as sdkTierMediaImageUrl,
  TIER_UNLIMITED_SUPPLY,
  tokenCurrencyId,
  type TierMetadata,
} from "@bananapus/nana-sdk-core/v6";
import { Address, formatUnits, PublicClient } from "viem";

/** The v6 pay card's modes: mint tokens, or top up the balance minting nothing. */
export type V6PayMode = "pay" | "addbalance";

/** A token the pay card can pay with, resolved on-chain per selected chain. */
export interface V6PayTokenOption {
  token: Address;
  decimals: number;
  /** Accounting-context currency id (`uint32(uint160(token))` for router tokens). */
  currency: number;
  symbol: string;
  /**
   * True when the token is NOT accepted directly and is paid through the
   * JBRouterTerminalRegistry (which swaps it into the accounting token).
   */
  viaRouter: boolean;
}

/**
 * A stable identity for a pay token — the same token can appear both directly
 * AND via-router, so the key must include the route (website/ fund-loss fix).
 */
export function payTokenKey(t: Pick<V6PayTokenOption, "token" | "viaRouter">): string {
  return `${t.token.toLowerCase()}:${t.viaRouter}`;
}

export function isNativePayToken(address: string): boolean {
  return address.toLowerCase() === NATIVE_TOKEN.toLowerCase();
}

/** Accounting-context currency id for a token (`uint32(uint160(token))`). */
export function payTokenCurrencyId(token: Address): number {
  return tokenCurrencyId(token);
}

const ROUTER_PROBE_BENEFICIARY: Address = "0x0000000000000000000000000000000000000001";

/**
 * Whether the router registry can actually route a pay of `token` into
 * `projectId` right now (direct forward, swap, or cash-out loop). A listed
 * router with no pool/feed path reverts at pay time — offering ETH/USDC there
 * is a trap, not a convenience — so a dead route previews an all-zero ruleset
 * (ruleset.id == 0). Cached (as a promise) per (chain, project, token), exactly
 * like website/'s _payRouteCache. Fail-soft: any error resolves false.
 */
const payRouteCache = new Map<string, Promise<boolean>>();
export function routerPayRouteWorks(
  client: PublicClient,
  chainId: number,
  projectId: bigint,
  registry: Address,
  token: Address,
  decimals: number,
): Promise<boolean> {
  const key = `${chainId}:${projectId}:${registry.toLowerCase()}:${token.toLowerCase()}`;
  let cached = payRouteCache.get(key);
  if (!cached) {
    cached = client
      .readContract({
        address: registry,
        abi: jbRouterTerminalRegistryAbi,
        functionName: "previewPayFor",
        args: [projectId, token, 10n ** BigInt(decimals), ROUTER_PROBE_BENEFICIARY, "0x"],
      })
      .then((out) => {
        // previewPayFor returns [ruleset, ...]; a dead route yields ruleset.id == 0.
        const ruleset = (out as readonly [{ id: number | bigint }, ...unknown[]])[0];
        return Number(ruleset?.id ?? 0) !== 0;
      })
      .catch(() => false);
    payRouteCache.set(key, cached);
  }
  return cached;
}

export { parseTierMetadataJson, TIER_UNLIMITED_SUPPLY };
export type TierDisplayMetadata = TierMetadata;

const APP_IPFS_GATEWAY = "https://juicebox.center/ipfs/";

/**
 * The one tier-media resolution chain (shop tab AND pay strip): pick the
 * shared fields, then normalize `image`/`animation_url` into URLs an <img>
 * can actually load (SVG-wrapper unwrapping + IPFS gateway routing).
 */
export function tierDisplayMetadata(json: Record<string, unknown>): TierDisplayMetadata {
  return sdkTierDisplayMetadata(json, APP_IPFS_GATEWAY);
}

/**
 * Make a tier media URL loadable from the browser. IPFS-addressed URLs —
 * ipfs:// URIs AND ones hot-linked to somebody else's gateway host (Banny
 * resolver SVGs point at bannyverse.infura-ipfs.io) — are re-routed through
 * Juicebox Center's open gateway: the CID path is immutable, so it serves the same
 * bytes without depending on a third-party host staying up (juicy-vision/
 * website parity; public gateways 504 on cold DHT lookups for these CIDs).
 */
export function tierMediaAssetUrl(value: unknown): string | undefined {
  return sdkTierMediaAssetUrl(value, APP_IPFS_GATEWAY);
}

/**
 * Make a metadata image renderable in an <img>. Resolvers sometimes return an
 * SVG data URI that merely wraps an external `<image href="…">` (Banny
 * accessories) — browsers block external loads inside an <img> data URI, so
 * pull the href out and load the bitmap directly (through the gateway, see
 * tierMediaAssetUrl). Self-contained SVGs pass through untouched.
 */
export function tierMediaImageUrl(image: unknown): string | undefined {
  return sdkTierMediaImageUrl(image, APP_IPFS_GATEWAY);
}

/** "3d 4h" / "2h 10m" / "5m" countdown label for a ruleset that hasn't started. */
export function formatStartCountdown(secs: number): string {
  if (secs <= 0) return "moments";
  const d = Math.floor(secs / 86400);
  if (d >= 1) return `${d}d ${Math.floor((secs % 86400) / 3600)}h`;
  const h = Math.floor(secs / 3600);
  if (h >= 1) return `${h}h ${Math.floor((secs % 3600) / 60)}m`;
  return `${Math.max(1, Math.floor(secs / 60))}m`;
}

/** Localized token-amount label with sensible fraction digits for the pay card. */
export function formatPayAmount(value: bigint, decimals: number): string {
  const num = Number(formatUnits(value, decimals));
  if (!Number.isFinite(num)) return formatUnits(value, decimals);
  return num.toLocaleString("en-US", {
    maximumFractionDigits: num !== 0 && num < 1 ? 6 : 4,
  });
}

import { routerEntriesFor } from "@/lib/protocol-rollout";
import {
  getJBContractAddress,
  JBChainId,
  jbContractAddress,
  jbMultiTerminalAbi,
  JBRouterTerminalContracts,
  jbRouterTerminalRegistryAbi,
} from "@bananapus/nana-sdk-core";
import { PayPreview, previewPay } from "@bananapus/nana-sdk-core/v6";
import { Address, PublicClient } from "viem";

export type PaymentTerminalType = "multi" | "swap";

type PaymentTerminal = {
  address: Address;
  abi: typeof jbMultiTerminalAbi | typeof jbRouterTerminalRegistryAbi;
  type: PaymentTerminalType;
};

export type V6PayRoute = PaymentTerminal & { preview: PayPreview };

/**
 * Resolve the best v6 pay route by previewing both the multi terminal and the router
 * terminal registry, keeping whichever mints the beneficiary the most project tokens.
 * Candidates whose preview reverts (e.g. no accounting context for the token) are
 * skipped, so a surviving route always carries a live quote.
 */
export async function resolveBestV6PayRoute(args: {
  client: PublicClient;
  chainId: JBChainId;
  projectId: bigint;
  token: Address;
  amount: bigint;
  beneficiary: Address;
  attachedTerminals?: readonly Address[];
}): Promise<V6PayRoute | null> {
  const { client, chainId, projectId, token, amount, beneficiary } = args;

  const previews = await Promise.all(
    v6PayRouteCandidates(chainId, args.attachedTerminals).map(async (route) => {
      try {
        const preview = await previewPay(client, {
          chainId,
          terminal: route.address,
          projectId,
          token,
          amount,
          beneficiary,
          metadata: "0x",
        });
        return { ...route, preview };
      } catch {
        return null;
      }
    }),
  );

  let best: V6PayRoute | null = null;
  for (const route of previews) {
    if (!route) continue;
    if (!best || v6PayRouteIsBetter(route, best)) best = route;
  }
  return best;
}

function v6PayRouteCandidates(
  chainId: JBChainId,
  attachedTerminals?: readonly Address[],
): PaymentTerminal[] {
  const routes: PaymentTerminal[] = [];

  if (attachedTerminals) {
    routes.push(
      ...routerEntriesFor(chainId, attachedTerminals).map((address) => ({
        address,
        abi: jbRouterTerminalRegistryAbi,
        type: "swap" as const,
      })),
    );
  } else
    try {
      routes.push({
        address: getJBContractAddress(
          JBRouterTerminalContracts.JBRouterTerminalRegistry,
          6,
          chainId,
        ),
        abi: jbRouterTerminalRegistryAbi,
        type: "swap",
      });
    } catch {
      // Router registry not deployed on this chain.
    }

  const multi = jbContractAddress[6].JBMultiTerminal[chainId];
  if (
    multi &&
    (!attachedTerminals ||
      attachedTerminals.some((address) => address.toLowerCase() === multi.toLowerCase())) &&
    !routes.some((route) => route.address.toLowerCase() === multi.toLowerCase())
  ) {
    routes.push({ address: multi, abi: jbMultiTerminalAbi, type: "multi" });
  }

  return routes;
}

function v6PayRouteIsBetter(candidate: V6PayRoute, current: V6PayRoute): boolean {
  if (candidate.preview.beneficiaryTokenCount !== current.preview.beneficiaryTokenCount) {
    return candidate.preview.beneficiaryTokenCount > current.preview.beneficiaryTokenCount;
  }
  const candidateTotal =
    candidate.preview.beneficiaryTokenCount + candidate.preview.reservedTokenCount;
  const currentTotal = current.preview.beneficiaryTokenCount + current.preview.reservedTokenCount;
  if (candidateTotal !== currentTotal) return candidateTotal > currentTotal;

  // Prefer the direct multi terminal over the router when quotes tie.
  return candidate.type === "multi" && current.type !== "multi";
}

"use client";

import { useViewedAccount } from "@/hooks/useViewedAccount";
import { payTokenKey, V6PayTokenOption } from "@/lib/v6/pay";
import {
  jb721TiersHookAbi,
  JBChainId,
  jbContractAddress,
  JBCoreContracts,
  jbPricesAbi,
  NATIVE_TOKEN,
} from "@bananapus/nana-sdk-core";
import { BASE_CURRENCY_ETH, BASE_CURRENCY_USD } from "@bananapus/nana-sdk-core/v6";
import { useQuery } from "@tanstack/react-query";
import { Address, BaseError, ContractFunctionRevertedError, PublicClient } from "viem";
import { usePublicClient } from "wagmi";
import { loadShopInventory } from "../shop/shopLib";

export interface V6PayShopTier {
  id: number;
  /** Full (undiscounted) price in the shop's pricing units. */
  price: bigint;
  /** Out of 200 (DISCOUNT_DENOMINATOR). */
  discountPercent: number;
  remaining: number;
  unlimited: boolean;
  /** True when shop credits can't fund this tier — fresh payment required. */
  cantBuyWithCredits: boolean;
  /** tokenUriResolver output (data URI), "" when the hook has no resolver. */
  resolvedUri: string;
  encodedIpfsUri: `0x${string}`;
}

export interface V6PayShop {
  hook: Address;
  /**
   * The metadata id target — the hook's METADATA_ID_TARGET (the shared
   * implementation), NOT the clone. Keying by the clone address makes the
   * hook miss the tier ids entirely: payment goes through, no NFT mints.
   */
  idTarget: Address;
  pricingCurrency: number;
  pricingDecimals: number;
  tiers: V6PayShopTier[];
}

export interface V6ShopPayRoute {
  supported: boolean;
  /** Payment-token units per one whole shop-pricing unit. */
  pricePerUnit: bigint | null;
  reason?: string;
  /** The feed could not be READ, as opposed to not existing. Temporary, and worth retrying. */
  unavailable?: boolean;
}

/** The project's 721 shop (hook + tiers) on the selected chain, or null. */
export function usePayShop(chainId: JBChainId, projectId: bigint) {
  const publicClient = usePublicClient({ chainId });

  return useQuery({
    queryKey: ["v6PayShop", chainId, projectId.toString()],
    enabled: !!publicClient,
    staleTime: 120_000,
    retry: 1,
    queryFn: async (): Promise<V6PayShop | null> => {
      const client = publicClient as PublicClient;
      // Share the Shop tab's bounded, non-resolving inventory read. Asking the
      // store to resolve every token URI in one RPC call can revert for larger
      // collections and used to make the pay-card strip disappear entirely.
      const resolved = await loadShopInventory(client, chainId, projectId);
      if (!resolved) return null;
      return {
        hook: resolved.hook,
        idTarget: resolved.idTarget,
        pricingCurrency: resolved.pricing.currency,
        pricingDecimals: resolved.pricing.decimals,
        tiers: resolved.tiers.map((t) => ({
          id: t.id,
          price: t.price,
          discountPercent: t.discountPercent,
          remaining: t.remaining,
          unlimited: t.unlimited,
          // Fail closed if the store doesn't return flags: charging fresh
          // funds is safer than underfunding a credit-restricted mint.
          cantBuyWithCredits: t.flags?.cantBuyWithCredits ?? true,
          // Display metadata resolves through the shared useTierMedia chain.
          resolvedUri: t.resolvedUri ?? "",
          encodedIpfsUri: t.encodedIpfsUri,
        })),
      };
    },
  });
}

/** The connected wallet's shop credits (`payCreditsOf`) on the hook. */
export function usePayShopCredits(chainId: JBChainId, hook: Address | undefined) {
  const publicClient = usePublicClient({ chainId });
  const { address } = useViewedAccount();

  return useQuery({
    queryKey: ["v6PayShopCredits", chainId, hook, address],
    enabled: !!publicClient && !!hook && !!address,
    staleTime: 15_000,
    retry: 1,
    queryFn: () =>
      (publicClient as PublicClient).readContract({
        address: hook!,
        abi: jb721TiersHookAbi,
        functionName: "payCreditsOf",
        args: [address!],
      }),
  });
}

/**
 * Verify every accepted token against the shop's pricing context. JBPrices
 * returns payment-token units per one whole shop-pricing unit; router inputs
 * stay unsupported because the hook only sees the post-swap token.
 */
export function usePayShopRoutes(
  chainId: JBChainId,
  projectId: bigint,
  shop: V6PayShop | null | undefined,
  tokens: V6PayTokenOption[],
) {
  const publicClient = usePublicClient({ chainId });

  return useQuery({
    queryKey: [
      "v6PayShopRoutes",
      chainId,
      projectId.toString(),
      shop?.pricingCurrency,
      shop?.pricingDecimals,
      tokens.map(payTokenKey).join(","),
    ],
    enabled: !!publicClient && !!shop && tokens.length > 0,
    staleTime: 60_000,
    retry: 1,
    queryFn: async (): Promise<Record<string, V6ShopPayRoute>> => {
      const prices = jbContractAddress[6][JBCoreContracts.JBPrices][chainId];
      const entries = await Promise.all(
        tokens.map(async (payToken) => {
          const key = payTokenKey(payToken);
          if (payToken.viaRouter) {
            return [
              key,
              {
                supported: false,
                pricePerUnit: null,
                reason: "Item checkout requires a directly accepted token.",
              },
            ] as const;
          }

          const sameCurrency =
            payToken.currency === shop!.pricingCurrency ||
            (shop!.pricingCurrency === BASE_CURRENCY_ETH &&
              payToken.token.toLowerCase() === NATIVE_TOKEN.toLowerCase());
          if (sameCurrency) {
            return [
              key,
              { supported: true, pricePerUnit: 10n ** BigInt(payToken.decimals) },
            ] as const;
          }

          if (!prices) {
            return [
              key,
              {
                supported: false,
                pricePerUnit: null,
                reason: "No price contract is available on this chain.",
              },
            ] as const;
          }
          // A REVERT is JBPrices_PriceFeedNotFound: this pair genuinely has no feed, and saying
          // so is a true statement about the protocol. A network failure is not — it used to
          // collapse into the same `0n` and produce the same permanent-sounding verdict about
          // a momentary outage. Both still fail closed; only the explanation differs.
          let pricePerUnit: bigint;
          try {
            pricePerUnit = await (publicClient as PublicClient).readContract({
              address: prices,
              abi: jbPricesAbi,
              functionName: "pricePerUnitOf",
              args: [
                projectId,
                BigInt(payToken.currency),
                BigInt(shop!.pricingCurrency),
                BigInt(payToken.decimals),
              ],
            });
          } catch (error) {
            return [
              key,
              contractReverted(error)
                ? {
                    supported: false,
                    pricePerUnit: null,
                    reason: "No price feed converts this payment token.",
                  }
                : {
                    supported: false,
                    pricePerUnit: null,
                    unavailable: true,
                    reason: "Couldn't check this token's price feed. Try again in a moment.",
                  },
            ] as const;
          }
          return [
            key,
            pricePerUnit > 0n
              ? { supported: true, pricePerUnit }
              : {
                  supported: false,
                  pricePerUnit: null,
                  reason: "No price feed converts this payment token.",
                },
          ] as const;
        }),
      );
      return Object.fromEntries(entries);
    },
  });
}

/** A revert (as opposed to a transport failure) means the chain answered — so the absence of
 *  a feed is a fact about the protocol, not about the network. */
function contractReverted(error: unknown): boolean {
  return (
    error instanceof BaseError &&
    !!error.walk((cause) => cause instanceof ContractFunctionRevertedError)
  );
}

