  });
  mocks.signTypedData.mockResolvedValue(SIGNATURE);
});

describe("reviewed Permit2 signature boundary", () => {
  it("reviews and signs the exact short-lived PermitSingle payload", async () => {
    const order: string[] = [];
    const review = await import("@/lib/transaction-review");
    const dispose = review.registerTransactionReviewHandler(async (request) => {
      order.push("review");
      expect(request).toMatchObject({
        kind: "authorization",
        calls: [],
        authorization: {
          domain: {
            name: "Permit2",
            chainId: 8453,
          },
          primaryType: "PermitSingle",
          message: {
            details: { token: TOKEN, amount: 25_000_000n, nonce: 7 },
            spender: ROUTER,
          },
        },
      });
      return true;
    });
    mocks.signTypedData.mockImplementation(async () => {
      order.push("sign");
      return SIGNATURE;
    });

    const { result } = renderHook(() => useReviewedPermit2Signature());
    let signature: Hex | undefined;
    await act(async () => {
      signature = await result.current.signPermit2Async({
        expectedAccount: ACCOUNT,
        authorization,
      });
    });

    expect(signature).toBe(SIGNATURE);
    expect(order).toEqual(["review", "sign"]);
    expect(mocks.switchChain).toHaveBeenCalledWith({ chainId: 8453 });
    expect(mocks.signTypedData).toHaveBeenCalledWith(
      expect.objectContaining({
        account: ACCOUNT,
        primaryType: "PermitSingle",
        message: expect.objectContaining({ spender: ROUTER }),
      }),
    );
    dispose();
  });

  it("fails closed if the connected account changes after signing", async () => {
    mocks.account = { address: ACCOUNT, chainId: 8453 };
    mocks.signTypedData.mockImplementation(async () => {
      mocks.account = { address: OTHER_ACCOUNT, chainId: 8453 };
      return SIGNATURE;
    });
    const { result } = renderHook(() => useReviewedPermit2Signature({ reviewedInParent: true }));

    await expect(
      result.current.signPermit2Async({ expectedAccount: ACCOUNT, authorization }),
    ).rejects.toThrow(/changed after signing/i);
  });
});

import {
  BENDYSTRAW_PROJECT_REF_BATCH_SIZE,
  bendystrawProjectRefFilter,
  bendystrawProjectRefsFilters,
  matchesBendystrawProjectRef,
  type BendystrawFilter,
  type BendystrawProjectRef,
} from "@bananapus/nana-sdk-core";

export type VersionedProjectRef = Required<BendystrawProjectRef>;

/** Keep exact-ref OR filters small enough for the indexer's input parser. */
export const REF_LOOKUP_BATCH_SIZE = BENDYSTRAW_PROJECT_REF_BATCH_SIZE;

export function projectRefKey(ref: VersionedProjectRef): string {
  bendystrawProjectRefFilter(ref);
  return `${ref.chainId}:${ref.projectId}:${ref.version}`;
}

/** A filter matching every unique ref exactly, or null for an empty input. */
export function projectRefsWhere(refs: readonly VersionedProjectRef[]): BendystrawFilter | null {
  if (refs.length === 0) return null;
  const batches = projectRefsWheres(refs);
  if (batches.length > 1) {
    throw new Error("Use projectRefsWheres for more than 200 project references.");
  }
  return batches[0] ?? null;
}

/** Exact project-ref filters in complete, independently queryable batches. */
export function projectRefsWheres(refs: readonly VersionedProjectRef[]): BendystrawFilter[] {
  return bendystrawProjectRefsFilters(refs);
}

/** Raw GraphQL equivalent for the one dynamic query which cannot use variables. */
export function projectRefGraphqlInput(ref: VersionedProjectRef): string {
  bendystrawProjectRefFilter(ref);
  return `{ AND: [{ chainId: ${ref.chainId} }, { projectId: ${ref.projectId} }, { version: ${ref.version} }] }`;
}

export function matchesProjectRef(
  row: VersionedProjectRef,
  refs: readonly VersionedProjectRef[],
): boolean {
  return matchesBendystrawProjectRef(row, refs);
}

import {
  BENDYSTRAW_TIMEOUT_MS,
  BendystrawRequestError as BendystrawError,
  assertBendystrawData,
  assertBendystrawVariables,
  resolveBendystrawNetwork,
} from "@bananapus/nana-sdk-core";
import type { BendystrawOperation } from "./operations";

export function bendystrawNetworkFor(
  variables: Record<string, unknown>,
  chainId?: number,
): "mainnet" | "testnet" {
  return resolveBendystrawNetwork({ chainId, variables });
}

export async function queryBendystrawFromBrowser<
  TResult,
  TVariables extends Record<string, unknown>,
>(
  operation: BendystrawOperation<TResult, TVariables>,
  variables: TVariables,
  chainId?: number,
): Promise<TResult> {
  assertBendystrawVariables(variables, operation.validateVariables, operation.id);

  const network = bendystrawNetworkFor(variables, chainId);
  const response = await fetch(`/api/bendystraw/${network}/query`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ operation: operation.id, variables }),
    cache: "no-store",
    signal: AbortSignal.timeout(BENDYSTRAW_TIMEOUT_MS),
  });

  let envelope: { data?: unknown; error?: unknown };
  try {
    envelope = (await response.json()) as { data?: unknown; error?: unknown };
  } catch {
    throw new BendystrawError("Bendystraw proxy returned invalid JSON", 502);
  }
  if (!response.ok) {
    throw new BendystrawError(
      typeof envelope.error === "string" ? envelope.error : "Bendystraw request failed",
      response.status,
    );
  }
  return assertBendystrawData(envelope.data, operation.validateData, operation.id);
}

