"use client";

import {
  SAFE_TX_TYPES,
  safeMessage,
  safeTransactionHash,
  type SafeQueuedTransaction,
} from "@/lib/safe-queue";
import { requireTransactionReview } from "@/lib/transaction-review";
import { requireNoViewAs } from "@/lib/view-as";
import { useCallback } from "react";
import { type Address, type Hex } from "viem";
import { useConfig, useSwitchChain } from "wagmi";
import { getAccount, getWalletClient } from "wagmi/actions";

export type ReviewedSafeSignatureRequest = {
  chainId: number;
  safe: Address;
  tx: SafeQueuedTransaction;
  /** Re-authenticate the Safe/owner after review and chain switching. */
  reverify?: (account: Address) => Promise<void>;
};

function exactSafeDigest(
  chainId: number,
  safe: Address,
  tx: SafeQueuedTransaction,
  expected?: Hex,
): Hex {
  const digest = safeTransactionHash(chainId, safe, tx);
  const serviceHash = tx.safeTxHash ?? tx.contractTransactionHash;
  if (serviceHash && serviceHash.toLowerCase() !== digest.toLowerCase()) {
    throw new Error("Safe service transaction data does not match its signed hash.");
  }
  if (expected && expected.toLowerCase() !== digest.toLowerCase()) {
    throw new Error("The Safe transaction changed while the wallet signature was pending.");
  }
  return digest;
}

export function useReviewedSafeSignature() {
  const config = useConfig();
  const { switchChainAsync } = useSwitchChain();

  const signSafeTransactionAsync = useCallback(
    async ({ chainId, safe, tx, reverify }: ReviewedSafeSignatureRequest): Promise<Hex> => {
      requireNoViewAs();
      const before = getAccount(config);
      if (!before.address) throw new Error("Connect a wallet first.");

      const digest = exactSafeDigest(chainId, safe, tx);

      await requireTransactionReview({
        kind: "authorization",
        title: "Review Safe transaction signature",
        description:
          "This signature approves the exact queued Safe call. It does not execute until the threshold and nonce requirements are met.",
        confirmLabel: "Agree & sign Safe transaction",
        authorization: {
          type: "EIP-712 SafeTx",
          safe,
          nonce: tx.nonce,
          digest,
          message: safeMessage(tx),
        },
        calls: [
          {
            chainId,
            from: before.address,
            to: tx.to,
            value: BigInt(tx.value ?? 0),
            data: tx.data ?? "0x",
            label: `Safe transaction #${tx.nonce}`,
          },
        ],
      });

      await switchChainAsync({ chainId });
      const after = getAccount(config);
      if (
        !after.address ||
        after.address.toLowerCase() !== before.address.toLowerCase() ||
        after.chainId !== chainId
      ) {
        throw new Error("Connected account or network changed. Review the Safe transaction again.");
      }
      await reverify?.(after.address);
      const reverified = getAccount(config);
      if (
        !reverified.address ||
        reverified.address.toLowerCase() !== after.address.toLowerCase() ||
        reverified.chainId !== chainId
      ) {
        throw new Error("Connected account or network changed. Review the Safe transaction again.");
      }
      const wallet = await getWalletClient(config, { chainId, account: after.address });
      if (
        !wallet.account ||
        wallet.account.address.toLowerCase() !== before.address.toLowerCase()
      ) {
        throw new Error("Connected account changed. Review the Safe transaction again.");
      }
      const signature = await wallet.signTypedData({
        account: wallet.account,
        domain: { chainId, verifyingContract: safe },
        types: SAFE_TX_TYPES,
        primaryType: "SafeTx",
        message: safeMessage(tx),
      });
      const signedAccount = getAccount(config);
      if (
        !signedAccount.address ||
        signedAccount.address.toLowerCase() !== before.address.toLowerCase() ||
        signedAccount.chainId !== chainId
      ) {
        throw new Error("Connected account or network changed. Review the Safe transaction again.");
      }
      // A wallet prompt has no time bound. Re-authenticate the live project
      // Safe after it closes, before the caller can POST this signature to the
      // transaction service, and prove the signed payload stayed exact.
      await reverify?.(signedAccount.address);
      exactSafeDigest(chainId, safe, tx, digest);
      const postverified = getAccount(config);
      if (
        !postverified.address ||
        postverified.address.toLowerCase() !== signedAccount.address.toLowerCase() ||
        postverified.chainId !== chainId
      ) {
        throw new Error("Connected account or network changed. Review the Safe transaction again.");
      }
      return signature;
    },
    [config, switchChainAsync],
  );

  return { signSafeTransactionAsync };
}

import { useReviewedSafeSignature } from "@/hooks/useReviewedSafeSignature";
import { act, renderHook } from "@testing-library/react";
import { type Address, type Hex, zeroAddress } from "viem";
import { beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  config: { id: "safe-signature-config" },
  account: {
    address: "0x1111111111111111111111111111111111111111" as Address | undefined,
    chainId: 1 as number | undefined,
  },
  getAccount: vi.fn(),
  getWalletClient: vi.fn(),
  switchChain: vi.fn(),
  signTypedData: vi.fn(),
}));

vi.mock("wagmi", () => ({
  useConfig: () => mocks.config,
  useSwitchChain: () => ({ switchChainAsync: mocks.switchChain }),
}));

vi.mock("wagmi/actions", () => ({
  getAccount: mocks.getAccount,
  getWalletClient: mocks.getWalletClient,
}));

const ACCOUNT = "0x1111111111111111111111111111111111111111" as Address;
const SAFE = "0x2222222222222222222222222222222222222222" as Address;
const TARGET = "0x3333333333333333333333333333333333333333" as Address;
const SIGNATURE = `0x${"12".repeat(65)}` as Hex;
const tx = {
  to: TARGET,
  value: "7",
  data: "0x1234" as Hex,
  operation: 0,
  safeTxGas: "100",
  baseGas: "20",
  gasPrice: "1",
  gasToken: zeroAddress,
  refundReceiver: zeroAddress,
  nonce: 4,
};

beforeEach(() => {
  window.localStorage.clear();
  mocks.account = { address: ACCOUNT, chainId: 1 };
  mocks.getAccount.mockImplementation(() => mocks.account);
  mocks.switchChain.mockImplementation(async ({ chainId }: { chainId: number }) => {
    mocks.account = { ...mocks.account, chainId };
  });
  mocks.signTypedData.mockResolvedValue(SIGNATURE);
  mocks.getWalletClient.mockResolvedValue({
    account: { address: ACCOUNT },
    signTypedData: mocks.signTypedData,
  });
});

describe("reviewed Safe signature boundary", () => {
  // wallet-action:safe-signature-boundary
  it("reviews the exact Safe call before signing its EIP-712 payload", async () => {
    const events: string[] = [];
    const review = await import("@/lib/transaction-review");
    const dispose = review.registerTransactionReviewHandler(async (request) => {
      events.push("review");
      expect(request).toMatchObject({
        kind: "authorization",
        calls: [{ chainId: 8453, from: ACCOUNT, to: TARGET, value: 7n, data: "0x1234" }],
        authorization: {
          type: "EIP-712 SafeTx",
          safe: SAFE,
          nonce: 4,
        },
      });
      return true;
    });
    mocks.signTypedData.mockImplementation(async () => {
      events.push("sign");
      return SIGNATURE;
    });

    const { result } = renderHook(() => useReviewedSafeSignature());
    let signature: Hex | undefined;
    await act(async () => {
      signature = await result.current.signSafeTransactionAsync({
        chainId: 8453,
        safe: SAFE,
        tx,
      });
    });

    expect(signature).toBe(SIGNATURE);
    expect(events).toEqual(["review", "sign"]);
    expect(mocks.switchChain).toHaveBeenCalledWith({ chainId: 8453 });
    expect(mocks.signTypedData).toHaveBeenCalledWith(
      expect.objectContaining({
        account: { address: ACCOUNT },
        domain: { chainId: 8453, verifyingContract: SAFE },
        primaryType: "SafeTx",
      }),
    );
    dispose();
  });

  it("fails closed if the service hash does not match the reconstructed payload", async () => {
    const { result } = renderHook(() => useReviewedSafeSignature());

    await expect(
      result.current.signSafeTransactionAsync({
        chainId: 1,
        safe: SAFE,
        tx: { ...tx, safeTxHash: `0x${"ff".repeat(32)}` },
      }),
    ).rejects.toThrow("does not match");
    expect(mocks.switchChain).not.toHaveBeenCalled();
    expect(mocks.signTypedData).not.toHaveBeenCalled();
  });

  it("reverifies Safe authority before and after the wallet signs", async () => {
    const events: string[] = [];
    const review = await import("@/lib/transaction-review");
    const dispose = review.registerTransactionReviewHandler(async () => {
      events.push("review");
      return true;
    });
    mocks.signTypedData.mockImplementation(async () => {
      events.push("sign");
      return SIGNATURE;
    });
    const reverify = vi.fn(async () => {
      events.push("reverify");
    });
    const { result } = renderHook(() => useReviewedSafeSignature());

    await act(async () => {
      await result.current.signSafeTransactionAsync({
        chainId: 1,
        safe: SAFE,
        tx,
        reverify,
      });
    });

    expect(reverify).toHaveBeenCalledTimes(2);
    expect(reverify).toHaveBeenNthCalledWith(1, ACCOUNT);
    expect(reverify).toHaveBeenNthCalledWith(2, ACCOUNT);
    expect(events).toEqual(["review", "reverify", "sign", "reverify"]);
    dispose();
  });

  it("withholds a wallet-produced signature when Safe authority rotates during the prompt", async () => {
    const review = await import("@/lib/transaction-review");
    const dispose = review.registerTransactionReviewHandler(async () => true);
    const reverify = vi
      .fn()
      .mockResolvedValueOnce(undefined)
      .mockRejectedValueOnce(new Error("The Safe policy changed during signing."));
    const { result } = renderHook(() => useReviewedSafeSignature());

    await expect(
      result.current.signSafeTransactionAsync({
        chainId: 1,
        safe: SAFE,
        tx,
        reverify,
      }),
    ).rejects.toThrow("policy changed");
    expect(mocks.signTypedData).toHaveBeenCalledOnce();
    expect(reverify).toHaveBeenCalledTimes(2);
    dispose();
  });

  it("rejects a queued payload that changes while the wallet prompt is open", async () => {
    const review = await import("@/lib/transaction-review");
    const dispose = review.registerTransactionReviewHandler(async () => true);
    const mutableTx = { ...tx };
    mocks.signTypedData.mockImplementationOnce(async () => {
      mutableTx.nonce += 1;
      return SIGNATURE;
    });
    const { result } = renderHook(() => useReviewedSafeSignature());

    await expect(
      result.current.signSafeTransactionAsync({ chainId: 1, safe: SAFE, tx: mutableTx }),
    ).rejects.toThrow("changed while the wallet signature was pending");
    dispose();
  });
});

