    expect(mediaTypeForFile({ name: 'field-recording.flac', type: 'application/octet-stream' })).toBe('audio/flac');
    expect(mediaTypeForFile({ name: 'cover.png', type: 'image/custom; charset=binary' })).toBe('image/custom');
  });
});

