const chainId = 11155111;
const terminal = "0x1111111111111111111111111111111111111111" as const;
const holder = "0x2222222222222222222222222222222222222222" as const;
const beneficiary = "0x3333333333333333333333333333333333333333" as const;
const projectId = 3n;

describe("cashOut", () => {
  test("buildCashOutTx encodes cashOutTokensOf", () => {
    const tx = buildCashOutTx({
      chainId,
      terminal,
      holder,
      projectId,
      cashOutCount: ONE_ETHER,
      tokenToReclaim: NATIVE_TOKEN,
      beneficiary,
    });

    expect(tx.chainId).toEqual(chainId);
    expect(tx.address).toEqual(terminal);
    expect(tx.functionName).toEqual("cashOutTokensOf");
    expect(tx.args).toEqual([
      holder,
      projectId,
      ONE_ETHER,
      NATIVE_TOKEN,
      0n,
      beneficiary,
      "0x",
    ]);
    expect(() => encodeFunctionData(tx)).not.toThrow();
  });

  test("buildCashOutTx passes minTokensReclaimed and metadata through", () => {
    const tx = buildCashOutTx({
      chainId,
      terminal,
      holder,
      projectId,
      cashOutCount: ONE_ETHER,
      tokenToReclaim: NATIVE_TOKEN,
      minTokensReclaimed: 999n,
      beneficiary,
      metadata: "0x1234",
    });

    expect(tx.args[4]).toEqual(999n);
    expect(tx.args[6]).toEqual("0x1234");
    expect(() => encodeFunctionData(tx)).not.toThrow();
  });

  test("getCashOutQuote reads the terminal store; the fee stays unresolved without the tax rate", async () => {
    const calls: any[] = [];
    const client = {
      async readContract(params: unknown) {
        calls.push(params);
        return ONE_ETHER;
      },
    } as unknown as PublicClient;

    const quote = await getCashOutQuote(client, {
      chainId,
      projectId,
      cashOutCount: ONE_ETHER,
    });

    expect(quote.reclaimAmount).toEqual(ONE_ETHER);
    // The protocol fee is conditional on the ruleset's cash-out tax rate (and,
    // at zero tax, on feeFreeSurplusOf) — without those inputs the net amount
    // is unresolved, never fabricated.
    expect(quote.reclaimAmountAfterFee).toBeUndefined();

    expect(calls[0].address).toEqual(v6Address("JBTerminalStore", chainId));
    expect(calls[0].abi).toBe(jbTerminalStoreAbi);
    expect(calls[0].functionName).toEqual("currentReclaimableSurplusOf");
    // Empty terminal/token arrays use all of the project's terminals and tokens;
    // defaults quote 18 decimals in the native token's currency.
    expect(calls[0].args).toEqual([projectId, ONE_ETHER, [], [], 18n, 61166n]);
  });

  test("getCashOutQuote applies the full x/40 fee with a non-zero tax rate", async () => {
    const client = {
      async readContract() {
        return ONE_ETHER;
      },
    } as unknown as PublicClient;

    const quote = await getCashOutQuote(client, {
      chainId,
      projectId,
      cashOutCount: ONE_ETHER,
      cashOutTaxRate: 2000n,
    });

    expect(quote.reclaimAmountAfterFee).toEqual(ONE_ETHER - ONE_ETHER / 40n);
  });

  test("getCashOutQuote gates the zero-tax fee on min(reclaim, feeFreeSurplus)", async () => {
    const client = {
      async readContract() {
        return ONE_ETHER;
      },
    } as unknown as PublicClient;

    // Zero tax with zero fee-free surplus: no fee at all.
    expect(
      (
        await getCashOutQuote(client, {
          chainId,
          projectId,
          cashOutCount: ONE_ETHER,
          cashOutTaxRate: 0n,
          feeFreeSurplus: 0n,
        })
      ).reclaimAmountAfterFee,
    ).toEqual(ONE_ETHER);

    // Zero tax with a partial fee-free surplus: the fee applies to the
    // feeable portion only.
    const feeFreeSurplus = ONE_ETHER / 2n;
    expect(
      (
        await getCashOutQuote(client, {
          chainId,
          projectId,
          cashOutCount: ONE_ETHER,
          cashOutTaxRate: 0n,
          feeFreeSurplus,
        })
      ).reclaimAmountAfterFee,
    ).toEqual(ONE_ETHER - feeFreeSurplus / 40n);

    // Zero tax with an UNKNOWN fee-free surplus: unresolved, not assumed zero.
    expect(
      (
        await getCashOutQuote(client, {
          chainId,
          projectId,
          cashOutCount: ONE_ETHER,
          cashOutTaxRate: 0n,
        })
      ).reclaimAmountAfterFee,
    ).toBeUndefined();
  });

  test("getCashOutQuote resolves feeless beneficiaries without the other inputs", async () => {
    const client = {
      async readContract() {
        return ONE_ETHER;
      },
    } as unknown as PublicClient;

    const quote = await getCashOutQuote(client, {
      chainId,
      projectId,
      cashOutCount: ONE_ETHER,
      beneficiaryIsFeeless: true,
    });

    expect(quote.reclaimAmountAfterFee).toEqual(ONE_ETHER);
  });

  test("getCashOutQuote respects custom decimals and currency", async () => {
    const calls: any[] = [];
    const client = {
      async readContract(params: unknown) {
        calls.push(params);
        return 0n;
      },
    } as unknown as PublicClient;

    await getCashOutQuote(client, {
      chainId,
      projectId,
      cashOutCount: ONE_ETHER,
      decimals: 6n,
      currency: 0x3606eb48n,
    });

    expect(calls[0].args).toEqual([
      projectId,
      ONE_ETHER,
      [],
      [],
      6n,
      0x3606eb48n,
    ]);
  });

  test("build721CashOutMetadata packs the cashOut id and token ids", () => {
    // With a target whose first 4 bytes are zero, the id is the first 4 bytes
    // of keccak256("cashOut").
    const metadata = build721CashOutMetadata({
      metadataIdTarget: "0x00000000000000000000000000000000DeaDBeef",
      tokenIds: [1_000_000_001n, 1_000_000_002n],
    });

    expect(sliceHex(metadata, 0, 32)).toEqual(`0x${"00".repeat(32)}`);
    // keccak256("cashOut") first 4 bytes, then the payload word offset (2).
    expect(sliceHex(metadata, 32, 36)).toEqual("0x86b14ff4");
    expect(sliceHex(metadata, 36, 37)).toEqual("0x02");
    const [tokenIds] = decodeAbiParameters(
      [{ type: "uint256[]" }],
      sliceHex(metadata, 64),
    );
    expect(tokenIds).toEqual([1_000_000_001n, 1_000_000_002n]);
  });

  test("build721CashOutMetadata rejects empty, duplicate, and zero token ids", () => {
    const target = "0x00000000000000000000000000000000DeaDBeef" as const;
    expect(() =>
      build721CashOutMetadata({ metadataIdTarget: target, tokenIds: [] }),
    ).toThrow(/at least one/);
    expect(() =>
      build721CashOutMetadata({ metadataIdTarget: target, tokenIds: [1n, 1n] }),
    ).toThrow(/unique/);
    expect(() =>
      build721CashOutMetadata({ metadataIdTarget: target, tokenIds: [0n] }),
    ).toThrow(/positive/);
  });
});

describe("hook-aware cash-out routing", () => {
  const hook = "0x4444444444444444444444444444444444444444" as const;
  const poolId = `0x${"12".repeat(32)}` as const;

  function specMetadata(
    params: {
      minimumSwap?: bigint;
      netDirect?: bigint;
      rawQuote?: bigint;
      userSpecified?: boolean;
    } = {},
  ) {
    return encodeAbiParameters(
      [
        { type: "uint256" },
        { type: "uint256" },
        { type: "uint256" },
        { type: "int24" },
        { type: "uint128" },
        { type: "bytes32" },
        { type: "uint256" },
        { type: "bool" },
      ],
      [
        params.minimumSwap ?? 1_100n,
        100n,
        params.netDirect ?? 900n,
        -123,
        456n,
        poolId,
        params.rawQuote ?? 1_200n,
        params.userSpecified ?? false,
      ],
    );
  }

  test("slippageFloor floors but never zeroes a positive quote", () => {
    expect(slippageFloor(1_000n, 100n)).toEqual(990n);
    expect(slippageFloor(1n, 100n)).toEqual(1n);
    expect(slippageFloor(0n, 100n)).toEqual(0n);
    expect(() => slippageFloor(1_000n, 10_000n)).toThrow();
  });

  test("cashOutProtocolFee matches the terminal's exact /40 rounding", () => {
    // 1001 / 40 = 25 exactly as the contract floors it; the legacy
    // ×975/1000 estimate yields net 975 — one wei below the true 976.
    expect(
      cashOutProtocolFee({ reclaimAmount: 1_001n, cashOutTaxRate: 1n }),
    ).toEqual(25n);
    expect(
      cashOutProtocolFee({ reclaimAmount: 1_000n, cashOutTaxRate: 0n }),
    ).toEqual(0n);
    expect(
      cashOutProtocolFee({
        reclaimAmount: 1_000n,
        cashOutTaxRate: 0n,
        feeFreeSurplus: 400n,
      }),
    ).toEqual(10n);
    expect(
      cashOutProtocolFee({
        reclaimAmount: 1_000n,
        cashOutTaxRate: 1n,
        beneficiaryIsFeeless: true,
      }),
    ).toEqual(0n);
  });

  test("treasury route floors the exact fee-adjusted net", () => {
    const route = resolveCashOutRoute({
      reclaimAmount: 1_000n,
      cashOutTaxRate: 1n,
      hookSpecifications: [],
    });
    expect(route.route).toEqual("treasury");
    expect(route.treasuryProtocolFee).toEqual(25n);
    expect(route.expectedReturn).toEqual(975n);
    expect(route.terminalMinimum).toEqual(965n);
    expect(route.metadata).toEqual("0x");
  });

  test("amm route moves the floor into hook metadata with zero terminal minimum", () => {
    const route = resolveCashOutRoute({
      reclaimAmount: 0n,
      cashOutTaxRate: 10_000n,
      hookSpecifications: [
        { hook, noop: false, amount: 0n, metadata: specMetadata() },
      ],
      buybackHookAddress: hook,
    });
    expect(route.route).toEqual("amm");
    expect(route.expectedReturn).toEqual(1_200n);
    expect(route.minimumReturn).toEqual(1_089n);
    expect(route.terminalMinimum).toEqual(0n);
    expect(route.metadata).toEqual(
      buildBuybackCashOutMetadata({ hook, minimumSwapAmountOut: 1_089n }),
    );
  });

  test("re-previewed explicit floor is preserved, not double-discounted", () => {
    const route = resolveCashOutRoute({
      reclaimAmount: 0n,
      cashOutTaxRate: 10_000n,
      hookSpecifications: [
        {
          hook,
          noop: false,
          amount: 0n,
          metadata: specMetadata({
            minimumSwap: 1_188n,
            rawQuote: 0n,
            userSpecified: true,
          }),
        },
      ],
      buybackHookAddress: hook,
    });
    expect(route.route).toEqual("amm");
    expect(route.minimumReturn).toEqual(1_188n);
  });

  test("uses the executable pool quote rather than the optimistic raw quote", () => {
    const route = resolveCashOutRoute({
      reclaimAmount: 1_510_000n,
      cashOutTaxRate: 1n,
      hookSpecifications: [
        {
          hook,
          noop: false,
          amount: 0n,
          metadata: specMetadata({
            minimumSwap: 16_000_000n,
            netDirect: 1_470_000n,
            rawQuote: 16_419_630n,
          }),
        },
      ],
      buybackHookAddress: hook,
      slippageBps: 100n,
    });

    expect(route.route).toEqual("amm");
    expect(route.expectedReturn).toEqual(16_419_630n);
    expect(route.minimumReturn).toEqual(15_840_000n);
    expect(cashOutPoolBufferBps(route)).toEqual(256n);
    expect(route.metadata).toEqual(
      buildBuybackCashOutMetadata({
        hook,
        minimumSwapAmountOut: 15_840_000n,
      }),
    );
  });

  test("noop spec stays on the treasury path", () => {
    const route = resolveCashOutRoute({
      reclaimAmount: 1_000n,
      cashOutTaxRate: 1n,
      hookSpecifications: [
        { hook, noop: true, amount: 0n, metadata: specMetadata() },
      ],
      buybackHookAddress: hook,
    });
    expect(route.route).toEqual("treasury");
    expect(route.metadata).toEqual("0x");
    expect(route.expectedReturn).toEqual(975n);
    expect(route.buyback?.hook).toEqual(hook);
  });

  test("amm route without safe market advantage falls back to treasury", () => {
    // Floored pool quote (990) does not beat the direct net (995): an
    // explicit metadata minimum would re-route to the terminal path anyway.
    const route = resolveCashOutRoute({
      reclaimAmount: 1_000n,
      cashOutTaxRate: 1n,
      hookSpecifications: [
        {
          hook,
          noop: false,
          amount: 0n,
          metadata: specMetadata({ rawQuote: 1_000n, netDirect: 995n }),
        },
      ],
      buybackHookAddress: hook,
    });
    expect(route.route).toEqual("treasury");
    expect(route.terminalMinimum).toEqual(965n);
  });

  test("buyback cashOut metadata envelope roundtrips", () => {
    const metadata = buildBuybackCashOutMetadata({
      hook,
      minimumSwapAmountOut: 123n,
      skip: true,
    });
    // 32-byte reserved word, then the id/offset table entry.
    expect(sliceHex(metadata, 0, 32)).toEqual(`0x${"00".repeat(32)}`);
    expect(sliceHex(metadata, 32, 36)).toEqual(hookMetadataId(hook, "cashOut"));
    const [minimum, skip] = decodeAbiParameters(
      [{ type: "uint256" }, { type: "bool" }],
      sliceHex(metadata, 64),
    );
    expect(minimum).toEqual(123n);
    expect(skip).toEqual(true);
  });

  test("decodeBuybackCashOutSpec decodes the diagnostic payload", () => {
    const spec = decodeBuybackCashOutSpec(
      specMetadata({ minimumSwap: 5n, netDirect: 7n, rawQuote: 9n }),
    );
    expect(spec.minimumSwapAmountOut).toEqual(5n);
    expect(spec.netDirectCashOutAmount).toEqual(7n);
    expect(spec.rawSwapQuote).toEqual(9n);
    expect(spec.poolId).toEqual(poolId);
    expect(spec.twapTick).toEqual(-123);
  });

  test("spec from a non-buyback hook is never selected as the amm route", () => {
    // A 721 tiers hook (or any other data-hook-returned specification) can
    // carry metadata that garbage-decodes to plausible buyback values. It must
    // NOT be routed as a pool sell with a zero terminal minimum.
    const route = resolveCashOutRoute({
      reclaimAmount: 1_000n,
      cashOutTaxRate: 1n,
      hookSpecifications: [
        { hook, noop: false, amount: 0n, metadata: specMetadata() },
      ],
      buybackHookAddress: "0x5555555555555555555555555555555555555555",
    });
    expect(route.route).toEqual("treasury");
    expect(route.terminalMinimum).toEqual(965n);
    expect(route.metadata).toEqual("0x");
    expect(route.buyback).toBeNull();
  });

  test("without a buyback hook address no spec is trusted as the amm route", () => {
    const route = resolveCashOutRoute({
      reclaimAmount: 1_000n,
      cashOutTaxRate: 1n,
      hookSpecifications: [
        { hook, noop: false, amount: 0n, metadata: specMetadata() },
      ],
    });
    expect(route.route).toEqual("treasury");
    expect(route.terminalMinimum).toEqual(965n);
    expect(route.metadata).toEqual("0x");
    expect(route.buyback).toBeNull();
  });

  test("buyback spec is matched by address, case-insensitively", () => {
    // Checksummed on-chain hook vs lowercase address-book entry.
    const checksummed = "0xAbCdaBCDabcDabcdaBcdABCdaBCDAbCDaBcDABcd" as const;
    const route = resolveCashOutRoute({
      reclaimAmount: 0n,
      cashOutTaxRate: 10_000n,
      hookSpecifications: [
        {
          hook: checksummed,
          noop: false,
          amount: 0n,
          metadata: specMetadata(),
        },
      ],
      buybackHookAddress: "0xabcdabcdabcdabcdabcdabcdabcdabcdabcdabcd",
    });
    expect(route.route).toEqual("amm");
    expect(route.terminalMinimum).toEqual(0n);
    expect(route.buyback?.hook).toEqual(checksummed);
  });

  test("mixed specs select the buyback one by address, not position", () => {
    const otherHook = "0x6666666666666666666666666666666666666666" as const;
    const route = resolveCashOutRoute({
      reclaimAmount: 0n,
      cashOutTaxRate: 10_000n,
      hookSpecifications: [
        // A non-buyback spec listed first, with metadata that happens to
        // decode: the legacy first-with-metadata heuristic picked this one.
        {
          hook: otherHook,
          noop: false,
          amount: 0n,
          metadata: specMetadata({ rawQuote: 9_999n }),
        },
        { hook, noop: false, amount: 0n, metadata: specMetadata() },
      ],
      buybackHookAddress: hook,
    });
    expect(route.route).toEqual("amm");
    expect(route.expectedReturn).toEqual(1_200n);
    expect(route.buyback?.hook).toEqual(hook);
    expect(route.metadata).toEqual(
      buildBuybackCashOutMetadata({ hook, minimumSwapAmountOut: 1_089n }),
    );
  });

  test("classifies nested cash-out execution errors without owning UI copy", () => {
    expect(
      classifyCashOutExecutionError({
        message: "execution reverted",
        cause: { details: "reverted with signature 0xe2d708a9" },
      }),
    ).toEqual({
      code: "BUYBACK_SLIPPAGE_EXCEEDED",
      selector: "0xe2d708a9",
    });
    expect(
      classifyCashOutExecutionError({
        cause: { errorName: "JBMultiTerminal_UnderMin" },
      }),
    ).toEqual({ code: "TERMINAL_UNDER_MIN", selector: "0x6b2bb382" });
    expect(
      classifyCashOutExecutionError(new Error("user rejected")),
    ).toBeNull();
  });

  test("chooses a direct sale only for claimed tokens with a strictly better protected output", () => {
    const cashOut = resolveCashOutRoute({
      reclaimAmount: 1_000n,
      cashOutTaxRate: 1n,
      hookSpecifications: [],
    });
    const poolKey = {
      currency0: holder,
      currency1: "0x0000000000000000000000000000000000000000",
      fee: 10_000,
      tickSpacing: 200,
      hooks: hook,
    } as const;

    expect(
      chooseBestCashOutRoute({
        cashOut,
        directSwapQuote: 1_000n,
        directSwapPoolKey: poolKey,
        directSwapZeroForOne: true,
        spendableProjectTokenCount: 100n,
        cashOutCount: 100n,
      }),
    ).toMatchObject({
      kind: "direct-swap",
      expectedReturn: 1_000n,
      minimumReturn: 990n,
    });
    expect(
      chooseBestCashOutRoute({
        cashOut,
        directSwapQuote: 1_000n,
        directSwapPoolKey: poolKey,
        directSwapZeroForOne: true,
        spendableProjectTokenCount: 99n,
        cashOutCount: 100n,
      }).kind,
    ).toEqual("cash-out");
    expect(
      chooseBestCashOutRoute({
        cashOut,
        directSwapQuote: 980n,
        directSwapPoolKey: poolKey,
        directSwapZeroForOne: true,
        spendableProjectTokenCount: 100n,
        cashOutCount: 100n,
      }).kind,
    ).toEqual("cash-out");
  });

  test("quotes and prepares a direct native-pair sale when it safely beats cashing out", async () => {
    const projectToken = "0x7777777777777777777777777777777777777777" as const;
    const poolKey = {
      currency0: "0x0000000000000000000000000000000000000000",
      currency1: projectToken,
      fee: 10_000,
      tickSpacing: 200,
      hooks: hook,
    } as const;
    const calls: string[] = [];
    const client = {
      readContract: async (call: { functionName: string }) => {
        calls.push(call.functionName);
        if (call.functionName === "previewCashOutFrom") {
          return [{ id: 42n }, 1_000n, 1n, []];
        }
        throw new Error(`unexpected call ${call.functionName}`);
      },
      call: async () => {
        calls.push("quoteExactInputSingle");
        return {
          data: encodeAbiParameters(
            [{ type: "uint256" }, { type: "uint256" }],
            [1_200n, 50_000n],
          ),
        };
      },
    } as unknown as PublicClient;
    const args = {
      chainId,
      projectId,
      holder,
      cashOutCount: 100n,
      tokenToReclaim: NATIVE_TOKEN,
      directSwap: {
        poolKey,
        projectToken,
        spendableProjectTokenCount: 100n,
      },
    } as const;

    const best = await getBestCashOutRoute(client, args);
    expect(best).toMatchObject({
      kind: "direct-swap",
      expectedReturn: 1_200n,
      minimumReturn: 1_188n,
      zeroForOne: false,
    });

    const prepared = await prepareBestCashOut(client, {
      ...args,
      beneficiary,
      directSwapDeadline: 123_456n,
    });
    expect(prepared.kind).toEqual("direct-swap");
    if (prepared.kind !== "direct-swap") throw new Error("expected swap");
    expect(prepared.transaction.functionName).toEqual("execute");
    expect(prepared.transaction.args[2]).toEqual(123_456n);
    expect(prepared.route.minimumReturn).toEqual(1_188n);
    expect(calls).toEqual([
      "previewCashOutFrom",
      "quoteExactInputSingle",
      "previewCashOutFrom",
      "quoteExactInputSingle",
    ]);
  });

  test("does not quote a pool whose output is not the reclaim token", async () => {
    const projectToken = "0x7777777777777777777777777777777777777777" as const;
    let poolCalls = 0;
    const client = {
      readContract: async () => [{ id: 42n }, 1_000n, 1n, []],
      call: async () => {
        poolCalls += 1;
        throw new Error("should not quote");
      },
    } as unknown as PublicClient;
    const best = await getBestCashOutRoute(client, {
      chainId,
      projectId,
      holder,
      cashOutCount: 100n,
      tokenToReclaim: NATIVE_TOKEN,
      directSwap: {
        projectToken,
        spendableProjectTokenCount: 100n,
        poolKey: {
          currency0: projectToken,
          currency1: beneficiary,
          fee: 10_000,
          tickSpacing: 200,
          hooks: hook,
        },
      },
    });
    expect(best.kind).toEqual("cash-out");
    expect(poolCalls).toEqual(0);
  });

  test("falls back to the terminal when the optional direct-swap quoter fails", async () => {
    const projectToken = "0x7777777777777777777777777777777777777777" as const;
    const client = {
      readContract: async () => [{ id: 42n }, 1_000n, 1n, []],
      call: async () => {
        throw new Error("quoter unavailable");
      },
    } as unknown as PublicClient;
    const best = await getBestCashOutRoute(client, {
      chainId,
      projectId,
      holder,
      cashOutCount: 100n,
      tokenToReclaim: NATIVE_TOKEN,
      directSwap: {
        projectToken,
        spendableProjectTokenCount: 100n,
        poolKey: {
          currency0: projectToken,
          currency1: "0x0000000000000000000000000000000000000000",
          fee: 10_000,
          tickSpacing: 200,
          hooks: hook,
        },
      },
    });
    expect(best).toMatchObject({
      kind: "cash-out",
      expectedReturn: 975n,
      minimumReturn: 965n,
    });
  });

  test("getHookAwareCashOutQuote reads previewCashOutFrom and resolves", async () => {
    const calls: { functionName: string }[] = [];
    const client = {
      readContract: async (call: {
        functionName: string;
        args: readonly unknown[];
      }) => {
        calls.push(call);
        if (call.functionName === "previewCashOutFrom") {
          return [{}, 1_000n, 1n, []];
        }
        throw new Error(`unexpected call ${call.functionName}`);
      },
    } as unknown as PublicClient;

    const route = await getHookAwareCashOutQuote(client, {
      chainId,
      projectId,
      holder,
      cashOutCount: ONE_ETHER,
      tokenToReclaim: NATIVE_TOKEN,
    });
    expect(calls.map((call) => call.functionName)).toEqual([
      "previewCashOutFrom",
    ]);
    expect(route.route).toEqual("treasury");
    expect(route.expectedReturn).toEqual(975n);
    expect(route.terminalMinimum).toEqual(965n);
  });

  test("getHookAwareCashOutQuote routes to amm only for the chain's buyback hook", async () => {
    const buybackHook = v6Address("JBBuybackHook", chainId);
    const clientFor = (specHook: string) =>
      ({
        readContract: async (call: { functionName: string }) => {
          if (call.functionName === "previewCashOutFrom") {
            return [
              {},
              1_000n,
              1n,
              [
                {
                  hook: specHook,
                  noop: false,
                  amount: 0n,
                  metadata: specMetadata(),
                },
              ],
            ];
          }
          throw new Error(`unexpected call ${call.functionName}`);
        },
      }) as unknown as PublicClient;

    // The chain's canonical buyback hook wins the pool route.
    const ammRoute = await getHookAwareCashOutQuote(clientFor(buybackHook), {
      chainId,
      projectId,
      holder,
      cashOutCount: ONE_ETHER,
      tokenToReclaim: NATIVE_TOKEN,
    });
    expect(ammRoute.route).toEqual("amm");
    expect(ammRoute.terminalMinimum).toEqual(0n);
    expect(ammRoute.buyback?.hook).toEqual(buybackHook);

    // Projects that have not migrated retain their executed previous hook route.
    const previous =
      jbContractAddressHistory["6"].JBBuybackHook.previous[chainId];
    const previousRoute = await getHookAwareCashOutQuote(clientFor(previous), {
      chainId,
      projectId,
      holder,
      cashOutCount: ONE_ETHER,
      tokenToReclaim: NATIVE_TOKEN,
    });
    expect(previousRoute.route).toEqual("amm");
    expect(previousRoute.buyback?.hook).toEqual(previous);

    // Any other hook's spec stays on the treasury path with a real minimum.
    const treasuryRoute = await getHookAwareCashOutQuote(
      clientFor("0x9999999999999999999999999999999999999999"),
      {
        chainId,
        projectId,
        holder,
        cashOutCount: ONE_ETHER,
        tokenToReclaim: NATIVE_TOKEN,
      },
    );
    expect(treasuryRoute.route).toEqual("treasury");
    expect(treasuryRoute.terminalMinimum).toEqual(965n);
    expect(treasuryRoute.metadata).toEqual("0x");
    expect(treasuryRoute.buyback).toBeNull();
  });

  test("prepareHookAwareCashOut locks the pool route and builds its transaction", async () => {
    const buybackHook = v6Address("JBBuybackHook", chainId);
    const calls: { functionName: string; args: readonly unknown[] }[] = [];
    const client = {
      readContract: async (call: {
        functionName: string;
        args: readonly unknown[];
      }) => {
        calls.push(call);
        if (call.functionName !== "previewCashOutFrom") {
          throw new Error(`unexpected call ${call.functionName}`);
        }
        const metadata = call.args[5];
        return [
          { id: 42n },
          0n,
          10_000n,
          [
            {
              hook: buybackHook,
              noop: false,
              amount: 0n,
              metadata:
                metadata === "0x"
                  ? specMetadata()
                  : specMetadata({
                      minimumSwap: 1_089n,
                      rawQuote: 0n,
                      userSpecified: true,
                    }),
            },
          ],
        ];
      },
    } as unknown as PublicClient;

    const prepared = await prepareHookAwareCashOut(client, {
      chainId,
      projectId,
      holder,
      cashOutCount: ONE_ETHER,
      tokenToReclaim: NATIVE_TOKEN,
      beneficiary,
    });

    expect(calls).toHaveLength(2);
    expect(prepared.preview.rulesetId).toEqual(42n);
    expect(prepared.lockedPreview?.rulesetId).toEqual(42n);
    expect(prepared.route.route).toEqual("amm");
    expect(prepared.route.minimumReturn).toEqual(1_089n);
    expect(prepared.transaction.args[4]).toEqual(0n);
    expect(prepared.transaction.args[5]).toEqual(beneficiary);
    expect(prepared.transaction.args[6]).toEqual(prepared.route.metadata);
  });

  test("prepareHookAwareCashOut rejects a route which changes while locking", async () => {
    const buybackHook = v6Address("JBBuybackHook", chainId);
    let previewCount = 0;
    const client = {
      readContract: async (call: { functionName: string }) => {
        if (call.functionName !== "previewCashOutFrom") {
          throw new Error(`unexpected call ${call.functionName}`);
        }
        previewCount += 1;
        return [
          { id: 42n },
          previewCount === 1 ? 0n : 1_000n,
          previewCount === 1 ? 10_000n : 1n,
          previewCount === 1
            ? [
                {
                  hook: buybackHook,
                  noop: false,
                  amount: 0n,
                  metadata: specMetadata(),
                },
              ]
            : [],
        ];
      },
    } as unknown as PublicClient;

    await expect(
      prepareHookAwareCashOut(client, {
        chainId,
        projectId,
        holder,
        cashOutCount: ONE_ETHER,
        tokenToReclaim: NATIVE_TOKEN,
      }),
    ).rejects.toMatchObject({ code: "CASH_OUT_ROUTE_CHANGED" });
  });
});

import {
  encodeFunctionData,
  type Abi,
  type Address,
  type ContractFunctionName,
  type ContractFunctionParameters,
  type Hex,
} from "viem";

export const JBCENTER_DEFAULT_URL = "https://juicebox.center";
export const JBCENTER_REQUEST_TIMEOUT_MS = 15_000;
export const JBCENTER_DEPLOYMENT_TIMEOUT_MS = 45_000;
export const JBCENTER_PIN_TIMEOUT_MS = 300_000;
export const MAX_JBCENTER_RESPONSE_BYTES = 20 * 1024 * 1024;

export const JBCENTER_RPC_METHODS = [
  "eth_blobBaseFee",
  "eth_blockNumber",
  "eth_call",
  "eth_chainId",
  "eth_createAccessList",
  "eth_estimateGas",
  "eth_feeHistory",
  "eth_gasPrice",
  "eth_getBalance",
  "eth_getBlockByHash",
  "eth_getBlockByNumber",
  "eth_getBlockReceipts",
  "eth_getBlockTransactionCountByHash",
  "eth_getBlockTransactionCountByNumber",
  "eth_getCode",
  "eth_getLogs",
  "eth_getProof",
  "eth_getStorageAt",
  "eth_getTransactionByBlockHashAndIndex",
  "eth_getTransactionByBlockNumberAndIndex",
  "eth_getTransactionByHash",
  "eth_getTransactionCount",
  "eth_getTransactionReceipt",
  "eth_maxPriorityFeePerGas",
  "eth_syncing",
  "net_version",
] as const;

export type JBCenterRpcMethod = (typeof JBCENTER_RPC_METHODS)[number];

export type JBCenterRpcRequest = {
  method: JBCenterRpcMethod;
  params?: readonly unknown[];
};

/** Structurally compatible with EIP-1193 providers, including viem's `custom`. */
export type JBCenterRpcProvider = {
  request<TResult = unknown>(request: {
    method: string;
    params?: readonly unknown[];
  }): Promise<TResult>;
};

export type JBCenterJson =
  | null
  | boolean
  | number
  | string
  | JBCenterJson[]
  | JBCenterJsonObject;

export type JBCenterJsonObject = { [key: string]: JBCenterJson };

export type JBCenterDeploymentCall = {
  chainId: number;
  to: Address;
  data: Hex;
};

export type JBCenterContractCall<
  TAbi extends Abi = Abi,
  TFunctionName extends ContractFunctionName<
    TAbi,
    "payable" | "nonpayable"
  > = ContractFunctionName<TAbi, "payable" | "nonpayable">,
> = {
  chainId: number;
  address: Address;
} & ContractFunctionParameters<TAbi, "payable" | "nonpayable", TFunctionName>;

/** Freeze a typed viem contract request into the call signed by JB Center. */
export function createJBCenterDeploymentCall<
  const TAbi extends Abi,
  TFunctionName extends ContractFunctionName<TAbi, "payable" | "nonpayable">,
>(request: JBCenterContractCall<TAbi, TFunctionName>): JBCenterDeploymentCall {
  const { chainId, address, ...parameters } = request;
  return {
    chainId,
    to: address,
    data: encodeFunctionData(
      parameters as Parameters<typeof encodeFunctionData>[0],
    ),
  };
}

export type JBCenterIntentInput<
  TJb extends JBCenterJsonObject = JBCenterJsonObject,
> = {
  format: string;
  deploymentVersion: string;
  chainIds: number[];
  deploymentCalls: JBCenterDeploymentCall[];
  jb: TJb;
};

export type JBCenterIntentEnvelope<
  TJb extends JBCenterJsonObject = JBCenterJsonObject,
> = JBCenterIntentInput<TJb>;

export type JBCenterPreparedIntent<
  TJb extends JBCenterJsonObject = JBCenterJsonObject,
> = {
  contentHash: Hex;
  message: string;
  envelope: JBCenterIntentEnvelope<TJb>;
};

export type JBCenterPublishIntentInput<
  TJb extends JBCenterJsonObject = JBCenterJsonObject,
> = JBCenterIntentInput<TJb> & {
  publisher: Address;
  signature: Hex;
};

export type JBCenterIntentMetadata = {
  name: string;
  description: string | null;
  tagline: string | null;
  tags: string[];
  logoUri: string | null;
  owner: Address | null;
};

export type JBCenterDeployment = {
  chainId: number;
  projectId: string;
  transactionHash: Hex;
  createdAt: string;
};

export type JBCenterDeploymentInput = Omit<JBCenterDeployment, "createdAt">;

export type JBCenterIntent<
  TJb extends JBCenterJsonObject = JBCenterJsonObject,
> = JBCenterIntentMetadata & {
  id: string;
  status: "undeployed" | "deployed";
  contentHash: Hex;
  envelope: JBCenterIntentEnvelope<TJb>;
  publisher: Address;
  signature: Hex;
  createdAt: string;
  deployments: JBCenterDeployment[];
};

export type JBCenterSearchItem = JBCenterIntentMetadata & {
  source: "jbcenter";
  status: "undeployed";
  intentId: string;
  contentHash: Hex;
  format: string;
  deploymentVersion: string;
  chainIds: number[];
  publisher: Address;
  createdAt: string;
};

export type JBCenterSearchPage = {
  items: JBCenterSearchItem[];
  totalCount: number;
  nextCursor: string | null;
};

export type JBCenterSearchParams = {
  query?: string;
  limit?: number;
  cursor?: string;
};

export type JBCenterPin = {
  cid: string;
  status: "queued";
  uri: `ipfs://${string}`;
  gatewayUrl: string;
};

export type JBCenterRequestOptions = {
  signal?: AbortSignal;
  timeoutMs?: number;
};

export type JBCenterClientOptions = {
  baseUrl?: string;
  fetch?: typeof fetch;
  maxResponseBytes?: number;
  timeoutMs?: number;
};

type ErrorEnvelope = {
  error?: { code?: unknown; message?: unknown };
};

type RpcEnvelope =
  | { jsonrpc: "2.0"; id: number; result: unknown }
  | {
      jsonrpc: "2.0";
      id: number;
      error: { code: number; message: string; data?: Hex };
    };

type Validator<T> = (value: unknown) => value is T;

export class JBCenterRequestError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly code?: string,
    readonly requestId?: string,
    readonly retryAfter?: number,
  ) {
    super(message);
    this.name = "JBCenterRequestError";
  }
}

export class JBCenterTimeoutError extends Error {
  constructor(readonly timeoutMs: number) {
    super(`JB Center request timed out after ${timeoutMs}ms`);
    this.name = "JBCenterTimeoutError";
  }
}

export class JBCenterRpcError extends Error {
  constructor(
    readonly code: number,
    message: string,
    readonly data?: Hex,
  ) {
    super(message);
    this.name = "JBCenterRpcError";
  }
}

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isHash(value: unknown): value is Hex {
  return typeof value === "string" && /^0x[0-9a-f]{64}$/iu.test(value);
}

function isSignature(value: unknown): value is Hex {
  return (
    typeof value === "string" &&
    /^0x(?:[0-9a-f]{128}|[0-9a-f]{130})$/iu.test(value)
  );
}

function isRpcErrorData(value: unknown): value is Hex {
  return typeof value === "string" && /^0x(?:[0-9a-f]{2})*$/iu.test(value);
}

function rpcEnvelope(id: number): Validator<RpcEnvelope> {
  return (value: unknown): value is RpcEnvelope => {
    if (!record(value) || value.jsonrpc !== "2.0" || value.id !== id) {
      return false;
    }
    const hasResult = Object.prototype.hasOwnProperty.call(value, "result");
    const hasError = Object.prototype.hasOwnProperty.call(value, "error");
    if (hasResult === hasError) return false;
    if (hasResult) return true;
    return (
      record(value.error) &&
      Number.isSafeInteger(value.error.code) &&
      typeof value.error.message === "string" &&
      (value.error.data === undefined || isRpcErrorData(value.error.data))
    );
  };
}

function isAddress(value: unknown): value is Address {
  return typeof value === "string" && /^0x[0-9a-f]{40}$/iu.test(value);
}

function isStringArray(value: unknown): value is string[] {
  return (
    Array.isArray(value) && value.every((item) => typeof item === "string")
  );
}

function isNumberArray(value: unknown): value is number[] {
  return (
    Array.isArray(value) &&
    value.every((item) => Number.isSafeInteger(item) && Number(item) > 0)
  );
}

function isDeploymentCall(value: unknown): value is JBCenterDeploymentCall {
  return (
    record(value) &&
    Number.isSafeInteger(value.chainId) &&
    Number(value.chainId) > 0 &&
    isAddress(value.to) &&
    typeof value.data === "string" &&
    /^0x(?:[0-9a-f]{2}){4,}$/iu.test(value.data)
  );
}

function isEnvelope(value: unknown): value is JBCenterIntentEnvelope {
  if (
    !record(value) ||
    typeof value.format !== "string" ||
    typeof value.deploymentVersion !== "string" ||
    !isNumberArray(value.chainIds) ||
    new Set(value.chainIds).size !== value.chainIds.length ||
    !record(value.jb)
  ) {
    return false;
  }
  if (
    !Array.isArray(value.deploymentCalls) ||
    !value.deploymentCalls.every(isDeploymentCall) ||
    value.deploymentCalls.length !== value.chainIds.length
  ) {
    return false;
  }
  const chains = [...value.chainIds].sort((a, b) => a - b);
  const callChains = value.deploymentCalls
    .map(({ chainId }) => chainId)
    .sort((a, b) => a - b);
  return (
    new Set(callChains).size === callChains.length &&
    chains.every((chainId, index) => callChains[index] === chainId)
  );
}

function isMetadata(value: Record<string, unknown>): boolean {
  return (
    typeof value.name === "string" &&
    (value.description === null || typeof value.description === "string") &&
    (value.tagline === null || typeof value.tagline === "string") &&
    isStringArray(value.tags) &&
    (value.logoUri === null || typeof value.logoUri === "string") &&
    (value.owner === null || isAddress(value.owner))
  );
}

function isDeployment(value: unknown): value is JBCenterDeployment {
  return (
    record(value) &&
    Number.isSafeInteger(value.chainId) &&
    Number(value.chainId) > 0 &&
    typeof value.projectId === "string" &&
    isHash(value.transactionHash) &&
    typeof value.createdAt === "string"
  );
}

function isIntent(value: unknown): value is JBCenterIntent {
  return (
    record(value) &&
    isMetadata(value) &&
    typeof value.id === "string" &&
    (value.status === "undeployed" || value.status === "deployed") &&
    isHash(value.contentHash) &&
    isEnvelope(value.envelope) &&
    isAddress(value.publisher) &&
    isSignature(value.signature) &&
    typeof value.createdAt === "string" &&
    Array.isArray(value.deployments) &&
    value.deployments.every(isDeployment)
  );
}

function isPreparedIntent(value: unknown): value is JBCenterPreparedIntent {
  return (
    record(value) &&
    isHash(value.contentHash) &&
    typeof value.message === "string" &&
    isEnvelope(value.envelope)
  );
}

function isSearchItem(value: unknown): value is JBCenterSearchItem {
  return (
    record(value) &&
    isMetadata(value) &&
    value.source === "jbcenter" &&
    value.status === "undeployed" &&
    typeof value.intentId === "string" &&
    isHash(value.contentHash) &&
    typeof value.format === "string" &&
    typeof value.deploymentVersion === "string" &&
    isNumberArray(value.chainIds) &&
    isAddress(value.publisher) &&
    typeof value.createdAt === "string"
  );
}

function isSearchPage(value: unknown): value is JBCenterSearchPage {
  return (
    record(value) &&
    Array.isArray(value.items) &&
    value.items.every(isSearchItem) &&
    Number.isSafeInteger(value.totalCount) &&
    Number(value.totalCount) >= 0 &&
    (value.nextCursor === null || typeof value.nextCursor === "string")
  );
}

function isPin(value: unknown): value is JBCenterPin {
  return (
    record(value) &&
    typeof value.cid === "string" &&
    /^(?:Qm[1-9A-HJ-NP-Za-km-z]{44}|b[a-z2-7]{20,160})$/u.test(value.cid) &&
    value.status === "queued" &&
    typeof value.uri === "string" &&
    value.uri === `ipfs://${value.cid}` &&
    value.gatewayUrl === `/ipfs/${value.cid}`
  );
}

function normalizeBaseUrl(value: string): string {
  const url = new URL(value);
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    throw new TypeError("JB Center baseUrl must use HTTP or HTTPS");
  }
  if (url.username || url.password || url.search || url.hash) {
    throw new TypeError(
      "JB Center baseUrl cannot include credentials, query, or hash",
    );
  }
  return url.toString().replace(/\/$/u, "");
}

async function readBoundedJson(
  response: Response,
  maxResponseBytes: number,
): Promise<unknown> {
  const declaredSize = Number(response.headers.get("content-length") ?? 0);
  if (Number.isFinite(declaredSize) && declaredSize > maxResponseBytes) {
    await response.body?.cancel();
    throw new JBCenterRequestError(
      "JB Center response exceeds the size limit",
      502,
    );
  }
  if (!response.headers.get("content-type")?.toLowerCase().includes("json")) {
    await response.body?.cancel();
    throw new JBCenterRequestError(
      "JB Center returned an invalid content type",
      502,
    );
  }
  if (!response.body) {
    throw new JBCenterRequestError("JB Center returned an empty response", 502);
  }

  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > maxResponseBytes) {
        await reader.cancel("JB Center response exceeds the size limit");
        throw new JBCenterRequestError(
          "JB Center response exceeds the size limit",
          502,
        );
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  try {
    return JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    throw new JBCenterRequestError("JB Center returned invalid JSON", 502);
  }
}

function filenameOf(content: Blob, fallback: string): string {
  const candidate = (content as Blob & { name?: unknown }).name;
  return typeof candidate === "string" && candidate ? candidate : fallback;
}

export class JBCenterClient {
  readonly baseUrl: string;
  private readonly fetchImpl: typeof fetch;
  private readonly maxResponseBytes: number;
  private readonly timeoutMs: number;
  private nextRpcId = 1;

  constructor(options: JBCenterClientOptions = {}) {
    this.baseUrl = normalizeBaseUrl(options.baseUrl ?? JBCENTER_DEFAULT_URL);
    // Calling a native browser fetch through `this.fetchImpl(...)` otherwise
    // supplies the JBCenterClient as its receiver. Browsers brand-check the
    // receiver as Window and reject the request with "Illegal invocation".
    this.fetchImpl = options.fetch ?? globalThis.fetch.bind(globalThis);
    this.maxResponseBytes =
      options.maxResponseBytes ?? MAX_JBCENTER_RESPONSE_BYTES;
    this.timeoutMs = options.timeoutMs ?? JBCENTER_REQUEST_TIMEOUT_MS;
    if (
      !Number.isSafeInteger(this.maxResponseBytes) ||
      this.maxResponseBytes <= 0
    ) {
      throw new TypeError("maxResponseBytes must be a positive safe integer");
    }
    if (!Number.isFinite(this.timeoutMs) || this.timeoutMs <= 0) {
      throw new TypeError("timeoutMs must be positive");
    }
  }

  prepareIntent<TJb extends JBCenterJsonObject>(
    intent: JBCenterIntentInput<TJb>,
    options?: JBCenterRequestOptions,
  ): Promise<JBCenterPreparedIntent<TJb>> {
    return this.fetchJson(
      "v1/intents/message",
      { method: "POST", body: JSON.stringify(intent) },
      isPreparedIntent,
      options,
    ) as Promise<JBCenterPreparedIntent<TJb>>;
  }

  publishIntent<TJb extends JBCenterJsonObject>(
    intent: JBCenterPublishIntentInput<TJb>,
    options?: JBCenterRequestOptions,
  ): Promise<JBCenterIntent<TJb>> {
    return this.fetchJson(
      "v1/intents",
      { method: "POST", body: JSON.stringify(intent) },
      isIntent,
      options,
    ) as Promise<JBCenterIntent<TJb>>;
  }

  getIntent<TJb extends JBCenterJsonObject = JBCenterJsonObject>(
    intentId: string,
    options?: JBCenterRequestOptions,
  ): Promise<JBCenterIntent<TJb>> {
    return this.fetchJson(
      `v1/intents/${encodeURIComponent(intentId)}`,
      {},
      isIntent,
      options,
    ) as Promise<JBCenterIntent<TJb>>;
  }

  searchIntents(
    params: JBCenterSearchParams = {},
    options?: JBCenterRequestOptions,
  ): Promise<JBCenterSearchPage> {
    const query = new URLSearchParams();
    if (params.query !== undefined) query.set("q", params.query);
    if (params.limit !== undefined) query.set("limit", String(params.limit));
    if (params.cursor !== undefined) query.set("cursor", params.cursor);
    const suffix = query.size ? `?${query}` : "";
    return this.fetchJson(`v1/search${suffix}`, {}, isSearchPage, options);
  }

  recordDeployment(
    intentId: string,
    deployment: JBCenterDeploymentInput,
    options?: JBCenterRequestOptions,
  ): Promise<JBCenterDeployment> {
    return this.fetchJson(
      `v1/intents/${encodeURIComponent(intentId)}/deployments`,
      { method: "POST", body: JSON.stringify(deployment) },
      isDeployment,
      {
        ...options,
        timeoutMs: options?.timeoutMs ?? JBCENTER_DEPLOYMENT_TIMEOUT_MS,
      },
    );
  }

  pinJson(
    value: JBCenterJsonObject,
    options?: JBCenterRequestOptions,
  ): Promise<JBCenterPin> {
    return this.fetchJson(
      "v1/pins/json",
      { method: "POST", body: JSON.stringify(value) },
      isPin,
      { ...options, timeoutMs: options?.timeoutMs ?? JBCENTER_PIN_TIMEOUT_MS },
    );
  }

  pinImage(
    content: Blob,
    options?: JBCenterRequestOptions & { filename?: string },
  ): Promise<JBCenterPin> {
    return this.pinFile("v1/pins/file", content, "image", options);
  }

  pinMedia(
    content: Blob,
    options?: JBCenterRequestOptions & { filename?: string },
  ): Promise<JBCenterPin> {
    return this.pinFile("v1/pins/media", content, "media", options);
  }

  /**
   * Sends one read-only JSON-RPC request through JB Center. The service rejects
   * wallet, signing, transaction-submission, batch, and privileged methods.
   */
  async rpc<TResult = unknown>(
    chainId: number,
    request: JBCenterRpcRequest,
    options?: JBCenterRequestOptions,
  ): Promise<TResult> {
    if (!Number.isSafeInteger(chainId) || chainId <= 0) {
      throw new TypeError("chainId must be a positive safe integer");
    }
    if (!JBCENTER_RPC_METHODS.includes(request.method)) {
      throw new TypeError("JB Center RPC method is not supported");
    }
    if (request.params !== undefined && !Array.isArray(request.params)) {
      throw new TypeError("JB Center RPC params must be an array");
    }

    const id = this.nextRpcId;
    this.nextRpcId = id === Number.MAX_SAFE_INTEGER ? 1 : id + 1;
    const body = await this.fetchJson(
      `v1/rpc/${chainId}`,
      {
        method: "POST",
        body: JSON.stringify({ jsonrpc: "2.0", id, ...request }),
      },
      rpcEnvelope(id),
      options,
    );
    if ("error" in body) {
      throw new JBCenterRpcError(
        body.error.code,
        body.error.message,
        body.error.data,
      );
    }
    return body.result as TResult;
  }

  /** Returns an EIP-1193-shaped provider suitable for viem's `custom`. */
  rpcProvider(chainId: number): JBCenterRpcProvider {
    if (!Number.isSafeInteger(chainId) || chainId <= 0) {
      throw new TypeError("chainId must be a positive safe integer");
    }
    return {
      request: async <TResult = unknown>(request: {
        method: string;
        params?: readonly unknown[];
      }) => {
        if (
          !(JBCENTER_RPC_METHODS as readonly string[]).includes(request.method)
        ) {
          throw new TypeError("JB Center RPC method is not supported");
        }
        return this.rpc<TResult>(chainId, request as JBCenterRpcRequest);
      },
    };
  }

  private pinFile(
    path: string,
    content: Blob,
    fallbackName: string,
    options?: JBCenterRequestOptions & { filename?: string },
  ): Promise<JBCenterPin> {
    const body = new FormData();
    body.append(
      "file",
      content,
      options?.filename ?? filenameOf(content, fallbackName),
    );
    return this.fetchJson(path, { method: "POST", body }, isPin, {
      ...options,
      timeoutMs: options?.timeoutMs ?? JBCENTER_PIN_TIMEOUT_MS,
    });
  }

  private async fetchJson<T>(
    path: string,
    init: RequestInit,
    validate: Validator<T>,
    options: JBCenterRequestOptions = {},
  ): Promise<T> {
    const timeoutMs = options.timeoutMs ?? this.timeoutMs;
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
      throw new TypeError("timeoutMs must be positive");
    }

    const controller = new AbortController();
    const abort = () => controller.abort(options.signal?.reason);
    options.signal?.addEventListener("abort", abort, { once: true });
    const timeoutReason = new JBCenterTimeoutError(timeoutMs);
    const timeout = setTimeout(
      () => controller.abort(timeoutReason),
      timeoutMs,
    );
    try {
      if (options.signal?.aborted) abort();
      const headers = new Headers(init.headers);
      headers.set("Accept", "application/json");
      if (typeof init.body === "string") {
        headers.set("Content-Type", "application/json");
      }
      const response = await this.fetchImpl(`${this.baseUrl}/${path}`, {
        ...init,
        headers,
        signal: controller.signal,
      });
      const body = await readBoundedJson(response, this.maxResponseBytes);
      if (!response.ok) {
        const envelope = record(body) ? (body as ErrorEnvelope) : {};
        const code =
          typeof envelope.error?.code === "string"
            ? envelope.error.code
            : undefined;
        const message =
          typeof envelope.error?.message === "string"
            ? envelope.error.message
            : `JB Center request failed (${response.status})`;
        const retryAfterHeader = response.headers.get("retry-after");
        const retryAfter = Number(retryAfterHeader);
        throw new JBCenterRequestError(
          message,
          response.status,
          code,
          response.headers.get("x-request-id") ?? undefined,
          retryAfterHeader !== null &&
          Number.isFinite(retryAfter) &&
          retryAfter >= 0
            ? retryAfter
            : undefined,
        );
      }
      if (!validate(body)) {
        throw new JBCenterRequestError(
          "JB Center returned an invalid response",
          502,
          undefined,
          response.headers.get("x-request-id") ?? undefined,
        );
      }
      return body;
    } catch (error) {
      if (controller.signal.reason === timeoutReason) throw timeoutReason;
      throw error;
    } finally {
      clearTimeout(timeout);
      options.signal?.removeEventListener("abort", abort);
    }
  }
}

export function createJBCenterClient(
  options: JBCenterClientOptions = {},
): JBCenterClient {
  return new JBCenterClient(options);
}

export function createJBCenterRpcProvider(
  chainId: number,
  options: JBCenterClientOptions = {},
): JBCenterRpcProvider {
  return new JBCenterClient(options).rpcProvider(chainId);
}

