      message: "Slow down",
      status: 429,
      code: "rate_limit",
      requestId: "request-1",
      retryAfter: 60,
    });
    await expect(client.searchIntents()).rejects.toMatchObject({
      status: 502,
      message: "JB Center returned an invalid response",
