function isNative(token: Address): boolean {
  return token.toLowerCase() === NATIVE_TOKEN.toLowerCase();
}

async function quoteV3ExactInput({
  client,
  config,
  tokenIn,
  tokenOut,
  amountIn,
}: {
  client: PublicClient;
  config: NativeSwapConfig;
  tokenIn: Address;
  tokenOut: Address;
  amountIn: bigint;
}): Promise<{ fee: number; amountOut: bigint } | null> {
  const quotes = await Promise.all(
    V3_FEES.map(async (fee) => {
      try {
        const call = await client.call({
          to: config.v3Quoter,
          data: encodeFunctionData({
            abi: v3QuoterAbi,
            functionName: "quoteExactInputSingle",
            args: [
              {
                tokenIn,
                tokenOut,
                amountIn,
                fee,
                sqrtPriceLimitX96: 0n,
              },
            ],
          }),
        });
        if (!call.data) return null;
        const [amountOut] = decodeFunctionResult({
          abi: v3QuoterAbi,
          functionName: "quoteExactInputSingle",
          data: call.data,
        });
        return amountOut > 0n ? { fee, amountOut } : null;
      } catch {
        return null;
      }
    }),
  );
  return quotes.reduce<{ fee: number; amountOut: bigint } | null>(
    (best, quote) =>
      !quote || (best && best.amountOut >= quote.amountOut) ? best : quote,
    null,
  );
}

/**
 * Quote the best direct pool purchase, including the atomic ETH/USDC V3 bridge
 * when the user's payment currency differs from the hooked V4 pool currency.
 * Returns null unless its slippage-protected minimum beats terminal payment.
 */
export async function quoteDirectPaySwap({
  client,
  chainId,
  poolKey,
  pairIsCurrency0,
  paymentToken,
  amount,
  payPreview,
  paySettlement = "issuance",
  slippageBps = 100n,
}: {
  client: PublicClient;
  chainId: JBChainId;
  poolKey: UniswapV4PoolKey;
  pairIsCurrency0: boolean;
  paymentToken: Address;
  amount: bigint;
  payPreview: PayPreview;
  paySettlement?: PaySettlement;
  slippageBps?: bigint;
}): Promise<DirectPaySwapQuote | null> {
  if (!uniswapV4Deployment(chainId)?.universalRouter || amount <= 0n) {
    return null;
  }
  const currencyIn = pairIsCurrency0 ? poolKey.currency0 : poolKey.currency1;
  const normalizedPayment = isNative(paymentToken)
    ? zeroAddress
    : paymentToken.toLowerCase();
  let v4AmountIn = amount;
  let inputRoute: DirectPayInputRoute = { kind: "single-v4" };

  if (currencyIn.toLowerCase() !== normalizedPayment) {
    const config = NATIVE_SWAP_BY_CHAIN[chainId];
    const canBridgeNative =
      !!config &&
      isNative(paymentToken) &&
      currencyIn.toLowerCase() === config.bridgeToken.toLowerCase();
    const canBridgeUsdcToNative =
      !!config &&
      paymentToken.toLowerCase() === config.bridgeToken.toLowerCase() &&
      currencyIn.toLowerCase() === zeroAddress;
    if (!config || (!canBridgeNative && !canBridgeUsdcToNative)) return null;
    const bridgeQuote = await quoteV3ExactInput({
      client,
      config,
      tokenIn: canBridgeNative ? config.wrappedNative : config.bridgeToken,
      tokenOut: canBridgeNative ? config.bridgeToken : config.wrappedNative,
      amountIn: amount,
    });
    if (!bridgeQuote) return null;
    v4AmountIn = bridgeQuote.amountOut;
    inputRoute = canBridgeNative
      ? {
          kind: "native-v3-v4",
          wrappedNative: config.wrappedNative,
          bridgeToken: config.bridgeToken,
          bridgeTokenSymbol: "USDC",
          bridgeTokenDecimals: 6,
          v3Fee: bridgeQuote.fee,
          quotedBridgeAmount: bridgeQuote.amountOut,
        }
      : {
          kind: "erc20-v3-native-v4",
          inputToken: config.bridgeToken,
          wrappedNative: config.wrappedNative,
          bridgeTokenSymbol: "ETH",
          bridgeTokenDecimals: 18,
          v3Fee: bridgeQuote.fee,
          quotedBridgeAmount: bridgeQuote.amountOut,
        };
  }

  const quotedTokenCount = await quoteUniswapV4ExactInputSingle(client, {
    chainId,
    poolKey,
    zeroForOne: pairIsCurrency0,
    amountIn: v4AmountIn,
  });
  const best = chooseBestPayRoute({
    pay: payPreview,
    paySettlement,
    directSwapQuote: quotedTokenCount,
    slippageBps,
  });
  if (best.kind !== "direct-swap") return null;
  return {
    kind: "direct-swap",
    poolKey,
    zeroForOne: pairIsCurrency0,
    quotedTokenCount,
    minimumTokenCount: best.beneficiaryTokenCount,
    beneficiaryTokenCount: best.beneficiaryTokenCount,
    reservedTokenCount: 0n,
    inputRoute,
  };
}

function encodeV4SwapFromRouterBalance({
  quote,
  recipient,
  currencyIn,
}: {
  quote: DirectPaySwapQuote;
  recipient: Address;
  currencyIn: Address;
}): Hex {
  const swap = encodeAbiParameters(
    [
      {
        type: "tuple",
        components: [
          {
            type: "tuple",
            components: [
              { type: "address" },
              { type: "address" },
              { type: "uint24" },
              { type: "int24" },
              { type: "address" },
            ],
          },
          { type: "bool" },
          { type: "uint128" },
          { type: "uint128" },
          { type: "bytes" },
        ],
      },
    ],
    [
      [
        [
          quote.poolKey.currency0,
          quote.poolKey.currency1,
          quote.poolKey.fee,
          quote.poolKey.tickSpacing,
          quote.poolKey.hooks,
        ],
        quote.zeroForOne,
        0n,
        quote.minimumTokenCount,
        "0x",
      ],
    ],
  );
  const settle = encodeAbiParameters(
    [{ type: "address" }, { type: "uint256" }, { type: "bool" }],
    [currencyIn, CONTRACT_BALANCE, false],
  );
  const currencyOut = quote.zeroForOne
    ? quote.poolKey.currency1
    : quote.poolKey.currency0;
  const take = encodeAbiParameters(
    [{ type: "address" }, { type: "address" }, { type: "uint256" }],
    [currencyOut, recipient, 0n],
  );
  return encodeAbiParameters(
    [{ type: "bytes" }, { type: "bytes[]" }],
    ["0x0b060e", [settle, swap, take]],
  );
}

/** Build the atomic Universal Router transaction for a direct-pay quote. */
export function buildDirectPaySwapTx({
  chainId,
  quote,
  amount,
  recipient,
  deadline,
}: {
  chainId: JBChainId;
  quote: DirectPaySwapQuote;
  amount: bigint;
  recipient: Address;
  deadline: bigint;
}) {
  if (quote.inputRoute.kind === "single-v4") {
    return buildUniswapV4ExactInputSwapTx({
      chainId,
      poolKey: quote.poolKey,
      zeroForOne: quote.zeroForOne,
      amountIn: amount,
      minimumAmountOut: quote.minimumTokenCount,
      recipient,
      deadline,
    });
  }
  if (amount <= 0n || amount > UINT128_MAX || quote.minimumTokenCount <= 0n) {
    throw new Error("Swap amounts are outside the supported range.");
  }
  const config = NATIVE_SWAP_BY_CHAIN[chainId];
  const router = uniswapV4Deployment(chainId)?.universalRouter;
  if (!config || !router) {
    throw new Error("No supported native bridge route on this chain.");
  }

  if (quote.inputRoute.kind === "erc20-v3-native-v4") {
    if (
      quote.inputRoute.inputToken.toLowerCase() !==
        config.bridgeToken.toLowerCase() ||
      quote.inputRoute.wrappedNative.toLowerCase() !==
        config.wrappedNative.toLowerCase()
    ) {
      throw new Error(
        "This ERC-20 bridge route is not supported on this chain.",
      );
    }
    const v3Input = encodeAbiParameters(
      [
        { type: "address" },
        { type: "uint256" },
        { type: "uint256" },
        { type: "bytes" },
        { type: "bool" },
      ],
      [
        ADDRESS_THIS,
        amount,
        0n,
        encodePacked(
          ["address", "uint24", "address"],
          [
            quote.inputRoute.inputToken,
            quote.inputRoute.v3Fee,
            quote.inputRoute.wrappedNative,
          ],
        ),
        true,
      ],
    );
    const unwrapInput = encodeAbiParameters(
      [{ type: "address" }, { type: "uint256" }],
      [ADDRESS_THIS, 0n],
    );
    const v4Input = encodeV4SwapFromRouterBalance({
      quote,
      recipient,
      currencyIn: zeroAddress,
    });
    return {
      chainId,
      address: router,
      abi: universalRouterAbi,
      functionName: "execute" as const,
      args: [
        "0x000c10" as Hex,
        [v3Input, unwrapInput, v4Input],
        deadline,
      ] as const,
      value: 0n,
    };
  }

  if (
    quote.inputRoute.bridgeToken.toLowerCase() !==
      config.bridgeToken.toLowerCase() ||
    quote.inputRoute.wrappedNative.toLowerCase() !==
      config.wrappedNative.toLowerCase()
  ) {
    throw new Error("This native bridge route is not supported on this chain.");
  }
  const wrapInput = encodeAbiParameters(
    [{ type: "address" }, { type: "uint256" }],
    [ADDRESS_THIS, amount],
  );
  const v3Input = encodeAbiParameters(
    [
      { type: "address" },
      { type: "uint256" },
      { type: "uint256" },
      { type: "bytes" },
      { type: "bool" },
    ],
    [
      ADDRESS_THIS,
      amount,
      0n,
      encodePacked(
        ["address", "uint24", "address"],
        [
          quote.inputRoute.wrappedNative,
          quote.inputRoute.v3Fee,
          quote.inputRoute.bridgeToken,
        ],
      ),
      false,
    ],
  );
  const v4Input = encodeV4SwapFromRouterBalance({
    quote,
    recipient,
    currencyIn: quote.inputRoute.bridgeToken,
  });
  return {
    chainId,
    address: router,
    abi: universalRouterAbi,
    functionName: "execute" as const,
    args: ["0x0b0010" as Hex, [wrapInput, v3Input, v4Input], deadline] as const,
    value: amount,
  };
}

/** Prepend Universal Router's PERMIT2_PERMIT command to a reviewed swap. */
export function addPermit2SignatureToDirectPaySwap(
  request: ReturnType<typeof buildDirectPaySwapTx>,
  authorization: Permit2SignatureAuthorization,
  signature: Hex,
): ReturnType<typeof buildDirectPaySwapTx> {
  if (request.address.toLowerCase() !== authorization.spender.toLowerCase()) {
    throw new Error(
      "The reviewed Permit2 authorization does not match the swap.",
    );
  }
  const [commands, inputs, deadline] = request.args;
  const commandShape = commands.toLowerCase();
  const supportedShape =
    (commandShape === "0x10" && inputs.length === 1) ||
    (commandShape === "0x000c10" && inputs.length === 3);
  if (!supportedShape) {
    throw new Error(
      "The reviewed swap has an unsupported Universal Router shape.",
    );
  }
  const permitInput = encodeAbiParameters(
    [
      {
        type: "tuple",
        components: [
          {
            type: "tuple",
            components: [
              { type: "address" },
              { type: "uint160" },
              { type: "uint48" },
              { type: "uint48" },
            ],
          },
          { type: "address" },
          { type: "uint256" },
        ],
      },
      { type: "bytes" },
    ],
    [
      [
        [
          authorization.token,
          authorization.amount,
          authorization.expiration,
          authorization.nonce,
        ],
        authorization.spender,
        authorization.sigDeadline,
      ],
      signature,
    ],
  );
  return {
    ...request,
    args: [
      `0x0a${commands.slice(2)}` as Hex,
      [permitInput, ...inputs],
      deadline,
    ],
  } as ReturnType<typeof buildDirectPaySwapTx>;
}

import {
  Address,
  ContractFunctionArgs,
  Hex,
  PublicClient,
  decodeEventLog,
  isAddressEqual,
  zeroAddress,
} from "viem";
import { NATIVE_TOKEN, NATIVE_TOKEN_DECIMALS } from "../constants.js";
import { jbControllerAbi, jbProjectsAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { BASE_CURRENCY_ETH, tokenCurrencyId } from "./currency.js";
import { JBRulesetConfig, JBRulesetMetadata } from "./rulesets.js";
import { JBAccountingContext } from "./terminals.js";
import { v6Address } from "./types.js";

type LaunchProjectArgs = ContractFunctionArgs<
  typeof jbControllerAbi,
  "payable",
  "launchProjectFor"
>;

/**
 * A terminal to attach to a project at launch, together with the accounting
 * contexts (tokens) it should accept.
 */
export type JBTerminalConfig = LaunchProjectArgs[3][number];

/**
 * A fund access limit group scoping how much of a terminal's token balance
 * the project can pay out / use as surplus allowance.
 */
export type JBFundAccessLimitGroup =
  JBRulesetConfig["fundAccessLimitGroups"][number];

/**
 * Read the fee (in wei) that `JBProjects` charges to create a new project.
 *
 * Launch transactions must send EXACTLY this value as `msg.value` or they
 * revert. The fee is dynamic — read it per chain right before launching, and
 * never reuse a value across chains.
 */
export async function getProjectCreationFee(
  client: PublicClient,
  chainId: JBChainId,
): Promise<bigint> {
  return client.readContract({
    address: v6Address("JBProjects", chainId),
    abi: jbProjectsAbi,
    functionName: "creationFee",
  });
}

/**
 * Build a `JBAccountingContext` for a token.
 *
 * By default the context currency is token-keyed: `uint32(uint160(token))`
 * (native token → 61166). Pass an explicit shared currency such as ETH=1 or
 * USD=2 when the terminal should convert this token through a protocol price
 * feed. A ruleset's `baseCurrency` is the denomination used to interpret its
 * issuance weight.
 *
 * @param token The token address. Defaults to the native token sentinel
 * (`0x…EEEe`).
 * @param decimals The token's decimals. Defaults to 18 for the native token;
 * REQUIRED for any other token (there is no safe default).
 * @param currency The context's currency id. Defaults to the token-keyed id.
 */
export function buildAccountingContext(
  token: Address = NATIVE_TOKEN,
  decimals?: number,
  currency: number = tokenCurrencyId(token),
): JBAccountingContext {
  const isNative = token.toLowerCase() === NATIVE_TOKEN.toLowerCase();
  if (decimals === undefined && !isNative) {
    throw new Error(
      `decimals is required for non-native token ${token} (there is no safe default)`,
    );
  }
  return {
    token,
    decimals: decimals ?? NATIVE_TOKEN_DECIMALS,
    currency,
  };
}

/**
 * Build the standard terminal configurations for a launch:
 *
 * 1. `JBMultiTerminal` accepting the given accounting contexts (the
 *    project's treasury), and
 * 2. `JBRouterTerminalRegistry` with EMPTY accounting contexts — registering
 *    the router registry makes the project accept ANY token via swap
 *    routing. It is skipped on chains where it isn't deployed.
 *
 * @param args.accountingContexts The contexts the multi terminal accepts.
 * Defaults to just the native token context.
 */
export function buildTerminalConfigurations(args: {
  chainId: JBChainId;
  accountingContexts?: readonly JBAccountingContext[];
}): JBTerminalConfig[] {
  const configurations: JBTerminalConfig[] = [
    {
      terminal: v6Address("JBMultiTerminal", args.chainId),
      accountingContextsToAccept: args.accountingContexts ?? [
        buildAccountingContext(),
      ],
    },
  ];
  try {
    configurations.push({
      terminal: v6Address("JBRouterTerminalRegistry", args.chainId),
      accountingContextsToAccept: [],
    });
  } catch {
    // No router terminal registry on this chain — the multi terminal alone
    // is a valid configuration.
  }
  return configurations;
}

/**
 * Build a `JBRulesetMetadata` with safe defaults (v6 field names ONLY):
 * everything false/zero, `baseCurrency` ETH (1), no data hook.
 *
 * Note `scopeCashOutsToLocalBalances` is the v6 spelling — it replaces the
 * old inverted `useTotalSurplusForCashOuts`, and `false` keeps the v6
 * default behavior of cashing out against total surplus.
 *
 * @param overrides Any metadata fields to override.
 */
export function buildRulesetMetadata(
  overrides?: Partial<JBRulesetMetadata>,
): JBRulesetMetadata {
  return {
    reservedPercent: 0,
    cashOutTaxRate: 0,
    baseCurrency: BASE_CURRENCY_ETH,
    pausePay: false,
    pauseCreditTransfers: false,
    allowOwnerMinting: false,
    allowSetCustomToken: false,
    allowTerminalMigration: false,
    allowSetTerminals: false,
    allowSetController: false,
    allowAddAccountingContext: false,
    allowAddPriceFeed: false,
    ownerMustSendPayouts: false,
    holdFees: false,
    scopeCashOutsToLocalBalances: false,
    useDataHookForPay: false,
    useDataHookForCashOut: false,
    dataHook: zeroAddress,
    metadata: 0,
    ...overrides,
  };
}

/**
 * Build a `JBRulesetConfig` with safe defaults: starts as soon as possible,
 * no duration (rules can change any time), no issuance (`weight` 0), no
 * approval hook, default metadata, no splits, and ZERO payouts (an empty
 * `fundAccessLimitGroups` means the project can pay out NOTHING — funds can
 * only leave via cash outs).
 *
 * @param args.mustStartAtOrAfter Earliest start timestamp (uint48). 0 (the
 * default) starts at the deploy block. For omnichain launches pass ONE
 * shared timestamp so every chain's ruleset is byte-identical.
 * @param args.duration Seconds the ruleset is locked for. 0 = no duration.
 * @param args.weight Tokens issued per unit of `baseCurrency` paid, as an
 * 18-decimal fixed point (uint112). Later configurations can use the exported
 * `RULESET_WEIGHT_INHERIT` sentinel (1n); zero means genuine zero issuance.
 * @param args.weightCutPercent Issuance cut applied each cycle, out of 1e9.
 * @param args.approvalHook A deadline contract queued rulesets must clear.
 * @param args.metadata Ruleset metadata; see {@link buildRulesetMetadata}.
 * @param args.splitGroups Split groups to set alongside the ruleset.
 * @param args.fundAccessLimitGroups Payout limits / surplus allowances.
 */
export function buildRulesetConfiguration(args?: {
  mustStartAtOrAfter?: number;
  duration?: number;
  weight?: bigint;
  weightCutPercent?: number;
  approvalHook?: Address;
  metadata?: JBRulesetMetadata;
  splitGroups?: JBRulesetConfig["splitGroups"];
  fundAccessLimitGroups?: JBRulesetConfig["fundAccessLimitGroups"];
}): JBRulesetConfig {
  return {
    mustStartAtOrAfter: args?.mustStartAtOrAfter ?? 0,
    duration: args?.duration ?? 0,
    weight: args?.weight ?? 0n,
    weightCutPercent: args?.weightCutPercent ?? 0,
    approvalHook: args?.approvalHook ?? zeroAddress,
    metadata: args?.metadata ?? buildRulesetMetadata(),
    splitGroups: args?.splitGroups ?? [],
    fundAccessLimitGroups: args?.fundAccessLimitGroups ?? [],
  };
}

/**
 * Build a `JBController.launchProjectFor` transaction request creating a new
 * project on a single chain.
 *
 * The transaction is payable and must send EXACTLY the current project
 * creation fee — read it with {@link getProjectCreationFee} on the same
 * chain right before sending.
 *
 * @param args.owner The address that receives the project NFT (full control).
 * @param args.projectUri An IPFS URI (`ipfs://…`) pointing to the project's
 * metadata.
 * @param args.rulesetConfigurations The project's initial rulesets; see
 * {@link buildRulesetConfiguration}.
 * @param args.terminalConfigurations The project's terminals; see
 * {@link buildTerminalConfigurations}.
 * @param args.memo An optional memo emitted with the launch event.
 * @param args.creationFee The exact fee read from `JBProjects.creationFee()`.
 */
export function buildLaunchProjectTx(args: {
  chainId: JBChainId;
  owner: Address;
  projectUri: string;
  rulesetConfigurations: readonly JBRulesetConfig[];
  terminalConfigurations: readonly JBTerminalConfig[];
  memo?: string;
  creationFee: bigint;
}) {
  return {
    chainId: args.chainId,
    address: v6Address("JBController", args.chainId),
    abi: jbControllerAbi,
    functionName: "launchProjectFor" as const,
    args: [
      args.owner,
      args.projectUri,
      args.rulesetConfigurations,
      args.terminalConfigurations,
      args.memo ?? "",
    ] as const,
    value: args.creationFee,
  };
}

/** Minimal log shape needed to decode a project launch. */
export interface V6LaunchProjectLog {
  address: Address;
  data: Hex;
  topics: readonly Hex[];
}

/**
 * Decode the id of a project launched in a transaction, from one of its logs.
 *
 * Three logs identify a launch, and which one a receipt carries depends on the
 * path taken:
 *
 * - `JBController.LaunchProject` — a direct `launchProjectFor` on the controller.
 * - `JBController.LaunchRulesets` — a deployer-created project. `JBOmnichainDeployer`
 *   (and the 721 project deployer) create the project through `JBProjects.createFor`
 *   and then call `launchRulesetsFor`, so the controller never emits `LaunchProject`
 *   for them.
 * - `JBProjects.Create` — emitted by every path, since every project is an NFT
 *   minted by `JBProjects`.
 *
 * Checking the emitter matters: unrelated contracts can emit an event with the
 * same signature, and ERC-721 `Transfer` logs in a complex receipt are not a
 * reliable way to identify which mint was the Juicebox project NFT.
 */
export function decodeLaunchProjectId(
  log: V6LaunchProjectLog,
  { chainId }: { chainId: JBChainId },
): bigint | null {
  const topics = log.topics as [Hex, ...Hex[]];

  if (isAddressEqual(log.address, v6Address("JBController", chainId))) {
    for (const eventName of ["LaunchProject", "LaunchRulesets"] as const) {
      try {
        const decoded = decodeEventLog({
          abi: jbControllerAbi,
          eventName,
          data: log.data,
          topics,
          strict: true,
        });
        if (decoded.eventName === eventName) return decoded.args.projectId;
      } catch {
        // Not this event; try the next.
      }
    }
    return null;
  }

  if (isAddressEqual(log.address, v6Address("JBProjects", chainId))) {
    try {
      const decoded = decodeEventLog({
        abi: jbProjectsAbi,
        eventName: "Create",
        data: log.data,
        topics,
        strict: true,
      });
      return decoded.eventName === "Create" ? decoded.args.projectId : null;
    } catch {
      return null;
    }
  }

  return null;
}

/** Return the first canonical v6 project id found in a transaction's logs. */
export function projectIdFromLaunchLogs(
  logs: readonly V6LaunchProjectLog[],
  args: { chainId: JBChainId },
): bigint | null {
  for (const log of logs) {
    const projectId = decodeLaunchProjectId(log, args);
    if (projectId !== null) return projectId;
  }
  return null;
}

/**
 * The denominator for REVLoans fee percents: prepaid fee percents and source fee percents
 * are expressed out of 1000.
 */
export const LOANS_MAX_FEE = 1000n;

/**
 * The minimum `prepaidFeePercent` REVLoans accepts when borrowing: 25 of
 * {@link LOANS_MAX_FEE} (2.5%), paid upfront to the source revnet.
 */
export const MIN_PREPAID_FEE_PERCENT = 25n;

/** The largest prepaid source fee REVLoans accepts: 500 / 1000 = 50%. */
export const MAX_PREPAID_FEE_PERCENT = 500n;

/** The upfront fee REVLoans routes to the $REV revnet on every borrow: 1%. */
export const REV_PREPAID_FEE_PERCENT = 10n;

export interface LoanOpeningAmounts {
  grossBorrowAmount: bigint;
  protocolFee: bigint;
  revFee: bigint;
  sourceFee: bigint;
  netBorrowAmount: bigint;
}

/**
 * Calculate spendable loan proceeds using the contracts' floor-rounded fee arithmetic.
 */
export function loanOpeningAmounts({
  grossBorrowAmount,
  prepaidSourceFeePercent = MIN_PREPAID_FEE_PERCENT,
  protocolFeeApplies = true,
  revFeeApplies = true,
}: {
  grossBorrowAmount: bigint;
  prepaidSourceFeePercent?: bigint;
  protocolFeeApplies?: boolean;
  revFeeApplies?: boolean;
}): LoanOpeningAmounts {
  if (grossBorrowAmount < 0n) {
    throw new Error("grossBorrowAmount cannot be negative.");
  }
  if (
    prepaidSourceFeePercent < MIN_PREPAID_FEE_PERCENT ||
    prepaidSourceFeePercent > MAX_PREPAID_FEE_PERCENT
  ) {
    throw new Error(
      `prepaidSourceFeePercent must be between ${MIN_PREPAID_FEE_PERCENT} and ${MAX_PREPAID_FEE_PERCENT}.`,
    );
  }
  const protocolFee = protocolFeeApplies ? grossBorrowAmount / 40n : 0n;
  const revFee = revFeeApplies
    ? (grossBorrowAmount * REV_PREPAID_FEE_PERCENT) / LOANS_MAX_FEE
    : 0n;
  const sourceFee =
    (grossBorrowAmount * prepaidSourceFeePercent) / LOANS_MAX_FEE;
  const totalFees = protocolFee + revFee + sourceFee;
  return {
    grossBorrowAmount,
    protocolFee,
    revFee,
    sourceFee,
    netBorrowAmount:
      grossBorrowAmount > totalFees ? grossBorrowAmount - totalFees : 0n,
  };
}

/** Convenience accessor for {@link loanOpeningAmounts}. */
export function netLoanProceeds(
  grossBorrowAmount: bigint,
  prepaidSourceFeePercent = MIN_PREPAID_FEE_PERCENT,
): bigint {
  return loanOpeningAmounts({
    grossBorrowAmount,
    prepaidSourceFeePercent,
  }).netBorrowAmount;
}

import { Address, Hex, PublicClient } from "viem";
import { revLoansAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { LOANS_MAX_FEE, MIN_PREPAID_FEE_PERCENT } from "./loanMath.js";
import { v6Address } from "./types.js";
export * from "./loanMath.js";

/**
 * The JBPermissions permission id apps grant to the REVLoans contract before borrowing
 * against a holder's tokens: `BURN_TOKENS` (11, per `JBPermissionIds`). REVLoans burns
 * the holder's collateral via `JBController.burnTokensOf`, which is gated on this
 * permission ONLY — never grant ROOT (1) to REVLoans; ROOT silently satisfies every
 * permission check and hands the contract full operator power over the holder.
 */
export const REVLOANS_BURN_PERMISSION_ID = 11;

/**
 * @deprecated Use {@link REVLOANS_BURN_PERMISSION_ID}. This constant previously held
 * ROOT (1) — a grant that gives REVLoans unrestricted operator power over the holder.
 * It now aliases `BURN_TOKENS` (11), the only permission REVLoans needs. Audit any
 * grants made with the old value and revoke ROOT from REVLoans.
 */
export const REVLOANS_PERMISSION_ID = REVLOANS_BURN_PERMISSION_ID;

/**
 * A Permit2 single allowance, passed to `repayLoan` when repaying with an ERC-20 via a
 * signed permit. Pass {@link EMPTY_SINGLE_ALLOWANCE} (the default) when repaying with the
 * native token or a pre-approved ERC-20.
 */
export type JBSingleAllowance = {
  sigDeadline: bigint;
  amount: bigint;
  expiration: number;
  nonce: number;
  signature: Hex;
};

/**
 * An empty Permit2 allowance: use when no permit signature is needed (native-token
 * repayments, or ERC-20s already approved to REVLoans).
 */
export const EMPTY_SINGLE_ALLOWANCE: JBSingleAllowance = {
  sigDeadline: 0n,
  amount: 0n,
  expiration: 0,
  nonce: 0,
  signature: "0x",
};

/**
 * Builds a `borrowFrom` transaction on REVLoans, opening a loan against a holder's revnet
 * tokens.
 *
 * The caller must be the holder or have permission to act on their behalf, and the holder
 * must have granted permission id {@link REVLOANS_BURN_PERMISSION_ID} to REVLoans.
 *
 * @param args.chainId The chain to borrow on.
 * @param args.revnetId The revnet to borrow from.
 * @param args.token The terminal token to borrow.
 * @param args.minBorrowAmount The minimum amount to borrow, denominated in `token`.
 * Defaults to 0.
 * @param args.collateralCount The number of revnet tokens to lock as collateral, as a
 * fixed point number with 18 decimals.
 * @param args.beneficiary The address that receives the borrowed funds and the loan NFT.
 * @param args.prepaidFeePercent The fee percent to prepay, out of {@link LOANS_MAX_FEE}.
 * Must be at least {@link MIN_PREPAID_FEE_PERCENT}.
 * @param args.holder The address whose tokens are used as collateral.
 */
export function buildBorrowTx({
  chainId,
  revnetId,
  token,
  minBorrowAmount = 0n,
  collateralCount,
  beneficiary,
  prepaidFeePercent,
  holder,
}: {
  chainId: JBChainId;
  revnetId: bigint;
  token: Address;
  minBorrowAmount?: bigint;
  collateralCount: bigint;
  beneficiary: Address;
  prepaidFeePercent: bigint;
  holder: Address;
}): {
  chainId: JBChainId;
  address: Address;
  abi: typeof revLoansAbi;
  functionName: "borrowFrom";
  args: readonly [bigint, Address, bigint, bigint, Address, bigint, Address];
} {
  return {
    chainId,
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "borrowFrom",
    args: [
      revnetId,
      token,
      minBorrowAmount,
      collateralCount,
      beneficiary,
      prepaidFeePercent,
      holder,
    ],
  };
}

/**
 * Builds a `repayLoan` transaction on REVLoans, paying down a loan and reclaiming
 * collateral.
 *
 * Payable: when the loan's source token is the native token, send the repayment as
 * `value`.
 *
 * @param args.chainId The chain the loan lives on.
 * @param args.loanId The id of the loan being repaid (also the loan NFT's token id).
 * @param args.maxRepayBorrowAmount The maximum amount to repay, denominated in the loan's
 * source token. Excess above what's owed is refunded.
 * @param args.collateralCountToReturn The number of collateral tokens to reclaim, as a
 * fixed point number with 18 decimals.
 * @param args.beneficiary The address that receives the reclaimed collateral (and any new
 * loan NFT for a partial repayment).
 * @param args.allowance A Permit2 allowance for ERC-20 repayments. Defaults to
 * {@link EMPTY_SINGLE_ALLOWANCE}.
 * @param args.value The native-token repayment to send along. Defaults to 0.
 */
export function buildRepayLoanTx({
  chainId,
  loanId,
  maxRepayBorrowAmount,
  collateralCountToReturn,
  beneficiary,
  allowance = EMPTY_SINGLE_ALLOWANCE,
  value = 0n,
}: {
  chainId: JBChainId;
  loanId: bigint;
  maxRepayBorrowAmount: bigint;
  collateralCountToReturn: bigint;
  beneficiary: Address;
  allowance?: JBSingleAllowance;
  value?: bigint;
}): {
  chainId: JBChainId;
  address: Address;
  abi: typeof revLoansAbi;
  functionName: "repayLoan";
  args: readonly [bigint, bigint, bigint, Address, JBSingleAllowance];
  value: bigint;
} {
  return {
    chainId,
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "repayLoan",
    args: [
      loanId,
      maxRepayBorrowAmount,
      collateralCountToReturn,
      beneficiary,
      allowance,
    ],
    value,
  };
}

/**
 * Builds a `reallocateCollateralFromLoan` transaction on REVLoans, moving collateral out
 * of an existing loan and into a new loan (optionally adding more collateral and borrowing
 * more).
 *
 * Note: this internally opens a new loan with the full current borrow capacity, so it is
 * economically equivalent to borrowing.
 *
 * @param args.chainId The chain the loan lives on.
 * @param args.loanId The id of the loan to reallocate collateral from.
 * @param args.collateralCountToTransfer The number of collateral tokens to move from the
 * existing loan into the new one, as a fixed point number with 18 decimals.
 * @param args.token The terminal token to borrow with the new loan.
 * @param args.minBorrowAmount The minimum amount the new loan must borrow, denominated in
 * `token`. Defaults to 0.
 * @param args.collateralCountToAdd The number of additional collateral tokens to add to
 * the new loan, as a fixed point number with 18 decimals.
 * @param args.beneficiary The address that receives the borrowed funds and the new loan
 * NFT.
 * @param args.prepaidFeePercent The fee percent to prepay on the new loan, out of
 * {@link LOANS_MAX_FEE}. Must be at least {@link MIN_PREPAID_FEE_PERCENT}.
 */
export function buildReallocateCollateralTx({
  chainId,
  loanId,
  collateralCountToTransfer,
  token,
  minBorrowAmount = 0n,
  collateralCountToAdd,
  beneficiary,
  prepaidFeePercent,
}: {
  chainId: JBChainId;
  loanId: bigint;
  collateralCountToTransfer: bigint;
  token: Address;
  minBorrowAmount?: bigint;
  collateralCountToAdd: bigint;
  beneficiary: Address;
  prepaidFeePercent: bigint;
}): {
  chainId: JBChainId;
  address: Address;
  abi: typeof revLoansAbi;
  functionName: "reallocateCollateralFromLoan";
  args: readonly [bigint, bigint, Address, bigint, bigint, Address, bigint];
} {
  return {
    chainId,
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "reallocateCollateralFromLoan",
    args: [
      loanId,
      collateralCountToTransfer,
      token,
      minBorrowAmount,
      collateralCountToAdd,
      beneficiary,
      prepaidFeePercent,
    ],
  };
}

/**
 * Reads how much a given collateral count can borrow from a revnet, via
 * `REVLoans.borrowableAmountFrom`.
 *
 * @param client A viem PublicClient connected to `chainId`.
 * @param args.chainId The chain to read on.
 * @param args.revnetId The revnet to borrow from.
 * @param args.collateralCount The number of revnet tokens that would be locked as
 * collateral, as a fixed point number with 18 decimals.
 * @param args.decimals The decimals the returned amounts should be denominated in.
 * @param args.currency The currency the returned amounts should be denominated in.
 * @returns `borrowableNow` (currently borrowable, net of the revnet's cash-out delay) and
 * `borrowableCapacity` (the full capacity the collateral represents).
 */
export async function getBorrowableAmount(
  client: PublicClient,
  {
    chainId,
    revnetId,
    collateralCount,
    decimals,
    currency,
  }: {
    chainId: JBChainId;
    revnetId: bigint;
    collateralCount: bigint;
    decimals: bigint;
    currency: bigint;
  },
): Promise<{ borrowableNow: bigint; borrowableCapacity: bigint }> {
  const [borrowableNow, borrowableCapacity] = await client.readContract({
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "borrowableAmountFrom",
    args: [revnetId, collateralCount, decimals, currency],
  });

  return { borrowableNow, borrowableCapacity };
}

import { Address, Hex, PublicClient, zeroAddress } from "viem";
import { JBOmnichainDeployerContracts } from "../contracts.js";
import {
  jb721TiersHookAbi,
  jb721TiersHookStoreAbi,
  jbContractAddress,
  jbOmnichainDeployerAbi,
} from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { isMissingContractFunctionError } from "../utils/errors.js";
import { ipfsAssetPath, isIpfsCid } from "../utils/ipfs.js";
import { getRevnetTiered721Hook } from "./revnets.js";
import { getCurrentRuleset, type JBRulesetWithMetadata } from "./rulesets.js";

/**
 * App-level sentinel convention used by Juicebox 721 shops for effectively
 * unlimited inventory.
 */
export const TIER_UNLIMITED_SUPPLY = 999_999_999;

/**
 * JB721TiersHookStore's `DISCOUNT_DENOMINATOR`: a tier's `discountPercent` is
 * out of 200, so the shopper-facing "% off" is `discountPercent / 2`.
 */
export const DISCOUNT_DENOMINATOR = 200n;

/** The 721 tiers hook's ruleset-metadata bit which pauses eligible transfers. */
export const JB721_RULESET_METADATA_PAUSE_TRANSFERS = 1 << 0;

/** The 721 tiers hook's ruleset-metadata bit which pauses pending reserve mints. */
export const JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES = 1 << 1;

/** The protocol stores 14 app-specific bits in `JBRulesetMetadata.metadata`. */
export const JB_RULESET_METADATA_APP_BITS_MAX = 0x3fff;

/** 721-specific overrides accepted by {@link build721RulesetMetadata}. */
export interface JB721RulesetMetadataInput {
  /** Existing app-specific metadata. Unrelated bits are preserved. */
  metadata?: number;
  /** Pause transfers for tiers whose `transfersPausable` flag is enabled. */
  pauseTransfers?: boolean;
  /** Pause minting the hook's pending reserve tokens. */
  pauseMintPendingReserves?: boolean;
}

/** 721-specific flags decoded from app-specific ruleset metadata. */
export interface JB721RulesetMetadata {
  pauseTransfers: boolean;
  pauseMintPendingReserves: boolean;
}

function assertRulesetAppMetadata(metadata: number): void {
  if (
    !Number.isInteger(metadata) ||
    metadata < 0 ||
    metadata > JB_RULESET_METADATA_APP_BITS_MAX
  ) {
    throw new Error(
      `Ruleset app metadata must be an integer between 0 and ${JB_RULESET_METADATA_APP_BITS_MAX}.`,
    );
  }
}

function setMetadataFlag(
  metadata: number,
  flag: number,
  enabled: boolean | undefined,
): number {
  if (enabled === undefined) return metadata;
  return enabled ? metadata | flag : metadata & ~flag;
}

/**
 * Set the 721 tiers hook's ruleset flags while preserving every unrelated app
 * metadata bit. This is important when composing with other hooks; for
 * example, Revnets use another bit to permit sucker deployment.
 *
 * A transfer is only paused when `pauseTransfers` is true AND the transferred
 * tier was created with `transfersPausable`. Mints and burns remain possible.
 * Omitted overrides preserve the corresponding bit in `metadata`.
 */
export function build721RulesetMetadata(
  input: JB721RulesetMetadataInput = {},
): number {
  const metadata = input.metadata ?? 0;
  assertRulesetAppMetadata(metadata);

  return setMetadataFlag(
    setMetadataFlag(
      metadata,
      JB721_RULESET_METADATA_PAUSE_TRANSFERS,
      input.pauseTransfers,
    ),
    JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
    input.pauseMintPendingReserves,
  );
}

/** Decode the 721 tiers hook's flags without interpreting unrelated bits. */
export function decode721RulesetMetadata(
  metadata: number,
): JB721RulesetMetadata {
  assertRulesetAppMetadata(metadata);
  return {
    pauseTransfers: (metadata & JB721_RULESET_METADATA_PAUSE_TRANSFERS) !== 0,
    pauseMintPendingReserves:
      (metadata & JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES) !== 0,
  };
}

/** Canonical display fields understood across Juicebox 721 metadata writers. */
export interface TierMetadata {
  name?: string;
  description?: string;
  image?: string;
  animationUrl?: string;
  mediaType?: string;
  categoryName?: string;
}

/** Input accepted by {@link buildTierMetadata}. */
export interface TierMetadataInput {
  name: string;
  description?: string;
  image?: string;
  animationUrl?: string;
  mediaType?: string;
  categoryName?: string;
}

/** JSON shape written for a tier's pinned metadata. */
export interface StoredTierMetadata {
  name: string;
  description?: string;
  image?: string;
  animation_url?: string;
  mediaType?: string;
  categoryName?: string;
}

function nonEmptyString(value: unknown): string | undefined {
  return typeof value === "string" && value ? value : undefined;
}

function decodeBase64Utf8(value: string): string {
  const binary = atob(value);
  return new TextDecoder().decode(
    Uint8Array.from(binary, (character) => character.charCodeAt(0)),
  );
}

/**
 * Parse a `data:application/json` tier URI. Invalid, non-object, and non-data
 * values return `null` so callers can fall back to an IPFS metadata fetch.
 */
export function parseTierMetadataJson(
  uri: string,
): Record<string, unknown> | null {
  if (!uri.startsWith("data:application/json")) return null;
  const comma = uri.indexOf(",");
  if (comma === -1) return null;

  try {
    const header = uri.slice(0, comma);
    const payload = uri.slice(comma + 1);
    const json = JSON.parse(
      header.split(";").includes("base64")
        ? decodeBase64Utf8(payload)
        : decodeURIComponent(payload),
    ) as unknown;
    return json !== null && typeof json === "object" && !Array.isArray(json)
      ? (json as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

/**
 * Normalize legacy and current tier metadata field names into one display
 * shape. Only non-empty strings are returned.
 */
export function pickTierMetadata(json: Record<string, unknown>): TierMetadata {
  return {
    name: nonEmptyString(json.productName) ?? nonEmptyString(json.name),
    description:
      nonEmptyString(json.productDescription) ??
      nonEmptyString(json.description),
    image: nonEmptyString(json.image) ?? nonEmptyString(json.imageUri),
    animationUrl:
      nonEmptyString(json.animation_url) ?? nonEmptyString(json.animationUrl),
    mediaType:
      nonEmptyString(json.mediaType) ??
      nonEmptyString(json.animationType) ??
      nonEmptyString(json.mimeType),
    categoryName: nonEmptyString(json.categoryName),
  };
}

/** Whether a tier media value uses an immutable or browser-loadable URI form. */
export function isSafeTierMediaUri(value: string): boolean {
  const uri = value.trim();
  if (!uri || /\s/.test(uri)) return false;

  const ipfsPath = ipfsAssetPath(uri);
  if (ipfsPath && isIpfsCid(ipfsPath.split("/")[0])) return true;
  if (isIpfsCid(uri.split("/")[0])) return true;
  if (/^data:(image|audio|video)\/[a-z0-9.+-]+[;,]/i.test(uri)) return true;

  try {
    const url = new URL(uri);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

/** Build the canonical JSON object pinned for one tier. */
export function buildTierMetadata(
  input: TierMetadataInput,
): StoredTierMetadata {
  const name = input.name.trim();
  if (!name) throw new Error("Tier name is required.");

  const optional = (value: string | undefined) => value?.trim() || undefined;
  const image = optional(input.image);
  const animationUrl = optional(input.animationUrl);
  const mediaType = optional(input.mediaType);
  if (image && !isSafeTierMediaUri(image)) {
    throw new Error(
      "Tier images must use IPFS, HTTP, HTTPS, or an image data URI.",
    );
  }
  if (animationUrl && !isSafeTierMediaUri(animationUrl)) {
    throw new Error(
      "Tier animations must use IPFS, HTTP, HTTPS, or a media data URI.",
    );
  }
  if (
    mediaType &&
    !/^[a-z0-9!#$&^_.+-]+\/[a-z0-9!#$&^_.+-]+$/i.test(mediaType)
  ) {
    throw new Error("Tier media type must be a valid MIME type.");
  }

  return {
    name,
    description: optional(input.description),
    image,
    animation_url: animationUrl,
    mediaType,
    categoryName: optional(input.categoryName),
  };
}

/**
 * Route IPFS media through a caller-selected gateway base URL. Data URIs and
 * ordinary HTTP URLs pass through unchanged.
 */
export function tierMediaAssetUrl(
  value: unknown,
  ipfsGatewayBaseUrl = "https://ipfs.io/ipfs/",
): string | undefined {
  if (typeof value !== "string" || !value) return undefined;
  if (value.startsWith("data:")) return value;
  const trimmed = value.trim();
  const path =
    ipfsAssetPath(trimmed) ??
    (isIpfsCid(trimmed.split("/")[0]) ? trimmed : null);
  if (!path) return value;
  return `${ipfsGatewayBaseUrl.replace(/\/?$/, "/")}${path}`;
}

function svgDataUriMarkup(uri: string): string | null {
  const match = /^data:image\/svg\+xml([^,]*),([\s\S]*)$/.exec(uri);
  if (!match) return null;
  try {
    return match[1].split(";").includes("base64")
      ? decodeBase64Utf8(match[2])
      : decodeURIComponent(match[2]);
  } catch {
    return null;
  }
}

/**
 * Return a browser-renderable tier image URL. SVG data URIs that only wrap an
 * external `<image href>` are unwrapped because browsers block that nested
 * network request when the SVG itself is used as an `<img>` source.
 */
export function tierMediaImageUrl(
  image: unknown,
  ipfsGatewayBaseUrl?: string,
): string | undefined {
  if (typeof image !== "string" || !image) return undefined;
  const markup = svgDataUriMarkup(image);
  if (markup) {
    const href = /<image[^>]+href=["']([^"']+)["']/.exec(markup)?.[1];
    if (href && !href.startsWith("data:")) {
      return tierMediaAssetUrl(href, ipfsGatewayBaseUrl);
    }
    return image;
  }
  return tierMediaAssetUrl(image, ipfsGatewayBaseUrl);
}

/** Pick and resolve all tier metadata fields in one pass. */
export function tierDisplayMetadata(
  json: Record<string, unknown>,
  ipfsGatewayBaseUrl?: string,
): TierMetadata {
  const metadata = pickTierMetadata(json);
  return {
    ...metadata,
    image: tierMediaImageUrl(metadata.image, ipfsGatewayBaseUrl),
    animationUrl: tierMediaAssetUrl(metadata.animationUrl, ipfsGatewayBaseUrl),
  };
}

/** Stable first-seen category ids, with blank categories assigned to 0. */
export function buildTierCategoryPlan(
  tiers: ReadonlyArray<{ id: string; categoryName?: string }>,
): {
  categoryByTierId: Record<string, number>;
  storeCategories: Record<string, string>;
} {
  const categoryIds = new Map<string, number>();
  const categoryByTierId: Record<string, number> = {};
  const storeCategories: Record<string, string> = {};

  for (const tier of tiers) {
    const name = tier.categoryName?.trim() || "";
    if (!name) {
      categoryByTierId[tier.id] = 0;
      continue;
    }
    let category = categoryIds.get(name);
    if (category === undefined) {
      category = categoryIds.size + 1;
      categoryIds.set(name, category);
      storeCategories[String(category)] = name;
    }
    categoryByTierId[tier.id] = category;
  }

  return { categoryByTierId, storeCategories };
}

/**
 * A tier's effective (discounted) price, matching the on-chain formula in
 * JB721TiersHookStore: `price - mulDiv(price, discountPercent, 200)` with
 * integer-floor division.
 *
 * @param price The tier's full (undiscounted) price.
 * @param discountPercent The tier's discount, out of 200 (`DISCOUNT_DENOMINATOR`).
 */
export function effectiveTierPrice(
  price: bigint,
  discountPercent: number | bigint,
): bigint {
  let discount = BigInt(discountPercent);
  if (discount <= 0n) return price;
  if (discount > DISCOUNT_DENOMINATOR) discount = DISCOUNT_DENOMINATOR;
  return price - (price * discount) / DISCOUNT_DENOMINATOR;
}

/**
 * A single 721 tier a project sells.
 */
export interface Project721Tier {
  id: number;
  /** Full (undiscounted) price in the shop's pricing terms. */
  price: bigint;
  remainingSupply: number;
  initialSupply: number;
  votingUnits: bigint;
  reserveFrequency: number;
  category: number;
  /** Out of 200 — see {@link DISCOUNT_DENOMINATOR}. */
  discountPercent: number;
  encodedIpfsUri: Hex;
  /** tokenUriResolver output (data URI), or "" if the hook has no resolver. */
  resolvedUri: string;
}

/**
 * A project's resolved 721 tiers hook ("shop"): the hook, its store, the
 * metadata id target for pay/cash-out metadata, the pricing context, and tiers.
 */
export interface Project721Shop {
  /** The project's 721 tiers hook (the ruleset data hook / revnet hook). */
  hook: Address;
  /** The hook's tiers store. */
  store: Address;
  /**
   * The hook's `METADATA_ID_TARGET` (shared implementation address). Pass this
   * to {@link build721PayMetadata} / {@link build721CashOutMetadata}, never the
   * `hook` address.
   */
  metadataIdTarget: Address;
  /** The hook's pricing context: `currency` id and `decimals`. */
  pricing: { currency: number; decimals: number };
  tiers: Project721Tier[];
  /**
   * The current ruleset (with decoded metadata) when hook resolution had to
   * read it — every non-revnet project. `null` for revnets, whose hook comes
   * from `REVOwner` without a ruleset read. Reuse it instead of calling
   * `getCurrentRuleset` again.
   */
  ruleset: JBRulesetWithMetadata | null;
}

/**
 * Read a JB721 hook's `METADATA_ID_TARGET` — the shared *implementation* address
 * that pay/cash-out metadata ids must key off (a delegatecall clone reports the
 * implementation, not itself). Falls back to `hook` ONLY when the contract
 * itself answered that it has no such getter (a revert or empty return — an
 * older, non-clone hook). Transport/RPC failures are rethrown: treating them as
 * "old hook" would key pay metadata off the clone address, which the hook
 * silently ignores — the payer pays and receives no NFT.
 *
 * @param client A viem public client on the given chain.
 * @param args.hook The project's 721 tiers hook (clone) address.
 */
export async function get721MetadataIdTarget(
  client: PublicClient,
  { hook }: { chainId: JBChainId; hook: Address },
): Promise<Address> {
  return client
    .readContract({
      address: hook,
      abi: jb721TiersHookAbi,
      functionName: "METADATA_ID_TARGET",
    })
    .catch((error: unknown) => {
      if (isMissingContractFunctionError(error)) return hook;
      throw error;
    });
}

/**
 * Resolve a project's 721 tiers hook, its store, metadata id target, pricing
 * context, and tiers in one call.
 *
 * Hook resolution mirrors the app patterns: revnets read
 * `REVOwner.tiered721HookOf`; custom projects read the current ruleset's pay
 * data hook — either the omnichain deployer (the real hook lives in
 * `JBOmnichainDeployer.tiered721HookOf(projectId, rulesetId)`) or the 721 hook
 * itself, verified by probing `STORE()` (a proven revert or empty return means
 * it is not a 721 hook, so the project has no shop).
 *
 * Returns `null` only when the project authoritatively has no 721 shop. RPC and
 * transport failures throw — on authoritative reads and on the `STORE()` probe
 * alike — so a transient error surfaces as an error rather than a false
 * "no shop".
 *
 * @param client A viem public client on the given chain.
 * @param args.projectId The project (or revnet) id.
 * @param args.isRevnet Whether the project is a revnet (changes hook resolution).
 * @param args.tierLimit Max tiers to read from `tiersOf`. Defaults to 100.
 * @param args.categories Tier categories to filter by (empty = all). Defaults to `[]`.
 * @param args.includeResolvedUri Ask the store to run the hook's token URI
 * resolver for every tier (`tiersOf`'s `includeResolvedUri`). Defaults to
 * `false`: resolver output (often inline SVG data URIs) is packed into one
 * eth_call return, and over a large shop the upstream RPC rejects it. Turn it
 * on only for small reads that need `resolvedUri` without an indexer.
 */
export async function getProject721Shop(
  client: PublicClient,
  {
    chainId,
    projectId,
    isRevnet,
    tierLimit = 100,
    categories = [],
    includeResolvedUri = false,
  }: {
    chainId: JBChainId;
    projectId: bigint;
    isRevnet: boolean;
    tierLimit?: number;
    categories?: bigint[];
    includeResolvedUri?: boolean;
  },
): Promise<Project721Shop | null> {
  // 1. Resolve the 721 hook.
  let hook: Address | null = null;
  // A non-authoritative candidate is the ruleset data hook, which might be some
  // other kind of hook; the STORE() probe below decides.
  let authoritative = true;
  let currentRuleset: JBRulesetWithMetadata | null = null;

  if (isRevnet) {
    const revnetHook = await getRevnetTiered721Hook(client, {
      chainId,
      revnetId: projectId,
    });
    hook = revnetHook !== zeroAddress ? revnetHook : null;
  } else {
    currentRuleset = await getCurrentRuleset(client, { chainId, projectId });
    const { ruleset, metadata } = currentRuleset;
    const dataHook = metadata.dataHook as Address;
    if (metadata.useDataHookForPay && dataHook && dataHook !== zeroAddress) {
      const omni = jbContractAddress["6"][
        JBOmnichainDeployerContracts.JBOmnichainDeployer
      ]?.[chainId] as Address | undefined;
      if (omni && dataHook.toLowerCase() === omni.toLowerCase()) {
        // Omnichain project: the real 721 hook lives in the deployer's
        // per-ruleset mapping.
        const [omniHook] = await client.readContract({
          address: omni,
          abi: jbOmnichainDeployerAbi,
          functionName: "tiered721HookOf",
          args: [projectId, BigInt(ruleset.id)],
        });
        hook = omniHook !== zeroAddress ? omniHook : null;
      } else {
        // Single-chain custom project: the data hook may be the 721 hook itself.
        hook = dataHook;
        authoritative = false;
      }
    }
  }
  if (!hook) return null;

  // 2. The hook's store. For a non-authoritative candidate a PROVEN revert (or
  // empty return) means "not a 721 hook" — no shop. Transport failures prove
  // nothing and are rethrown; swallowing them would render "no shop" for a
  // project that has one. For an authoritative hook, let every failure throw.
  const readStore = () =>
    client.readContract({
      address: hook!,
      abi: jb721TiersHookAbi,
      functionName: "STORE",
    });
  const store = authoritative
    ? await readStore()
    : await readStore().catch((error: unknown) => {
        if (isMissingContractFunctionError(error)) return null;
        throw error;
      });
  if (!store) return null;

  // 3. Metadata id target + pricing context. Pricing is meaningless without the
  // hook's exact currency + decimals, so a failure here is an error, not a
  // fallback.
  const [metadataIdTarget, pricingRaw] = await Promise.all([
    get721MetadataIdTarget(client, { chainId, hook }),
    client.readContract({
      address: hook,
      abi: jb721TiersHookAbi,
      functionName: "pricingContext",
    }),
  ]);

  // 4. The tiers. Resolver URIs are opt-in (see `includeResolvedUri`).
  const raw = await client.readContract({
    address: store,
    abi: jb721TiersHookStoreAbi,
    functionName: "tiersOf",
    args: [hook, categories, includeResolvedUri, 0n, BigInt(tierLimit)],
  });

  const tiers: Project721Tier[] = raw
    .filter((tier) => tier.initialSupply > 0)
    .map((tier) => ({
      id: tier.id,
      price: tier.price,
      remainingSupply: tier.remainingSupply,
      initialSupply: tier.initialSupply,
      votingUnits: tier.votingUnits,
      reserveFrequency: tier.reserveFrequency,
      category: tier.category,
      discountPercent: tier.discountPercent,
      encodedIpfsUri: tier.encodedIpfsUri,
      resolvedUri: tier.resolvedUri ?? "",
    }));

  return {
    hook,
    store,
    metadataIdTarget,
    pricing: {
      currency: Number(pricingRaw[0]),
      decimals: Number(pricingRaw[1]),
    },
    tiers,
    ruleset: currentRuleset,
  };
}

