describe("721 ruleset metadata", () => {
  test("sets and decodes both 721 hook flags", () => {
    const metadata = build721RulesetMetadata({
      pauseTransfers: true,
      pauseMintPendingReserves: true,
    });

    expect(metadata).toBe(
      JB721_RULESET_METADATA_PAUSE_TRANSFERS |
        JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
    );
    expect(decode721RulesetMetadata(metadata)).toEqual({
      pauseTransfers: true,
      pauseMintPendingReserves: true,
    });
  });

  test("preserves unrelated metadata bits when setting or clearing flags", () => {
    const unrelatedBits = (1 << 2) | (1 << 13);
    expect(
      build721RulesetMetadata({
        metadata:
          unrelatedBits | JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
        pauseTransfers: true,
      }),
    ).toBe(
      unrelatedBits |
        JB721_RULESET_METADATA_PAUSE_TRANSFERS |
        JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
    );
    expect(
      build721RulesetMetadata({
        metadata: unrelatedBits | JB721_RULESET_METADATA_PAUSE_TRANSFERS,
        pauseTransfers: false,
      }),
    ).toBe(unrelatedBits);
  });

  test("preserves omitted flags and updates reserve minting independently", () => {
    expect(
      build721RulesetMetadata({
        metadata: JB721_RULESET_METADATA_PAUSE_TRANSFERS,
        pauseMintPendingReserves: true,
      }),
    ).toBe(
      JB721_RULESET_METADATA_PAUSE_TRANSFERS |
        JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
    );
    expect(
      build721RulesetMetadata({
        metadata:
          JB721_RULESET_METADATA_PAUSE_TRANSFERS |
          JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
        pauseMintPendingReserves: false,
      }),
    ).toBe(JB721_RULESET_METADATA_PAUSE_TRANSFERS);
  });

  test.each([-1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, 0x4000])(
    "rejects invalid app metadata %s",
    (metadata) => {
      expect(() => build721RulesetMetadata({ metadata })).toThrow(/integer/);
      expect(() => decode721RulesetMetadata(metadata)).toThrow(/integer/);
    },
  );

  test("accepts the highest 14-bit metadata value", () => {
    expect(
      build721RulesetMetadata({ metadata: JB_RULESET_METADATA_APP_BITS_MAX }),
    ).toBe(JB_RULESET_METADATA_APP_BITS_MAX);
  });
});

describe("tier metadata", () => {
  test("parses encoded and base64 JSON data URIs", () => {
    expect(
      parseTierMetadataJson(
        `data:application/json,${encodeURIComponent(JSON.stringify({ name: "Café" }))}`,
      ),
    ).toEqual({ name: "Café" });
    expect(
      parseTierMetadataJson(
        "data:application/json;base64,eyJwcm9kdWN0TmFtZSI6IkJhbm55In0=",
      ),
    ).toEqual({ productName: "Banny" });
    expect(parseTierMetadataJson("https://example.com/tier.json")).toBeNull();
    expect(parseTierMetadataJson("data:application/json,%7Bbad")).toBeNull();
  });

  test("normalizes legacy metadata aliases", () => {
    expect(
      pickTierMetadata({
        productName: "Legacy name",
        name: "Current name",
        productDescription: "Legacy description",
        imageUri: `ipfs://${CID}/image.png`,
        animation_url: "https://example.com/animation.mp4",
        mimeType: "video/mp4",
        categoryName: "Wearables",
      }),
    ).toEqual({
      name: "Legacy name",
      description: "Legacy description",
      image: `ipfs://${CID}/image.png`,
      animationUrl: "https://example.com/animation.mp4",
      mediaType: "video/mp4",
      categoryName: "Wearables",
    });
  });

  test("builds a canonical payload and validates media", () => {
    expect(
      buildTierMetadata({
        name: "  Poster  ",
        description: " ",
        image: `ipfs://${CID}/poster.png`,
        animationUrl: "https://example.com/poster.mp4",
        mediaType: "video/mp4",
      }),
    ).toEqual({
      name: "Poster",
      description: undefined,
      image: `ipfs://${CID}/poster.png`,
      animation_url: "https://example.com/poster.mp4",
      mediaType: "video/mp4",
      categoryName: undefined,
    });
    expect(isSafeTierMediaUri(`${CID}/poster.png`)).toBe(true);
    expect(() => buildTierMetadata({ name: " " })).toThrow(/name/);
    expect(() =>
      buildTierMetadata({ name: "Poster", image: "javascript:alert(1)" }),
    ).toThrow(/images/);
    expect(() =>
      buildTierMetadata({ name: "Poster", mediaType: "not mime" }),
    ).toThrow(/MIME/);
  });

  test("routes IPFS media and unwraps external images in SVG data URIs", () => {
    expect(
      tierDisplayMetadata(
        {
          image: `ipfs://${CID}/image.png`,
          animation_url: `${CID}/animation.mp4`,
        },
        "/api/ipfs",
      ),
    ).toMatchObject({
      image: `/api/ipfs/${CID}/image.png`,
      animationUrl: `/api/ipfs/${CID}/animation.mp4`,
    });
    const svg = `<svg><image xlink:href="ipfs://${CID}/wrapped.png" /></svg>`;
    expect(
      tierMediaImageUrl(
        `data:image/svg+xml,${encodeURIComponent(svg)}`,
        "/api/ipfs",
      ),
    ).toBe(`/api/ipfs/${CID}/wrapped.png`);
  });

  test("assigns stable first-seen category ids", () => {
    expect(
      buildTierCategoryPlan([
        { id: "one", categoryName: " Posters " },
        { id: "two", categoryName: "" },
        { id: "three", categoryName: "Posters" },
        { id: "four", categoryName: "Music" },
      ]),
    ).toEqual({
      categoryByTierId: { one: 1, two: 0, three: 1, four: 2 },
      storeCategories: { "1": "Posters", "2": "Music" },
    });
    expect(TIER_UNLIMITED_SUPPLY).toBe(999_999_999);
  });
});

describe("effectiveTierPrice", () => {
  test("floors like on-chain mulDiv(price, discountPercent, 200)", () => {
    // 100 - floor(100 * 25 / 200) = 100 - 12 = 88.
    expect(effectiveTierPrice(100n, 25)).toEqual(88n);
  });

  test("no discount returns the full price", () => {
    expect(effectiveTierPrice(1000n, 0)).toEqual(1000n);
  });

  test("full discount (denominator) is free", () => {
    expect(effectiveTierPrice(1000n, Number(DISCOUNT_DENOMINATOR))).toEqual(0n);
  });

  test("clamps discounts above the denominator to free", () => {
    expect(effectiveTierPrice(1000n, 500)).toEqual(0n);
  });
});

describe("get721MetadataIdTarget", () => {
  test("returns METADATA_ID_TARGET (the implementation, not the clone)", async () => {
    const client = {
      readContract: async () => impl,
    } as unknown as PublicClient;

    expect(await get721MetadataIdTarget(client, { chainId, hook })).toEqual(
      impl,
    );
  });

  test("falls back to the hook address when the contract reverts the getter", async () => {
    const revert = new ContractFunctionExecutionError(
      new ContractFunctionRevertedError({
        abi: jb721TiersHookAbi,
        functionName: "METADATA_ID_TARGET",
      }),
      {
        abi: jb721TiersHookAbi,
        args: [],
        contractAddress: hook,
        functionName: "METADATA_ID_TARGET",
      },
    );
    const client = {
      readContract: async () => {
        throw revert;
      },
    } as unknown as PublicClient;

    expect(await get721MetadataIdTarget(client, { chainId, hook })).toEqual(
      hook,
    );
  });

  test("falls back to the hook address when the getter returns no data (older hook)", async () => {
    const zeroData = new ContractFunctionExecutionError(
      new ContractFunctionZeroDataError({
        functionName: "METADATA_ID_TARGET",
      }),
      {
        abi: jb721TiersHookAbi,
        args: [],
        contractAddress: hook,
        functionName: "METADATA_ID_TARGET",
      },
    );
    const client = {
      readContract: async () => {
        throw zeroData;
      },
    } as unknown as PublicClient;

    expect(await get721MetadataIdTarget(client, { chainId, hook })).toEqual(
      hook,
    );
  });

  test("rethrows transport errors instead of returning the clone address", async () => {
    // A transient RPC failure proves nothing about the hook. Falling back to
    // the clone address here would build pay metadata the hook silently
    // ignores: the user pays and receives no NFT.
    const transport = new ContractFunctionExecutionError(
      new HttpRequestError({
        url: "https://rpc.example",
        details: "fetch failed",
      }),
      {
        abi: jb721TiersHookAbi,
        args: [],
        contractAddress: hook,
        functionName: "METADATA_ID_TARGET",
      },
    );
    const client = {
      readContract: async () => {
        throw transport;
      },
    } as unknown as PublicClient;

    await expect(
      get721MetadataIdTarget(client, { chainId, hook }),
    ).rejects.toBe(transport);
  });

  test("rethrows non-viem errors", async () => {
    const failure = new Error("socket hang up");
    const client = {
      readContract: async () => {
        throw failure;
      },
    } as unknown as PublicClient;

    await expect(
      get721MetadataIdTarget(client, { chainId, hook }),
    ).rejects.toBe(failure);
  });
});

describe("getProject721Shop", () => {
  test("returns null when a revnet has no 721 hook", async () => {
    const client = {
      // getRevnetTiered721Hook -> zero address.
      readContract: async () => zeroAddress,
    } as unknown as PublicClient;

    expect(
      await getProject721Shop(client, {
        chainId,
        projectId: 1n,
        isRevnet: true,
      }),
    ).toBeNull();
  });

  test("resolves a revnet shop: hook, store, target, pricing, tiers", async () => {
    const client = {
      readContract: async ({
        address,
        functionName,
      }: {
        address: string;
        functionName: string;
      }) => {
        if (functionName === "tiered721HookOf") return hook; // REVOwner
        if (address === hook && functionName === "STORE") return store;
        if (functionName === "METADATA_ID_TARGET") return impl;
        if (functionName === "pricingContext") return [61166n, 18n];
        if (functionName === "tiersOf") {
          return [
            {
              id: 1,
              price: 1000n,
              remainingSupply: 5,
              initialSupply: 10,
              votingUnits: 0n,
              reserveFrequency: 0,
              reserveBeneficiary: zeroAddress,
              encodedIpfsUri: `0x${"11".repeat(32)}`,
              category: 0,
              discountPercent: 0,
              flags: {},
              splitPercent: 0,
              resolvedUri: "",
            },
            // Filtered out: initialSupply 0.
            {
              id: 2,
              price: 0n,
              remainingSupply: 0,
              initialSupply: 0,
              votingUnits: 0n,
              reserveFrequency: 0,
              reserveBeneficiary: zeroAddress,
              encodedIpfsUri: `0x${"00".repeat(32)}`,
              category: 0,
              discountPercent: 0,
              flags: {},
              splitPercent: 0,
              resolvedUri: "",
            },
          ];
        }
        throw new Error(`unexpected read ${functionName}`);
      },
    } as unknown as PublicClient;

    const shop = await getProject721Shop(client, {
      chainId,
      projectId: 1n,
      isRevnet: true,
    });

    expect(shop).not.toBeNull();
    expect(shop!.hook).toEqual(hook);
    expect(shop!.store).toEqual(store);
    expect(shop!.metadataIdTarget).toEqual(impl);
    expect(shop!.pricing).toEqual({ currency: 61166, decimals: 18 });
    expect(shop!.tiers).toHaveLength(1);
    expect(shop!.tiers[0]).toMatchObject({ id: 1, price: 1000n });
  });

  test("asks tiersOf for resolved URIs only when opted in, and returns no ruleset for a revnet", async () => {
    const seen: boolean[] = [];
    const client = {
      readContract: async ({
        address,
        functionName,
        args,
      }: {
        address: string;
        functionName: string;
        args?: readonly unknown[];
      }) => {
        if (functionName === "tiered721HookOf") return hook;
        if (address === hook && functionName === "STORE") return store;
        if (functionName === "METADATA_ID_TARGET") return impl;
        if (functionName === "pricingContext") return [61166n, 18n];
        if (functionName === "tiersOf") {
          seen.push(args![2] as boolean);
          return [];
        }
        throw new Error(`unexpected read ${functionName}`);
      },
    } as unknown as PublicClient;

    const byDefault = await getProject721Shop(client, {
      chainId,
      projectId: 1n,
      isRevnet: true,
    });
    await getProject721Shop(client, {
      chainId,
      projectId: 1n,
      isRevnet: true,
      includeResolvedUri: true,
    });

    expect(seen).toEqual([false, true]);
    expect(byDefault!.ruleset).toBeNull();
  });

  test("returns the ruleset it read for a custom project", async () => {
    const ruleset = {
      id: 7,
      cycleNumber: 1,
      basedOnId: 0,
      start: 0,
      duration: 0,
      weight: 0n,
      weightCutPercent: 0,
      approvalHook: zeroAddress,
      metadata: 0n,
    };
    const metadata = {
      dataHook: hook,
      useDataHookForPay: true,
      useDataHookForCashOut: false,
    };
    let rulesetReads = 0;
    const client = {
      readContract: async ({
        address,
        functionName,
      }: {
        address: string;
        functionName: string;
      }) => {
        if (functionName === "currentRulesetOf") {
          rulesetReads += 1;
          return [ruleset, metadata];
        }
        if (address === hook && functionName === "STORE") return store;
        if (functionName === "METADATA_ID_TARGET") return impl;
        if (functionName === "pricingContext") return [61166n, 18n];
        if (functionName === "tiersOf") return [];
        throw new Error(`unexpected read ${functionName}`);
      },
    } as unknown as PublicClient;

    const shop = await getProject721Shop(client, {
      chainId,
      projectId: 1n,
      isRevnet: false,
    });

    expect(rulesetReads).toBe(1);
    expect(shop!.ruleset).toEqual({ ruleset, metadata });
  });

  const tiersOfOne = () => [
    {
      id: 1,
      price: 1000n,
      remainingSupply: 5,
      initialSupply: 10,
      votingUnits: 0n,
      reserveFrequency: 0,
      reserveBeneficiary: zeroAddress,
      encodedIpfsUri: `0x${"11".repeat(32)}`,
      category: 0,
      discountPercent: 0,
      flags: {},
      splitPercent: 0,
      resolvedUri: "",
    },
  ];

  // The custom-project omnichain deployer address on chain 11155111, read from
  // the SDK's own address book so the branch matches real wiring.
  const omniDeployer = (
    jbContractAddress["6"][
      JBOmnichainDeployerContracts.JBOmnichainDeployer
    ] as Record<string, Address>
  )["11155111"];

  test("custom project: resolves the real hook via the omnichain deployer", async () => {
    const client = {
      readContract: async ({
        address,
        functionName,
      }: {
        address: string;
        functionName: string;
      }) => {
        // currentRulesetOf -> [ruleset, metadata] with the deployer as data hook.
        if (functionName === "currentRulesetOf") {
          return [
            { id: 7 },
            { useDataHookForPay: true, dataHook: omniDeployer },
          ];
        }
        // The deployer maps to the real clone hook.
        if (
          address.toLowerCase() === omniDeployer.toLowerCase() &&
          functionName === "tiered721HookOf"
        ) {
          return [hook, false];
        }
        if (address === hook && functionName === "STORE") return store;
        if (functionName === "METADATA_ID_TARGET") return impl;
        if (functionName === "pricingContext") return [1n, 18n];
        if (functionName === "tiersOf") return tiersOfOne();
        throw new Error(`unexpected read ${functionName} @ ${address}`);
      },
    } as unknown as PublicClient;

    const shop = await getProject721Shop(client, {
      chainId: 11155111,
      projectId: 9n,
      isRevnet: false,
    });
    expect(shop!.hook).toEqual(hook);
    expect(shop!.metadataIdTarget).toEqual(impl);
  });

  test("custom project: data hook that is not a 721 hook is no shop", async () => {
    const notAHook = "0x4444444444444444444444444444444444444444" as const;
    // A PROVEN revert — the contract answered that it has no `STORE()`.
    const revert = new ContractFunctionExecutionError(
      new ContractFunctionRevertedError({
        abi: jb721TiersHookAbi,
        functionName: "STORE",
      }),
      {
        abi: jb721TiersHookAbi,
        args: [],
        contractAddress: notAHook,
        functionName: "STORE",
      },
    );
    const client = {
      readContract: async ({ functionName }: { functionName: string }) => {
        if (functionName === "currentRulesetOf") {
          return [{ id: 7 }, { useDataHookForPay: true, dataHook: notAHook }];
        }
        if (functionName === "STORE") throw revert;
        throw new Error(`unexpected read ${functionName}`);
      },
    } as unknown as PublicClient;

    expect(
      await getProject721Shop(client, {
        chainId: 11155111,
        projectId: 9n,
        isRevnet: false,
      }),
    ).toBeNull();
  });

  test("custom project: a transport failure on the STORE probe throws", async () => {
    // Not a revert: the chain never answered. Rendering "no shop" here hides a
    // shop that exists.
    const notAHook = "0x4444444444444444444444444444444444444444" as const;
    const client = {
      readContract: async ({ functionName }: { functionName: string }) => {
        if (functionName === "currentRulesetOf") {
          return [{ id: 7 }, { useDataHookForPay: true, dataHook: notAHook }];
        }
        if (functionName === "STORE") throw new Error("fetch failed");
        throw new Error(`unexpected read ${functionName}`);
      },
    } as unknown as PublicClient;

    await expect(
      getProject721Shop(client, {
        chainId: 11155111,
        projectId: 9n,
        isRevnet: false,
      }),
    ).rejects.toThrow("fetch failed");
  });

  test("custom project: no pay data hook is no shop", async () => {
    const client = {
      readContract: async ({ functionName }: { functionName: string }) => {
        if (functionName === "currentRulesetOf") {
          return [
            { id: 7 },
            { useDataHookForPay: false, dataHook: zeroAddress },
          ];
        }
        throw new Error(`unexpected read ${functionName}`);
      },
    } as unknown as PublicClient;

    expect(
      await getProject721Shop(client, {
        chainId: 11155111,
        projectId: 9n,
        isRevnet: false,
      }),
    ).toBeNull();
  });
});

import { Address, Hex, PublicClient, encodeAbiParameters } from "viem";
import { DEFAULT_ALLOW_OVERSPENDING, NATIVE_TOKEN } from "../constants.js";
import { jbMultiTerminalAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { createHookMetadata, hookMetadataId } from "../utils/hook.js";

/**
 * A prepared `pay` transaction request, accepted as-is by viem's
 * `walletClient.writeContract` and wagmi's `writeContract`.
 */
export interface V6PayTxRequest {
  chainId: JBChainId;
  address: Address;
  abi: typeof jbMultiTerminalAbi;
  functionName: "pay";
  args: readonly [bigint, Address, bigint, Address, bigint, string, Hex];
  value: bigint;
}

/**
 * Build a `pay(projectId, token, amount, beneficiary, minReturnedTokens, memo,
 * metadata)` transaction request for a v6 terminal.
 *
 * When `token` is the native token, `value` is set to `amount` (the terminal reads the
 * paid amount from `msg.value`); for ERC-20 payments `value` is 0 and the terminal must
 * be approved to pull `amount` beforehand.
 *
 * @param args.chainId The chain to pay on.
 * @param args.terminal The terminal to pay (resolve with `resolvePaymentTerminal`).
 * @param args.projectId The project's id.
 * @param args.token The token being paid.
 * @param args.amount The amount being paid, as a fixed point number with the token's
 * decimals.
 * @param args.beneficiary The address that receives the minted project tokens.
 * @param args.minReturnedTokens The minimum project token count the beneficiary must
 * receive, else the transaction reverts. Defaults to 0.
 * @param args.memo A memo included in the Pay event. Defaults to "".
 * @param args.metadata Hook metadata (e.g. from {@link build721PayMetadata}). Defaults
 * to "0x".
 * @returns The transaction request.
 */
export function buildPayTx({
  chainId,
  terminal,
  projectId,
  token,
  amount,
  beneficiary,
  minReturnedTokens = 0n,
  memo = "",
  metadata = "0x",
}: {
  chainId: JBChainId;
  terminal: Address;
  projectId: bigint;
  token: Address;
  amount: bigint;
  beneficiary: Address;
  minReturnedTokens?: bigint;
  memo?: string;
  metadata?: Hex;
}): V6PayTxRequest {
  const isNative = token.toLowerCase() === NATIVE_TOKEN.toLowerCase();

  return {
    chainId,
    address: terminal,
    abi: jbMultiTerminalAbi,
    functionName: "pay",
    args: [
      projectId,
      token,
      amount,
      beneficiary,
      minReturnedTokens,
      memo,
      metadata,
    ],
    value: isNative ? amount : 0n,
  };
}

/**
 * The result of previewing a payment.
 */
export interface PayPreview {
  /**
   * The project token count the beneficiary would receive.
   */
  beneficiaryTokenCount: bigint;
  /**
   * The project token count that would be reserved for the project's reserved splits.
   */
  reservedTokenCount: bigint;
}

export type PaySettlement = "issuance" | "swap";

export interface PayRouteCandidate extends PayPreview {
  kind: "pay";
  settlement: PaySettlement;
}

export interface DirectSwapRouteCandidate extends PayPreview {
  kind: "direct-swap";
  settlement: "swap";
  quotedTokenCount: bigint;
}

export type BestPayRoute = PayRouteCandidate | DirectSwapRouteCandidate;

/**
 * Pick the executable route which guarantees the beneficiary the most tokens.
 *
 * A direct pool swap bypasses the terminal, so its reserved token count is always
 * zero. Its quote is reduced by `slippageBps` before comparison: a route is only
 * selected when its on-chain minimum beats the terminal preview, not merely when
 * its optimistic quote does.
 */
export function chooseBestPayRoute({
  pay,
  paySettlement,
  directSwapQuote,
  slippageBps = 100n,
}: {
  pay: PayPreview;
  paySettlement: PaySettlement;
  directSwapQuote?: bigint | null;
  slippageBps?: bigint;
}): BestPayRoute {
  if (slippageBps < 0n || slippageBps >= 10_000n) {
    throw new Error("slippageBps must be between 0 and 9,999.");
  }

  const payRoute: PayRouteCandidate = {
    kind: "pay",
    settlement: paySettlement,
    ...pay,
  };
  if (!directSwapQuote || directSwapQuote <= 0n) return payRoute;

  const minimum = (directSwapQuote * (10_000n - slippageBps)) / 10_000n;
  if (minimum <= pay.beneficiaryTokenCount) return payRoute;

  return {
    kind: "direct-swap",
    settlement: "swap",
    quotedTokenCount: directSwapQuote,
    beneficiaryTokenCount: minimum,
    reservedTokenCount: 0n,
  };
}

/**
 * Preview the project tokens minted by a payment, via the terminal's
 * `previewPayFor(projectId, token, amount, beneficiary, metadata)`.
 *
 * The terminal's `previewPayFor` is used (rather than
 * `JBTerminalStore.previewPayFrom`) because it takes exactly the data a `pay` caller
 * already has — the store variant additionally requires a full `JBTokenAmount` tuple
 * (token, decimals, currency, value), forcing an extra accounting-context lookup.
 *
 * @param client A viem public client on the given chain.
 * @param args.chainId The chain to preview on.
 * @param args.terminal The terminal that would be paid.
 * @param args.projectId The project's id.
 * @param args.token The token being paid.
 * @param args.amount The amount being paid, as a fixed point number with the token's
 * decimals.
 * @param args.beneficiary The address that would receive the minted project tokens.
 * @param args.metadata Hook metadata. Defaults to "0x".
 * @returns The previewed token counts.
 */
export async function previewPay(
  client: PublicClient,
  {
    terminal,
    projectId,
    token,
    amount,
    beneficiary,
    metadata = "0x",
  }: {
    chainId: JBChainId;
    terminal: Address;
    projectId: bigint;
    token: Address;
    amount: bigint;
    beneficiary: Address;
    metadata?: Hex;
  },
): Promise<PayPreview> {
  const [, beneficiaryTokenCount, reservedTokenCount] =
    await client.readContract({
      address: terminal,
      abi: jbMultiTerminalAbi,
      functionName: "previewPayFor",
      args: [projectId, token, amount, beneficiary, metadata],
    });

  return { beneficiaryTokenCount, reservedTokenCount };
}

/**
 * Build pay metadata instructing a project's JB721 tiers hook to mint specific tiers.
 *
 * The tier payload is `abi.encode(bool allowOverspending, uint16[] tierIdsToMint)`,
 * keyed by the hook's metadata id (`bytes4(bytes20(metadataIdTarget) ^
 * bytes20(keccak256("pay")))`) and packed into the JBMetadataResolver
 * word-offset-table format.
 *
 * @param args.metadataIdTarget The hook's `METADATA_ID_TARGET` — the shared
 * *implementation* address, NOT the project's clone hook address (see
 * {@link get721MetadataIdTarget}). Passing the clone address makes the hook ignore
 * the tiers and the payment mints ZERO NFTs (it succeeds, minting only tokens).
 * @param args.hookAddress Deprecated alias for `metadataIdTarget`. Only correct
 * when it already holds `METADATA_ID_TARGET`; prefer `metadataIdTarget`.
 * @param args.tierIdsToMint The tier ids to mint, one entry per NFT.
 * @param args.allowOverspending Whether payment beyond the tiers' total price is
 * allowed (excess mints no NFT). Defaults to true. Note the hook still gates this
 * on its store's `preventOverspending` flag.
 * @returns The metadata to pass as `pay`'s `metadata` argument.
 */
export function build721PayMetadata({
  metadataIdTarget,
  hookAddress,
  tierIdsToMint,
  allowOverspending = DEFAULT_ALLOW_OVERSPENDING,
}: {
  metadataIdTarget?: Address;
  /** @deprecated Use `metadataIdTarget`. */
  hookAddress?: Address;
  tierIdsToMint: bigint[];
  allowOverspending?: boolean;
}): Hex {
  const target = metadataIdTarget ?? hookAddress;
  if (!target) {
    throw new Error("build721PayMetadata requires metadataIdTarget");
  }

  const tierPayload = encodeAbiParameters(
    [{ type: "bool" }, { type: "uint16[]" }],
    [allowOverspending, tierIdsToMint.map(Number)],
  );

  return createHookMetadata(
    [hookMetadataId(target, "pay")],
    [tierPayload],
  ) as Hex;
}

/**
 * Encode the three-word pay quote required by buyback hook 1.4.0.
 * An explicit minimum is a settlement guarantee; zero uses the oracle floor,
 * whose underfill unwinds the swap and falls back to minting. Resolve the
 * project's actual hook before selecting this metadata target.
 */
export function buildBuybackPayMetadata({
  hook,
  amountToSwapWith,
  minimumSwapAmountOut,
  skipSplits = false,
}: {
  hook: Address;
  amountToSwapWith: bigint;
  minimumSwapAmountOut: bigint;
  skipSplits?: boolean;
}): Hex {
  return createHookMetadata(
    [hookMetadataId(hook, "pay")],
    [
      encodeAbiParameters(
        [{ type: "uint256" }, { type: "uint256" }, { type: "bool" }],
        [amountToSwapWith, minimumSwapAmountOut, skipSplits],
      ),
    ],
  );
}

import {
  PublicClient,
  decodeAbiParameters,
  encodeFunctionData,
  sliceHex,
} from "viem";
import { describe, expect, test } from "vitest";
import { NATIVE_TOKEN } from "../constants.js";
import { jbMultiTerminalAbi } from "../generated/juicebox.js";
import {
  build721PayMetadata,
  buildBuybackPayMetadata,
  buildPayTx,
  chooseBestPayRoute,
  previewPay,
} from "./pay.js";

const chainId = 11155111;
const terminal = "0x1111111111111111111111111111111111111111" as const;
const projectId = 3n;
const beneficiary = "0x2222222222222222222222222222222222222222" as const;
const usdc = "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48" as const;

describe("pay", () => {
  test("chooses a guaranteed-better direct swap and removes reserved splits", () => {
    const route = chooseBestPayRoute({
      pay: {
        beneficiaryTokenCount: 587_647n,
        reservedTokenCount: 391_765n,
      },
      paySettlement: "swap",
      directSwapQuote: 959_800n,
      slippageBps: 100n,
    });

    expect(route).toEqual({
      kind: "direct-swap",
      settlement: "swap",
      quotedTokenCount: 959_800n,
      beneficiaryTokenCount: 950_202n,
      reservedTokenCount: 0n,
    });
  });

  test("keeps terminal payment unless the direct swap minimum is better", () => {
    expect(
      chooseBestPayRoute({
        pay: {
          beneficiaryTokenCount: 950_000n,
          reservedTokenCount: 20_000n,
        },
        paySettlement: "issuance",
        directSwapQuote: 959_000n,
      }),
    ).toEqual({
      kind: "pay",
      settlement: "issuance",
      beneficiaryTokenCount: 950_000n,
      reservedTokenCount: 20_000n,
    });
  });

  test("buildPayTx sets value for native token payments", () => {
    const tx = buildPayTx({
      chainId,
      terminal,
      projectId,
      token: NATIVE_TOKEN,
      amount: 1000n,
      beneficiary,
    });

    expect(tx.chainId).toEqual(chainId);
    expect(tx.address).toEqual(terminal);
    expect(tx.functionName).toEqual("pay");
    expect(tx.value).toEqual(1000n);
    expect(tx.args).toEqual([
      projectId,
      NATIVE_TOKEN,
      1000n,
      beneficiary,
      0n,
      "",
      "0x",
    ]);
    expect(() => encodeFunctionData(tx)).not.toThrow();
  });

  test("buildPayTx sets no value for ERC-20 payments", () => {
    const tx = buildPayTx({
      chainId,
      terminal,
      projectId,
      token: usdc,
      amount: 1000n,
      beneficiary,
      minReturnedTokens: 7n,
      memo: "gm",
      metadata: "0x1234",
    });

    expect(tx.value).toEqual(0n);
    expect(tx.args).toEqual([
      projectId,
      usdc,
      1000n,
      beneficiary,
      7n,
      "gm",
      "0x1234",
    ]);
    expect(() => encodeFunctionData(tx)).not.toThrow();
  });

  test("previewPay calls the terminal's previewPayFor", async () => {
    const calls: any[] = [];
    const client = {
      async readContract(params: unknown) {
        calls.push(params);
        return [{}, 100n, 25n, []];
      },
    } as unknown as PublicClient;

    const preview = await previewPay(client, {
      chainId,
      terminal,
      projectId,
      token: NATIVE_TOKEN,
      amount: 1000n,
      beneficiary,
    });

    expect(preview).toEqual({
      beneficiaryTokenCount: 100n,
      reservedTokenCount: 25n,
    });
    expect(calls[0].address).toEqual(terminal);
    expect(calls[0].abi).toBe(jbMultiTerminalAbi);
    expect(calls[0].functionName).toEqual("previewPayFor");
    expect(calls[0].args).toEqual([
      projectId,
      NATIVE_TOKEN,
      1000n,
      beneficiary,
      "0x",
    ]);
  });

  test("build721PayMetadata packs the hook's metadata id and tier payload", () => {
    // With a hook address whose first 4 bytes are zero, the metadata id is the first
    // 4 bytes of keccak256("pay").
    const metadata = build721PayMetadata({
      hookAddress: "0x00000000000000000000000000000000DeaDBeef",
      tierIdsToMint: [1n, 2n],
    });

    // Word 0 is the protocol's reserved word.
    expect(sliceHex(metadata, 0, 32)).toEqual(`0x${"00".repeat(32)}`);
    // The lookup table: the hook's metadata id, then the payload's word offset (2).
    expect(sliceHex(metadata, 32, 36)).toEqual("0xadc75680");
    expect(sliceHex(metadata, 36, 37)).toEqual("0x02");
    // The payload starts at word 2 and decodes to (allowOverspending, tierIdsToMint).
    const payload = sliceHex(metadata, 64);
    const [allowOverspending, tierIds] = decodeAbiParameters(
      [{ type: "bool" }, { type: "uint16[]" }],
      payload,
    );
    expect(allowOverspending).toEqual(true);
    expect(tierIds).toEqual([1, 2]);
  });

  test("build721PayMetadata respects allowOverspending false", () => {
    const metadata = build721PayMetadata({
      hookAddress: "0x00000000000000000000000000000000DeaDBeef",
      tierIdsToMint: [5n],
      allowOverspending: false,
    });

    const [allowOverspending, tierIds] = decodeAbiParameters(
      [{ type: "bool" }, { type: "uint16[]" }],
      sliceHex(metadata, 64),
    );
    expect(allowOverspending).toEqual(false);
    expect(tierIds).toEqual([5]);
  });

  test("build721PayMetadata id XORs the hook address with keccak256('pay')", () => {
    const metadata = build721PayMetadata({
      hookAddress: "0x1111111111111111111111111111111111111111",
      tierIdsToMint: [1n],
    });

    // 0xadc75680 (first 4 bytes of keccak256("pay")) XOR 0x11111111.
    expect(sliceHex(metadata, 32, 36)).toEqual("0xbcd64791");
  });

  test("build721PayMetadata metadataIdTarget matches the hookAddress alias", () => {
    const target = "0x1111111111111111111111111111111111111111" as const;
    expect(
      build721PayMetadata({ metadataIdTarget: target, tierIdsToMint: [1n] }),
    ).toEqual(
      build721PayMetadata({ hookAddress: target, tierIdsToMint: [1n] }),
    );
  });

  test("build721PayMetadata throws when no target is given", () => {
    expect(() => build721PayMetadata({ tierIdsToMint: [1n] })).toThrow(
      /metadataIdTarget/,
    );
  });
});

describe("buyback pay quote", () => {
  test.each([false, true])(
    "encodes the required third word (skipSplits=%s)",
    (skipSplits) => {
      const metadata = buildBuybackPayMetadata({
        hook: terminal,
        amountToSwapWith: 100n,
        minimumSwapAmountOut: 99n,
        skipSplits,
      });
      expect(
        decodeAbiParameters(
          [{ type: "uint256" }, { type: "uint256" }, { type: "bool" }],
          sliceHex(metadata, 64),
        ),
      ).toEqual([100n, 99n, skipSplits]);
      expect(metadata.length).toBe(2 + 5 * 64);
    },
  );
  test("defaults to honoring reserved splits with an oracle-derived floor", () => {
    const metadata = buildBuybackPayMetadata({
      hook: terminal,
      amountToSwapWith: 100n,
      minimumSwapAmountOut: 0n,
    });
    expect(
      decodeAbiParameters(
        [{ type: "uint256" }, { type: "uint256" }, { type: "bool" }],
        sliceHex(metadata, 64),
      ),
    ).toEqual([100n, 0n, false]);
  });
});

import type { Address, Hex, PublicClient } from "viem";
import { NATIVE_TOKEN } from "../constants.js";
import type { JBChainId } from "../types.js";
import {
  UNISWAP_PERMIT2_ADDRESS,
  uniswapV4Deployment,
} from "./uniswapV4Deployments.js";

/** Canonical Permit2 deployment shared by supported EVM chains. */
export const PERMIT2_ADDRESS = UNISWAP_PERMIT2_ADDRESS;

/** Permit2 methods used to inspect or establish Universal Router allowances. */
export const permit2Abi = [
  {
    type: "function",
    name: "allowance",
    stateMutability: "view",
    inputs: [
      { name: "owner", type: "address" },
      { name: "token", type: "address" },
      { name: "spender", type: "address" },
    ],
    outputs: [
      { name: "amount", type: "uint160" },
      { name: "expiration", type: "uint48" },
      { name: "nonce", type: "uint48" },
    ],
  },
  {
    type: "function",
    name: "approve",
    stateMutability: "nonpayable",
    inputs: [
      { name: "token", type: "address" },
      { name: "spender", type: "address" },
      { name: "amount", type: "uint160" },
      { name: "expiration", type: "uint48" },
    ],
    outputs: [],
  },
] as const;

/** EIP-712 types for Permit2's one-token, one-spender authorization. */
export const PERMIT2_TYPES = {
  PermitDetails: [
    { name: "token", type: "address" },
    { name: "amount", type: "uint160" },
    { name: "expiration", type: "uint48" },
    { name: "nonce", type: "uint48" },
  ],
  PermitSingle: [
    { name: "details", type: "PermitDetails" },
    { name: "spender", type: "address" },
    { name: "sigDeadline", type: "uint256" },
  ],
} as const;

export interface Permit2SignatureAuthorization {
  chainId: JBChainId;
  token: Address;
  spender: Address;
  amount: bigint;
  expiration: number;
  nonce: number;
  sigDeadline: bigint;
}

export interface Permit2Allowance {
  amount: bigint;
  expiration: number;
  nonce: number;
}

/** Build the exact typed-data payload a wallet signs for PermitSingle. */
export function permit2TypedData(authorization: Permit2SignatureAuthorization) {
  return {
    domain: {
      name: "Permit2" as const,
      chainId: authorization.chainId,
      verifyingContract: PERMIT2_ADDRESS,
    },
    types: PERMIT2_TYPES,
    primaryType: "PermitSingle" as const,
    message: {
      details: {
        token: authorization.token,
        amount: authorization.amount,
        expiration: authorization.expiration,
        nonce: authorization.nonce,
      },
      spender: authorization.spender,
      sigDeadline: authorization.sigDeadline,
    },
  };
}

/** Read an owner's Permit2 allowance, defaulting the spender to Universal Router. */
export async function readPermit2Allowance(
  client: PublicClient,
  {
    chainId,
    owner,
    token,
    spender,
  }: {
    chainId: JBChainId;
    owner: Address;
    token: Address;
    spender?: Address;
  },
): Promise<Permit2Allowance> {
  const resolvedSpender =
    spender ?? uniswapV4Deployment(chainId)?.universalRouter;
  if (!resolvedSpender) {
    throw new Error(
      `No supported Uniswap Universal Router on chain ${chainId}.`,
    );
  }
  const [amount, expiration, nonce] = await client.readContract({
    address: PERMIT2_ADDRESS,
    abi: permit2Abi,
    functionName: "allowance",
    args: [owner, token, resolvedSpender],
  });
  return { amount, expiration, nonce };
}

/** Whether an allowance is too small or expires inside the safety buffer. */
export function permit2AllowanceNeedsRefresh({
  allowance,
  amount,
  now = Math.floor(Date.now() / 1000),
  expirationBufferSeconds = 1_800,
}: {
  allowance: Pick<Permit2Allowance, "amount" | "expiration">;
  amount: bigint;
  now?: number;
  expirationBufferSeconds?: number;
}): boolean {
  if (expirationBufferSeconds < 0) {
    throw new Error("expirationBufferSeconds cannot be negative.");
  }
  return (
    allowance.amount < amount ||
    allowance.expiration <= now + expirationBufferSeconds
  );
}

/** Read whether an ERC-20 needs a fresh Permit2 authorization for Universal Router. */
export async function needsPermit2Approval({
  client,
  chainId,
  owner,
  token,
  amount,
  now,
  expirationBufferSeconds,
}: {
  client: PublicClient;
  chainId: JBChainId;
  owner: Address;
  token: Address;
  amount: bigint;
  now?: number;
  expirationBufferSeconds?: number;
}): Promise<boolean> {
  if (token.toLowerCase() === NATIVE_TOKEN.toLowerCase()) return false;
  const allowance = await readPermit2Allowance(client, {
    chainId,
    owner,
    token,
  });
  return permit2AllowanceNeedsRefresh({
    allowance,
    amount,
    now,
    expirationBufferSeconds,
  });
}

/**
 * Prefer a gasless Permit2 signature for EOAs. Contract wallets generally need
 * the on-chain Permit2 approval path unless their integration handles ERC-1271.
 */
export function shouldUsePermit2Signature({
  needsApproval,
  walletLookupSettled,
  walletBytecode,
  isSafe,
}: {
  needsApproval: boolean;
  walletLookupSettled: boolean;
  walletBytecode?: Hex;
  isSafe: boolean;
}): boolean {
  const isContract = !!walletBytecode && walletBytecode !== "0x";
  return needsApproval && walletLookupSettled && !isContract && !isSafe;
}

/** Fall back only for wallets that cannot sign typed data, never on rejection. */
export function permit2SignatureNeedsOnchainFallback(error: unknown): boolean {
  const messages: string[] = [];
  let current: unknown = error;
  for (let depth = 0; current && depth < 5; depth += 1) {
    if (typeof current !== "object") break;
    const value = current as Record<string, unknown>;
    for (const key of ["code", "shortMessage", "message", "details"]) {
      if (value[key] !== undefined) messages.push(String(value[key]));
    }
    current = value.cause;
  }
  const text = messages.join(" ").toLowerCase();
  if (/user rejected|rejected the request|denied|4001/.test(text)) return false;
  return /(^|\s)-32602(\s|$)|(^|\s)-32601(\s|$)|(^|\s)4200(\s|$)|invalid parameters|method .*not supported|unsupported method|typed data.*not supported/.test(
    text,
  );
}

import { JB_CHAINS } from "../constants.js";

export const BENDYSTRAW_TIMEOUT_MS = 15_000;
export const MAX_BENDYSTRAW_RESPONSE_BYTES = 5 * 1024 * 1024;
export const BENDYSTRAW_PROJECT_REF_BATCH_SIZE = 200;
export const BENDYSTRAW_CACHE_TTL_MS = {
  live: 15_000,
  standard: 30_000,
  stable: 60_000,
} as const;

const RETRY_DELAYS_MS = [250, 750] as const;
const RETRYABLE_STATUSES = new Set([408, 429, 500, 502, 503, 504]);

export type BendystrawFilter = Record<string, unknown>;
export type BendystrawNetwork = "mainnet" | "testnet";
export type BendystrawCachePolicy = keyof typeof BENDYSTRAW_CACHE_TTL_MS;
export type BendystrawValidator<T> = (value: unknown) => value is T;

export type BendystrawNetworkSelection = {
  chainId?: number;
  defaultNetwork?: BendystrawNetwork;
  network?: BendystrawNetwork;
  variables?: unknown;
};

export type BendystrawEndpoints = {
  mainnet: string;
  testnet: string;
};

export type BendystrawProjectRef = {
  chainId: number;
  projectId: number;
  version?: number;
};

export type BendystrawProjectRow = {
  chainId?: unknown;
  projectId?: unknown;
  version?: unknown;
};

export class BendystrawRequestError extends Error {
  constructor(
    message: string,
    readonly status?: number,
  ) {
    super(message);
    this.name = "BendystrawRequestError";
  }
}

/**
 * The internal per-attempt request timeout elapsed.
 *
 * It exists so a timeout can be told apart from a caller cancel: both abort the
 * same `AbortController`, and without a distinct reason the timeout surfaces as
 * a bare `AbortError` indistinguishable from `options.signal` firing. Bendystraw
 * is known to spike to 5-13 s, so treating its timeout as a deliberate cancel
 * turned the most likely transient failure into a hard first-attempt error.
 */
export class BendystrawTimeoutError extends Error {
  constructor(readonly timeoutMs: number) {
    super(`Bendystraw request timed out after ${timeoutMs}ms`);
    this.name = "BendystrawTimeoutError";
  }
}

export type BendystrawRequestOptions<
  TResult = unknown,
  TVariables extends object = Record<string, never>,
> = {
  fetch?: typeof fetch;
  maxResponseBytes?: number;
  operationName?: string;
  retryDelaysMs?: readonly number[];
  signal?: AbortSignal;
  timeoutMs?: number;
  validateData?: BendystrawValidator<TResult>;
  validateVariables?: BendystrawValidator<TVariables>;
};

function collectBendystrawChainIds(
  value: unknown,
  chainIds: Set<number>,
  depth = 0,
): void {
  if (value === null || typeof value !== "object") return;
  if (depth > 12) {
    throw new TypeError("Bendystraw variables exceed the nesting limit");
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      collectBendystrawChainIds(item, chainIds, depth + 1);
    }
    return;
  }
  for (const [key, item] of Object.entries(value)) {
    if (key === "chainId" || key === "chainId_in") {
      const candidates = Array.isArray(item) ? item : [item];
      for (const candidate of candidates) {
        const chainId =
          typeof candidate === "string" && candidate.trim()
            ? Number(candidate)
            : candidate;
        if (!Number.isSafeInteger(chainId) || Number(chainId) <= 0) {
          throw new TypeError(`Invalid Bendystraw ${key}`);
        }
        chainIds.add(Number(chainId));
      }
    } else {
      collectBendystrawChainIds(item, chainIds, depth + 1);
    }
  }
}

function networkForChainId(chainId: number): BendystrawNetwork {
  const metadata = JB_CHAINS[chainId as keyof typeof JB_CHAINS];
  if (!metadata) {
    throw new TypeError(`Unsupported Bendystraw chain ID: ${chainId}`);
  }
  return metadata.chain.testnet ? "testnet" : "mainnet";
}

/**
 * Resolve the Bendystraw network for an operation from every chain selector in
 * its variables. Unknown chains, mixed networks, and explicit contradictions
 * fail closed instead of silently querying the wrong index.
 */
export function resolveBendystrawNetwork(
  selection: BendystrawNetworkSelection = {},
): BendystrawNetwork {
  const chainIds = new Set<number>();
  if (selection.chainId !== undefined) {
    if (!Number.isSafeInteger(selection.chainId) || selection.chainId <= 0) {
      throw new TypeError("Invalid Bendystraw chainId");
    }
    chainIds.add(selection.chainId);
  }
  collectBendystrawChainIds(selection.variables, chainIds);

  const inferred = new Set(
    [...chainIds].map((chainId) => networkForChainId(chainId)),
  );
  if (inferred.size > 1) {
    throw new TypeError(
      "A Bendystraw request cannot mix mainnet and testnet chains",
    );
  }
  const inferredNetwork = [...inferred][0];
  if (
    selection.network &&
    inferredNetwork &&
    selection.network !== inferredNetwork
  ) {
    throw new TypeError(
      `Bendystraw network ${selection.network} conflicts with ${inferredNetwork} chain variables`,
    );
  }
  return (
    selection.network ??
    inferredNetwork ??
    selection.defaultNetwork ??
    "mainnet"
  );
}

/** Normalize a Bendystraw origin or endpoint to one canonical GraphQL URL. */
export function normalizeBendystrawEndpoint(endpoint: string): string {
  const url = new URL(endpoint);
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    throw new TypeError("Bendystraw endpoint must use HTTP or HTTPS");
  }
  url.pathname = `${url.pathname
    .replace(/\/graphql\/?$/u, "")
    .replace(/\/$/u, "")}/graphql`;
  url.search = "";
  url.hash = "";
  return url.toString();
}

/** Select and normalize the endpoint for the operation's resolved network. */
export function selectBendystrawEndpoint(
  endpoints: BendystrawEndpoints,
  selection: BendystrawNetworkSelection = {},
): string {
  return normalizeBendystrawEndpoint(
    endpoints[resolveBendystrawNetwork(selection)],
  );
}

export function isBendystrawRecord(
  value: unknown,
): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

/** Build a lightweight guard for the required root fields of an operation. */
export function bendystrawDataHasFields<const TKey extends string>(
  ...fields: readonly TKey[]
): BendystrawValidator<Record<TKey, unknown>> {
  return (value): value is Record<TKey, unknown> =>
    isBendystrawRecord(value) &&
    fields.every((field) => Object.prototype.hasOwnProperty.call(value, field));
}

export function assertBendystrawData<T>(
  value: unknown,
  validator: BendystrawValidator<T>,
  operationName = "Bendystraw operation",
): T {
  if (!validator(value)) {
    throw new BendystrawRequestError(
      `${operationName} returned invalid data`,
      502,
    );
  }
  return value;
}

export function assertBendystrawVariables<T extends object>(
  value: unknown,
  validator: BendystrawValidator<T>,
  operationName = "Bendystraw operation",
): T {
  if (!validator(value)) {
    throw new BendystrawRequestError(
      `${operationName} received invalid variables`,
      400,
    );
  }
  return value;
}

/**
 * Shared freshness vocabulary for clients. The transport does not cache.
 *
 * - `live`: balances, activity, and mutable project state.
 * - `standard`: lists, search, and aggregate charts.
 * - `stable`: metadata and historical records.
 *
 * Writes should invalidate affected reads. An indexer failure may fall back to
 * an authoritative RPC read only when the fallback preserves the same scoped
 * identity; failures must never be converted into zero or empty data.
 */
export function bendystrawCacheTtl(policy: BendystrawCachePolicy): number {
  return BENDYSTRAW_CACHE_TTL_MS[policy];
}

function normalizeProjectRef(
  ref: BendystrawProjectRef,
): Required<BendystrawProjectRef> {
  const version = ref.version ?? 6;
  if (
    !Number.isSafeInteger(ref.chainId) ||
    ref.chainId <= 0 ||
    !Number.isSafeInteger(ref.projectId) ||
    ref.projectId <= 0 ||
    !Number.isSafeInteger(version) ||
    version <= 0
  ) {
    throw new TypeError("Invalid Bendystraw project reference");
  }
  return { chainId: ref.chainId, projectId: ref.projectId, version };
}

/**
 * Build an explicit conjunction for one versioned deployment. Keeping each
 * identity field in its own `AND` member prevents accidental project/chain
 * cross-products when multiple deployments are combined with `OR`.
 */
export function bendystrawProjectRefFilter(
  ref: BendystrawProjectRef,
): BendystrawFilter {
  const normalized = normalizeProjectRef(ref);
  return {
    AND: [
      { chainId: normalized.chainId },
      { projectId: normalized.projectId },
      { version: normalized.version },
    ],
  };
}

/**
 * Build an exact filter for one or more deployments. An empty list throws
 * instead of silently producing a broad, unscoped indexer query.
 */
export function bendystrawProjectRefsFilter(
  refs: readonly BendystrawProjectRef[],
): BendystrawFilter {
  const unique = new Map<string, Required<BendystrawProjectRef>>();
  for (const ref of refs) {
    const normalized = normalizeProjectRef(ref);
    unique.set(
      `${normalized.chainId}:${normalized.projectId}:${normalized.version}`,
      normalized,
    );
  }
  const filters = [...unique.values()].map(bendystrawProjectRefFilter);
  if (filters.length === 0) {
    throw new TypeError(
      "At least one Bendystraw project reference is required",
    );
  }
  return filters.length === 1 ? filters[0] : { OR: filters };
}

/**
 * Build independently queryable exact-deployment filters without handing an
 * indexer one unbounded `OR`. Empty input produces no queries; malformed refs
 * still fail closed.
 */
export function bendystrawProjectRefsFilters(
  refs: readonly BendystrawProjectRef[],
  batchSize = BENDYSTRAW_PROJECT_REF_BATCH_SIZE,
): BendystrawFilter[] {
  if (!Number.isSafeInteger(batchSize) || batchSize <= 0) {
    throw new TypeError("batchSize must be a positive safe integer");
  }

  const unique = new Map<string, Required<BendystrawProjectRef>>();
  for (const ref of refs) {
    const normalized = normalizeProjectRef(ref);
    unique.set(
      `${normalized.chainId}:${normalized.projectId}:${normalized.version}`,
      normalized,
    );
  }

  const normalized = [...unique.values()];
  const batches: BendystrawFilter[] = [];
  for (let index = 0; index < normalized.length; index += batchSize) {
    batches.push({
      OR: normalized
        .slice(index, index + batchSize)
        .map(bendystrawProjectRefFilter),
    });
  }
  return batches;
}

/**
 * Verify that an indexer row belongs to one of the requested deployments.
 * Use this at the response boundary as defense in depth against stale schemas,
 * permissive filters, and indexer regressions.
 */
export function matchesBendystrawProjectRef(
  row: BendystrawProjectRow,
  refs: readonly BendystrawProjectRef[],
): boolean {
  const chainId = Number(row.chainId);
  const projectId = Number(row.projectId);
  const version = Number(row.version);
  if (
    !Number.isSafeInteger(chainId) ||
    !Number.isSafeInteger(projectId) ||
    !Number.isSafeInteger(version)
  ) {
    return false;
  }
  return refs.some((ref) => {
    const normalized = normalizeProjectRef(ref);
    return (
      chainId === normalized.chainId &&
      projectId === normalized.projectId &&
      version === normalized.version
    );
  });
}

async function readBoundedBody(
  response: Response,
  maxResponseBytes: number,
): Promise<Uint8Array> {
  const declaredSize = Number(response.headers.get("content-length") ?? 0);
  if (Number.isFinite(declaredSize) && declaredSize > maxResponseBytes) {
    await response.body?.cancel();
    throw new BendystrawRequestError(
      "Bendystraw response exceeds the size limit",
      502,
    );
  }
  if (!response.headers.get("content-type")?.toLowerCase().includes("json")) {
    await response.body?.cancel();
    throw new BendystrawRequestError(
      "Bendystraw returned an invalid content type",
      502,
    );
  }
  if (!response.body) return new Uint8Array();

  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > maxResponseBytes) {
        await reader.cancel("Bendystraw response exceeds the size limit");
        throw new BendystrawRequestError(
          "Bendystraw response exceeds the size limit",
          502,
        );
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const body = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return body;
}

function abortName(error: unknown): string | undefined {
  return error instanceof Error ? error.name : undefined;
}

function delay(milliseconds: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

/**
 * Execute a bounded, timeout-protected Bendystraw GraphQL request.
 *
 * The helper retries only transient transport failures — including its own
 * per-attempt {@link BendystrawTimeoutError}. GraphQL errors, invalid
 * envelopes, invalid content types, oversized bodies, and caller cancellation
 * (`options.signal`) fail closed without being retried.
 *
 * @throws {BendystrawTimeoutError} When every attempt timed out.
 */
export async function requestBendystraw<
  TResult,
  TVariables extends object = Record<string, never>,
>(
  endpoint: string,
  query: string,
  variables: TVariables,
  options: BendystrawRequestOptions<TResult, TVariables> = {},
): Promise<TResult> {
  const fetchImpl = options.fetch ?? fetch;
  const maxResponseBytes =
    options.maxResponseBytes ?? MAX_BENDYSTRAW_RESPONSE_BYTES;
  const retryDelaysMs = options.retryDelaysMs ?? RETRY_DELAYS_MS;
  const timeoutMs = options.timeoutMs ?? BENDYSTRAW_TIMEOUT_MS;

  if (!Number.isSafeInteger(maxResponseBytes) || maxResponseBytes <= 0) {
    throw new TypeError("maxResponseBytes must be a positive safe integer");
  }
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    throw new TypeError("timeoutMs must be positive");
  }
  if (options.validateVariables) {
    assertBendystrawVariables(
      variables,
      options.validateVariables,
      options.operationName,
    );
  }

  for (let attempt = 0; ; attempt += 1) {
    const controller = new AbortController();
    const abort = () => controller.abort(options.signal?.reason);
    options.signal?.addEventListener("abort", abort, { once: true });
    const timeoutReason = new BendystrawTimeoutError(timeoutMs);
    const timeout = setTimeout(
      () => controller.abort(timeoutReason),
      timeoutMs,
    );
    try {
      if (options.signal?.aborted) abort();
      const response = await fetchImpl(endpoint, {
        method: "POST",
        headers: {
          Accept: "application/graphql-response+json, application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          query,
          variables,
          ...(options.operationName
            ? { operationName: options.operationName }
            : {}),
        }),
        signal: controller.signal,
      });

      if (
        RETRYABLE_STATUSES.has(response.status) &&
        attempt < retryDelaysMs.length
      ) {
        await response.body?.cancel();
      } else {
        const bytes = await readBoundedBody(response, maxResponseBytes);
        let envelope: {
          data?: TResult;
          errors?: Array<{ message?: unknown }>;
        };
        try {
          envelope = JSON.parse(
            new TextDecoder().decode(bytes),
          ) as typeof envelope;
        } catch {
          throw new BendystrawRequestError(
            "Bendystraw returned invalid JSON",
            502,
          );
        }
        if (!response.ok) {
          throw new BendystrawRequestError(
            `Bendystraw request failed (${response.status})`,
            response.status,
          );
        }
        const message = envelope.errors?.find(
          (error) => typeof error?.message === "string",
        )?.message;
        if (envelope.errors?.length) {
          throw new BendystrawRequestError(
            typeof message === "string"
              ? message.slice(0, 500)
              : "Bendystraw query failed",
            502,
          );
        }
        if (!Object.prototype.hasOwnProperty.call(envelope, "data")) {
          throw new BendystrawRequestError(
            "Bendystraw response is missing data",
            502,
          );
        }
        const data = envelope.data as TResult;
        return options.validateData
          ? assertBendystrawData(
              data,
              options.validateData,
              options.operationName,
            )
          : data;
      }
    } catch (error) {
      // The internal timeout is a transient transport failure, so it retries.
      // Only a CALLER cancel fails closed — hence the distinct abort reason.
      const timedOut =
        controller.signal.reason === timeoutReason ||
        error === timeoutReason ||
        error instanceof BendystrawTimeoutError;
      const cancelled =
        !timedOut &&
        (options.signal?.aborted ||
          abortName(error) === "AbortError" ||
          abortName(error) === "TimeoutError");
      if (
        cancelled ||
        error instanceof BendystrawRequestError ||
        attempt >= retryDelaysMs.length
      ) {
        // Surface the timeout as itself rather than as an opaque `AbortError`.
        throw timedOut ? timeoutReason : error;
      }
    } finally {
      clearTimeout(timeout);
      options.signal?.removeEventListener("abort", abort);
    }
    await delay(retryDelaysMs[attempt]);
  }
}

import { Address, ContractFunctionArgs, PublicClient } from "viem";
import { revDeployerAbi, revOwnerAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { JBAccountingContext } from "./terminals.js";
import { v6Address } from "./types.js";

type RevDeployArgs = ContractFunctionArgs<
  typeof revDeployerAbi,
  "payable",
  "deployFor"
>;

type RevDeployArgs6 = Extract<
  RevDeployArgs,
  readonly [unknown, unknown, unknown, unknown, unknown, unknown]
>;

type RevDeployArgs4 = Extract<
  RevDeployArgs,
  readonly [unknown, unknown, unknown, unknown]
>;

/**
 * A revnet's full configuration: its token description (name/ticker/uri and
 * the salt that fixes the ERC-20's deterministic address), base currency
 * (either a token-keyed currency or a well-known `JBCurrencyIds` id such as
 * ETH=1 or USD=2), operator, and stage configurations.
 */
export type REVConfig = RevDeployArgs4[1];

/**
 * One stage of a revnet's lifecycle. See `buildRevnetStageConfig` for the
 * field encodings.
 */
export type REVStageConfig = REVConfig["stageConfigurations"][number];

/**
 * An auto-issuance: tokens minted without payment when a stage starts, to a
 * beneficiary on a specific chain. `count` is an 18-decimal fixed point.
 */
export type REVAutoIssuance = REVStageConfig["autoIssuances"][number];

/**
 * Sucker deployment configuration for a revnet (same shape the omnichain
 * deployer takes; build with `parseSuckerDeployerConfig(..., { version: 6 })`).
 */
export type REVSuckerDeploymentConfig = RevDeployArgs4[3];

/**
 * Configuration for deploying a tiered 721 hook alongside a revnet.
 */
export type REVDeploy721TiersHookConfig = RevDeployArgs6[4];

/**
 * A croptop allowed-post configuration: which 721 categories third parties
 * may post to, and at what minimum price/supply.
 */
export type REVCroptopAllowedPost = RevDeployArgs6[5][number];

/**
 * Ruleset `extraMetadata` bit 2: allows `REVDeployer.deploySuckersFor` to extend
 * the revnet to new chains while the stage is active (the deployer checks
 * `(metadata >> 2) & 1`). `extraMetadata` is folded into the revnet's immutable
 * encoded-configuration hash, so a stage without this bit can NEVER be extended —
 * there is no later fix.
 */
export const REV_METADATA_ALLOW_SUCKER_DEPLOYMENT = 1 << 2;

/**
 * Build a `REVStageConfig` (spec-exact encodings, documented per field).
 *
 * ENCODINGS:
 * - `startsAtOrAfter`: ABSOLUTE unix timestamp (uint48), strictly increasing
 *   across stages. For omnichain revnets, compute every stage's start as a
 *   cumulative offset from ONE shared deploy-start timestamp so the stage
 *   list is byte-identical on every chain.
 * - `splitPercent`: the share of issuance routed to splits, out of 10,000
 *   (e.g. 3,800 = 38%).
 * - `splits[].percent`: each split's share of the SPLIT BUCKET (not of total
 *   issuance), out of 1e9; the group must total exactly 1e9 — use
 *   `fillSplitPercents`.
 * - `initialIssuance`: tokens minted per unit of base currency, 18-decimal
 *   fixed point (uint112). The exported `RULESET_WEIGHT_INHERIT` sentinel
 *   (1n) means "inherit the previous stage's issuance with its cuts applied";
 *   zero means genuine zero issuance.
 * - `issuanceCutFrequency`: seconds between issuance cuts (should be >= 1
 *   day; it becomes the stage's ruleset duration).
 * - `issuanceCutPercent`: how much issuance drops each period, out of 1e9
 *   (`MAX_WEIGHT_CUT_PERCENT`; e.g. 20% = 200,000,000).
 * - `cashOutTaxRate`: out of 10,000 (`MAX_CASH_OUT_TAX_RATE`). Any non-zero
 *   rate makes EVERY cash out incur the 2.5% protocol fee; zero-tax cash outs
 *   still pay it on `min(reclaimAmount, feeFreeSurplusOf)`, which is often
 *   but not always zero.
 * - `extraMetadata`: extra metadata bits forwarded to hooks.
 *   {@link REV_METADATA_ALLOW_SUCKER_DEPLOYMENT} (bit 2) is ORed in by default
 *   so the revnet stays extendable to new chains; pass
 *   `allowSuckerDeployment: false` to opt out PERMANENTLY for the stage.
 */
export function buildRevnetStageConfig(args: {
  startsAtOrAfter: number;
  initialIssuance: bigint;
  autoIssuances?: readonly REVAutoIssuance[];
  splitPercent?: number;
  splits?: REVStageConfig["splits"];
  issuanceCutFrequency?: number;
  issuanceCutPercent?: number;
  cashOutTaxRate?: number;
  extraMetadata?: number;
  /**
   * Whether `REVDeployer.deploySuckersFor` may extend the revnet to new chains
   * during this stage. Defaults to TRUE — a stage without the bit is
   * un-extendable forever, since stages are immutable once deployed.
   */
  allowSuckerDeployment?: boolean;
}): REVStageConfig {
  const extraMetadata =
    args.allowSuckerDeployment === false
      ? (args.extraMetadata ?? 0)
      : (args.extraMetadata ?? 0) | REV_METADATA_ALLOW_SUCKER_DEPLOYMENT;
  return {
    startsAtOrAfter: args.startsAtOrAfter,
    autoIssuances: args.autoIssuances ?? [],
    splitPercent: args.splitPercent ?? 0,
    splits: args.splits ?? [],
    initialIssuance: args.initialIssuance,
    issuanceCutFrequency: args.issuanceCutFrequency ?? 0,
    issuanceCutPercent: args.issuanceCutPercent ?? 0,
    cashOutTaxRate: args.cashOutTaxRate ?? 0,
    extraMetadata,
  };
}

/**
 * Build a `REVDeployer.deployFor` transaction request deploying a new revnet
 * (or a 721-shop revnet when `tiered721Config` is given).
 *
 * Deploying a NEW revnet (`revnetId` 0n) is payable and must send EXACTLY the
 * current project creation fee — read it with `getProjectCreationFee` on the
 * same chain. Deploying for an EXISTING project must send no value (the
 * deployer reverts otherwise), so `creationFee` is ignored in that case.
 * For omnichain revnets, send one transaction per chain with an identical
 * `config` (shared description salt, shared absolute stage starts) and a
 * shared sucker salt.
 *
 * @param args.config The revnet configuration; see {@link REVConfig}.
 * @param args.accountingContexts The tokens the revnet accepts as reserves;
 * see `buildAccountingContext`.
 * @param args.suckerConfig Cross-chain sucker configuration (empty
 * `deployerConfigurations` for a single-chain revnet); build with
 * `parseSuckerDeployerConfig(chainId, chainIds, assets, { version: 6 })`.
 * @param args.revnetId The revnet to deploy for. Defaults to 0n (create a
 * NEW revnet).
 * @param args.tiered721Config Optional tiered 721 hook config — switches to
 * the 6-arg overload.
 * @param args.allowedPosts Croptop posting rules (only used with
 * `tiered721Config`). Defaults to none.
 */
export function buildDeployRevnetTx(args: {
  chainId: JBChainId;
  config: REVConfig;
  accountingContexts: readonly JBAccountingContext[];
  suckerConfig: REVSuckerDeploymentConfig;
  creationFee?: bigint;
  revnetId?: bigint;
  tiered721Config?: REVDeploy721TiersHookConfig;
  allowedPosts?: readonly REVCroptopAllowedPost[];
}) {
  const address = v6Address("REVDeployer", args.chainId);
  const revnetId = args.revnetId ?? 0n;

  // An omnichain revnet whose stages lack the sucker-deployment bit can never
  // be extended to new chains (or have failed sucker deploys retried): stages
  // are immutable and `deploySuckersFor` checks the CURRENT stage's bit. Refuse
  // to encode that foot-gun — `buildRevnetStageConfig` sets the bit by default.
  if (args.suckerConfig.deployerConfigurations.length > 0) {
    const blockedStage = args.config.stageConfigurations.findIndex(
      (stage) =>
        (Number(stage.extraMetadata) & REV_METADATA_ALLOW_SUCKER_DEPLOYMENT) ===
        0,
    );
    if (blockedStage !== -1) {
      throw new Error(
        `Stage ${blockedStage} does not set REV_METADATA_ALLOW_SUCKER_DEPLOYMENT ` +
          `(extraMetadata bit 2), so this cross-chain revnet could never deploy ` +
          `suckers during that stage — permanently. Build stages with ` +
          `buildRevnetStageConfig (which sets the bit by default), or OR the bit ` +
          `into extraMetadata.`,
      );
    }
  }

  // The deployer forwards msg.value to `JBProjects.createFor` for new revnets and
  // reverts on any value when initializing an existing project.
  if (revnetId === 0n && args.creationFee === undefined) {
    throw new Error("creationFee is required when deploying a new revnet");
  }
  const value = revnetId === 0n ? (args.creationFee as bigint) : 0n;

  if (args.tiered721Config) {
    return {
      chainId: args.chainId,
      address,
      abi: revDeployerAbi,
      functionName: "deployFor" as const,
      args: [
        revnetId,
        args.config,
        args.accountingContexts,
        args.suckerConfig,
        args.tiered721Config,
        args.allowedPosts ?? [],
      ] as const,
      value,
    };
  }
  return {
    chainId: args.chainId,
    address,
    abi: revDeployerAbi,
    functionName: "deployFor" as const,
    args: [
      revnetId,
      args.config,
      args.accountingContexts,
      args.suckerConfig,
    ] as const,
    value,
  };
}

/**
 * Build a `REVOwner.autoIssueFor` transaction request minting a stage's
 * pending auto-issuance to its beneficiary. Callable by anyone once the
 * stage has started; mints whatever `amountToAutoIssue` reports.
 */
export function buildAutoIssueTx(args: {
  chainId: JBChainId;
  revnetId: bigint;
  stageId: bigint;
  beneficiary: Address;
}) {
  return {
    chainId: args.chainId,
    address: v6Address("REVOwner", args.chainId),
    abi: revOwnerAbi,
    functionName: "autoIssueFor" as const,
    args: [args.revnetId, args.stageId, args.beneficiary] as const,
  };
}

/**
 * Read the token count (18-decimal fixed point) still available to
 * auto-issue to a beneficiary for a given stage.
 */
export async function getAmountToAutoIssue(
  client: PublicClient,
  args: {
    chainId: JBChainId;
    revnetId: bigint;
    stageId: bigint;
    beneficiary: Address;
  },
): Promise<bigint> {
  return client.readContract({
    address: v6Address("REVOwner", args.chainId),
    abi: revOwnerAbi,
    functionName: "amountToAutoIssue",
    args: [args.revnetId, args.stageId, args.beneficiary],
  });
}

/**
 * Read the timestamp when cash outs become available to the revnet's
 * participants (only set when an EXISTING revnet deploys onto a new
 * network). 0 or a past timestamp means cash outs are live. Loans are also
 * unavailable while the delay is active.
 */
export async function getCashOutDelay(
  client: PublicClient,
  args: { chainId: JBChainId; revnetId: bigint },
): Promise<bigint> {
